(function (app) {
  "use strict";

  app.encyclopediaCards = app.encyclopediaCards || {};

  Object.assign(app.encyclopediaCards, {
    "01": {
      id: "01",
      number: "01",
      special: false,
      title: "天地開闢",
      deityName: "天之御中主神",
      reading: "あめのみなかぬしのかみ",
      deityNote: "",
      meaningTitle: "天地開闢",
      meaning: "まだ何も形になっていないところから、すべてが始まる。\n新しい世界、新しい可能性、物事の根源を表すカード。",
      myth: "『古事記』は、天地が初めて現れた「天地初発」の場面から始まります。\n\nそのとき、高天原に最初に現れた神が天之御中主神でした。\n\n続いて、高御産巣日神、神産巣日神が現れます。\nこの三柱は後世「造化三神」と呼ばれ、万物が生まれていく最初の段階に位置する神々として捉えられています。\n\nしかし、天之御中主神について『古事記』が語るのは非常にわずかです。\n最初に現れたのち、「独神」となり、姿を隠したと記されています。\n\n国を造ったとも、人間に何かを授けたとも書かれていません。\n\nただ、世界の物語が始まる、その最初に存在する神なのです。",
      connectionHeading: "なぜ「天地開闢」と結びつくのか",
      connection: "天之御中主神は、完成した世界の中で働く神ではありません。\n\nまだ国も、海も、山も、神々の物語さえ始まっていない時に現れた存在です。\n\nだから「國護り」では、天之御中主神を\n\n「すべてが始まる前の一点」\n\nとして捉えています。\n\n何も決まっていないということは、何にでもなれるということ。\n\n「天地開闢」は、完成された答えを示すカードではなく、\nこれから新しい世界が開かれていく可能性そのものを表します。",
      sacredSites: [
        { mark: "★", name: "サムハラ神社 奥之宮", location: "岡山県津山市" },
        { mark: "★", name: "サムハラ神社", location: "大阪府大阪市" },
      ],
      sacredSitesNote: "サムハラ神社では、天之御中主大神・高皇産霊大神・神皇産霊大神の三柱を主祭神として祀っています。\n三柱は、万象を生み出す「造化三神」として伝えられています。",
      en: {
        title: "The Beginning of Heaven and Earth", deityName: "Amenominakanushi no Kami", deityNote: "", meaningTitle: "The Beginning of Heaven and Earth",
        meaning: "The moment when everything begins from a place where nothing has yet taken form.\n\nThis card represents a new world, new possibilities, and the origin from which all things emerge.",
        myth: "The Kojiki begins with the moment known as the first emergence of Heaven and Earth.\n\nAt that moment, the first deity to appear in Takamagahara, the Plain of High Heaven, was Amenominakanushi no Kami.\n\nAfterward came Takamimusubi no Kami and Kamimusubi no Kami.\n\nThese three deities later came to be known collectively as the Three Deities of Creation, beings associated with the earliest stage in which existence itself began to unfold.\n\nYet the Kojiki tells us very little about Amenominakanushi.\n\nThe deity appears alone and then becomes hidden from view.\n\nThere are no stories describing Amenominakanushi creating the land or directly giving something to humankind.\n\nAnd yet, this deity stands at the very beginning—\n\npresent before the story of the world truly begins.",
        connectionHeading: "Why This Deity Represents “The Beginning of Heaven and Earth”",
        connection: "Amenominakanushi does not act within an already completed world.\n\nThis deity appears before there are nations, seas, mountains, or even the great stories of the gods.\n\nFor that reason, in Kunimamori, Amenominakanushi represents:\n\n“the single point before everything begins.”\n\nWhen nothing has yet been decided, anything is still possible.\n\n“The Beginning of Heaven and Earth” does not offer a finished answer.\n\nIt represents pure possibility—the opening of a world that has yet to take shape.",
        sacredSites: [{ mark: "★", name: "Samuhara Shrine Okunomiya", location: "Tsuyama, Okayama" }, { mark: "★", name: "Samuhara Shrine", location: "Osaka" }], sacredSitesNote: "",
      },
    },
    "02": {
      id: "02",
      number: "02",
      special: false,
      title: "創造",
      deityName: "伊邪那岐命・伊邪那美命",
      reading: "いざなぎのみこと・いざなみのみこと",
      deityNote: "",
      meaningTitle: "創造",
      meaning: "まだ存在しないものを、この世界に生み出す力。\n二つのものを結び合わせ、形あるものへと育てていくことを表す。",
      myth: "天地が開かれ、次々と神々が現れたのち、伊邪那岐命と伊邪那美命が誕生します。\n\n二柱は天津神から、漂っている国土を整え、固めることを命じられます。\n\n天の浮橋に立った二柱は、天沼矛を海へ差し下ろしてかき回しました。\n\n矛を引き上げた時、その先から滴り落ちた潮が積もり重なってできたのが淤能碁呂島です。\n\n二柱はそこへ降り、夫婦となります。\n\nそして淡路島をはじめとする島々を生み、さらに海、山、川、風、木、火など、この世界を構成する多くの神々を生んでいきました。\n\n『古事記』における日本の国土と自然世界は、伊邪那岐命と伊邪那美命の「国生み」「神生み」によって、次第に具体的な形を与えられていきます。",
      connectionHeading: "なぜ「創造」と結びつくのか",
      connection: "天之御中主神が「始まりそのもの」なら、伊邪那岐命と伊邪那美命は、\n\n「始まりに形を与えた神々」\n\nといえます。\n\n二柱は、男女という異なる存在が出会い、結び合うことによって、島々や自然、神々を次々と生み出しました。\n\nそのため「國護り」の「創造」は、単なる発想やアイデアではなく、\n\n自分の中にあるものを、現実の世界へ形として生み出していく力\n\nを表しています。",
      sacredSites: [
        { mark: "★", name: "伊弉諾神宮", location: "兵庫県淡路市" },
        { mark: "○", name: "多賀大社", location: "滋賀県犬上郡" },
        { mark: "○", name: "白山比咩神社", location: "石川県白山市" },
      ],
      sacredSitesNote: "",
      en: {
        title: "Creation", deityName: "Izanagi no Mikoto & Izanami no Mikoto", deityNote: "", meaningTitle: "Creation",
        meaning: "The power to bring something into existence that did not exist before.\n\nThis card represents the joining of different forces and the process of giving an idea, relationship, or possibility a tangible form.",
        myth: "After Heaven and Earth had begun to unfold and many deities had appeared, Izanagi no Mikoto and Izanami no Mikoto came into being.\n\nThe heavenly deities entrusted the two with a task:\n\nto form and solidify the drifting land below.\n\nStanding upon the Floating Bridge of Heaven, they lowered the heavenly jeweled spear into the sea and stirred the waters.\n\nWhen they lifted the spear, drops of brine fell from its tip and accumulated to form Onogoro Island.\n\nThe two descended to the island and became husband and wife.\n\nTogether, they gave birth to the islands of Japan, beginning with Awaji.\n\nThey then brought forth many deities associated with the natural world—deities of the sea, mountains, rivers, wind, trees, fire, and more.\n\nIn the Kojiki, the land and natural world gradually take concrete form through the acts known as the Birth of the Land and the Birth of the Gods.",
        connectionHeading: "Why These Deities Represent “Creation”",
        connection: "If Amenominakanushi represents the beginning itself, Izanagi and Izanami are the deities who:\n\n“gave form to that beginning.”\n\nThrough the meeting and joining of two different beings, islands, nature, and countless deities came into existence.\n\nFor this reason, “Creation” in Kunimamori means more than simply having an idea.\n\nIt represents:\n\nbringing what exists within you into the world and giving it tangible form.",
        sacredSites: [{ mark: "★", name: "Izanagi Jingu", location: "Awaji, Hyogo" }, { mark: "○", name: "Taga Taisha", location: "Shiga" }, { mark: "○", name: "Shirayama Hime Jinja", location: "Hakusan, Ishikawa" }], sacredSitesNote: "",
      },
    },
    "03": {
      id: "03",
      number: "03",
      special: false,
      title: "直感",
      deityName: "月読命",
      reading: "つくよみのみこと",
      deityNote: "",
      meaningTitle: "直感",
      meaning: "目に見える情報だけではなく、静かな感覚から答えを受け取ること。\n理屈になる前の気づき、内なる感覚を表す。",
      myth: "月読命は、伊邪那岐命が黄泉国から帰還し、穢れを清めるため禊を行った時に生まれた神です。\n\n伊邪那岐命が左目を洗った時に天照大御神、\n右目を洗った時に月読命、\n鼻を洗った時に須佐之男命が誕生しました。\n\nこの三柱は「三貴子」と呼ばれます。\n\n伊邪那岐命は、天照大御神には高天原を、月読命には夜之食国を、須佐之男命には海原を治めるよう命じました。\n\n『古事記』では、この後の月読命についてほとんど物語が語られません。\n\n一方、『日本書紀』の異伝には、月夜見尊が天照大神の命を受けて保食神のもとへ赴く物語があります。\n\nただしこれは『古事記』とは異なる系統の伝承であり、月読命について語る際には区別する必要があります。",
      connectionHeading: "なぜ「直感」と結びつくのか",
      connection: "月読命を「直感」と結びつけるのは、神話本文に「直感の神」と記されているからではありません。\n\n「國護り」では、\n\n太陽の光のようにはっきり見えるものではなく、夜の静けさの中で感じ取るもの\n\nという月の性質から、この意味を与えています。\n\n月は自ら強く輝くのではなく、暗闇の中で淡い光を映します。\n\nそれは、\n\n「なぜかわからないけれど、こちらだと感じる」\n\nという感覚にも似ています。\n\nこのカードは、外側の声よりも、\n自分の内側に浮かぶ小さな感覚を見逃さないことを示しています。",
      sacredSites: [
        { mark: "★", name: "伊勢神宮 月讀宮", location: "三重県伊勢市" },
        { mark: "○", name: "伊勢神宮 月夜見宮", location: "三重県伊勢市" },
        { mark: "○", name: "月読神社", location: "京都府京都市" },
      ],
      sacredSitesNote: "",
      en: {
        title: "Intuition", deityName: "Tsukuyomi no Mikoto", deityNote: "", meaningTitle: "Intuition",
        meaning: "Receiving an answer through quiet inner awareness rather than relying only on what can be seen or logically explained.\n\nThis card represents subtle knowing—the feeling that arises before it can be put into words.",
        myth: "Tsukuyomi no Mikoto was born when Izanagi no Mikoto purified himself after returning from Yomi, the land of the dead.\n\nWhen Izanagi washed his left eye, Amaterasu Omikami was born.\n\nWhen he washed his right eye, Tsukuyomi no Mikoto was born.\n\nAnd when he washed his nose, Susanoo no Mikoto appeared.\n\nTogether, these three are known as the Three Noble Children.\n\nIzanagi entrusted Takamagahara to Amaterasu, the realm of night to Tsukuyomi, and the seas to Susanoo.\n\nThe Kojiki says very little about Tsukuyomi after this point.\n\nOther traditions, including versions recorded in the Nihon Shoki, contain additional stories about the moon deity, but these belong to different textual traditions and should be distinguished from the Kojiki account.",
        connectionHeading: "Why This Deity Represents “Intuition”",
        connection: "The myths do not explicitly call Tsukuyomi a deity of intuition.\n\nThis meaning in Kunimamori comes from the symbolic nature of the moon itself.\n\nUnlike the bright clarity of the sun, moonlight reveals things softly within darkness.\n\nIt resembles the quiet inner sense that says:\n\n“I cannot explain why, but this feels like the right direction.”\n\nIntuition is not always loud or logical.\n\nSometimes the answer arrives as a faint feeling before the mind can explain it.\n\nThis card reminds you not to overlook the quiet signals rising from within.",
        sacredSites: [{ mark: "★", name: "Tsukiyomi-no-miya, Ise Jingu", location: "Ise, Mie" }, { mark: "○", name: "Tsukiyomi-no-miya, Geku", location: "Ise, Mie" }, { mark: "○", name: "Tsukiyomi Shrine", location: "Kyoto" }], sacredSitesNote: "",
      },
    },
    "04": {
      id: "04",
      number: "04",
      special: false,
      title: "意志",
      deityName: "建御雷神",
      reading: "たけみかづちのかみ",
      deityNote: "鹿島神宮では「武甕槌大神」と表記されます。",
      meaningTitle: "意志",
      meaning: "自分の決めた方向を貫く力。\n迷いを越え、覚悟をもって物事に向き合う強さを表す。",
      myth: "建御雷神は、『古事記』では伊邪那岐命が火神・迦具土神を斬った際、その刀に付いた血から生まれた神々の一柱として登場します。\n\nのちに重要な役割を担うのが「国譲り神話」です。\n\n高天原の神々は、葦原中国を天照大御神の御子孫が治めるべきだと考え、建御雷神を地上へ遣わします。\n\n建御雷神は出雲の伊那佐の小浜へ降り立ち、大国主神に国を譲る意思があるか問いかけました。\n\n大国主神は、息子たちの判断を仰ぎます。\n\n事代主神は国譲りを受け入れますが、もう一柱の建御名方神は建御雷神へ力比べを挑みます。\n\nしかし建御名方神は敗れ、最終的に大国主神も国を譲ることを承諾しました。\n\nこうして建御雷神は、葦原中国平定という大きな使命を成し遂げます。",
      connectionHeading: "なぜ「意志」と結びつくのか",
      connection: "建御雷神の強さは、単なる武力だけではありません。\n\n国譲り神話で与えられた使命は、\n\n「葦原中国を平定すること」\n\nでした。\n\n建御雷神はその役目から退かず、交渉し、必要な場面では力を示し、最後まで使命を成し遂げています。\n\nそのため「國護り」では建御雷神を、\n\n決めた方向へ力を集める「意志」\n\nの象徴としました。\n\nこれは「絶対に他人に譲らない」という頑固さではありません。\n\n自分が本当に進むと決めた時に、\n迷いに力を分散させず、一つの方向へ自分を定めることを表します。",
      sacredSites: [
        { mark: "★", name: "鹿島神宮", location: "茨城県鹿嶋市" },
        { mark: "○", name: "春日大社", location: "奈良県奈良市" },
        { mark: "○", name: "鹽竈神社", location: "宮城県塩竈市" },
      ],
      sacredSitesNote: "",
      en: {
        title: "Will", deityName: "Takemikazuchi no Kami", deityNote: "At Kashima Jingu, the deity is also written as Takemikazuchi no Okami.", meaningTitle: "Will",
        meaning: "The strength to remain committed to the direction you have chosen.\n\nThis card represents determination, resolve, and the ability to gather your energy toward one path rather than allowing hesitation to scatter it.",
        myth: "In the Kojiki, Takemikazuchi appears among the deities born from the blood of the fire god Kagutsuchi after Izanagi struck him down.\n\nLater, Takemikazuchi plays a central role in the myth known as the Transfer of the Land.\n\nThe heavenly deities decided that Ashihara-no-Nakatsukuni, the earthly realm, should be governed by the descendants of Amaterasu.\n\nTakemikazuchi was sent to the land of Izumo.\n\nThere, he confronted Okuninushi no Kami and asked whether he would surrender the land.\n\nOkuninushi first deferred to his sons.\n\nKotoshironushi accepted the transfer.\n\nAnother son, Takeminakata, challenged Takemikazuchi to a contest of strength.\n\nTakeminakata was defeated, and ultimately Okuninushi agreed to relinquish the land.\n\nTakemikazuchi thus fulfilled the difficult mission entrusted to him.",
        connectionHeading: "Why This Deity Represents “Will”",
        connection: "Takemikazuchi’s strength is not simply physical power.\n\nHis mission was clear:\n\nto bring the Transfer of the Land to completion.\n\nHe did not abandon that purpose.\n\nHe negotiated, demonstrated strength when necessary, and carried his task through to the end.\n\nFor this reason, Kunimamori associates Takemikazuchi with:\n\nthe will to gather your strength and direct it toward what you have chosen.\n\nThis does not mean stubbornly refusing to listen to anyone else.\n\nIt means that once you truly decide where you must go, you stop scattering your energy among endless hesitation.",
        sacredSites: [{ mark: "★", name: "Kashima Jingu", location: "Kashima, Ibaraki" }, { mark: "○", name: "Kasuga Taisha", location: "Nara" }, { mark: "○", name: "Shiogama Jinja", location: "Shiogama, Miyagi" }], sacredSitesNote: "",
      },
    },
    "05": {
      id: "05",
      number: "05",
      special: false,
      title: "機会",
      deityName: "天宇受売命",
      reading: "あめのうずめのみこと",
      deityNote: "「天鈿女命」とも表記されます。",
      meaningTitle: "機会",
      meaning: "閉ざされていた状況に、新しい動きが生まれる瞬間。\n目の前に現れたきっかけをつかみ、流れを変えることを表す。",
      myth: "天宇受売命が最もよく知られるのが「天岩戸神話」です。\n\n須佐之男命の行いに心を痛めた天照大御神は、天岩戸へ籠もってしまいました。\n\n太陽神が姿を隠したことで、高天原も葦原中国も闇に包まれ、さまざまな災いが起こります。\n\n困った八百万の神々は天安河原に集まり、天照大御神を岩戸から出す方法を考えました。\n\nそこで重要な役目を担ったのが天宇受売命です。\n\n天宇受売命が神懸かりして舞うと、八百万の神々は一斉に笑いました。\n\n岩戸の外があまりに賑やかなため、天照大御神は、\n\n「自分が隠れているのに、なぜ皆が笑っているのだろう」\n\nと不思議に思い、岩戸を少し開きます。\n\nその瞬間を逃さず、天手力男神が天照大御神を岩戸の外へ導き、世界に再び光が戻りました。\n\n天宇受売命の舞は、完全に閉ざされていた状況に、\n\n最初の小さな隙間を生み出した出来事\n\nだったのです。",
      connectionHeading: "なぜ「機会」と結びつくのか",
      connection: "天宇受売命自身が岩戸を力ずくで開いたわけではありません。\n\n彼女がしたのは、\n\n状況が動き出す「きっかけ」を作ること\n\nでした。\n\n笑いが起きる。\n天照大御神が気になる。\n岩戸がわずかに開く。\n\nその小さな変化を、他の神々がつなぎ、最後には世界へ光が戻ります。\n\n「機会」も同じです。\n\n大きな変化は、最初から完成した形で現れるとは限りません。\n\n偶然の出会い、誘い、ふとした興味、わずかな変化。\n\nそれが、閉じていた流れを変える入口になることがあります。\n\nこのカードは、\n\n目の前に生まれた小さな隙間を見逃さないこと\n\nを教えています。",
      sacredSites: [
        { mark: "★", name: "椿岸神社", location: "三重県鈴鹿市" },
        { mark: "○", name: "佐瑠女神社", location: "三重県伊勢市" },
        { mark: "○", name: "大田神社", location: "京都府京都市" },
      ],
      sacredSitesNote: "",
      en: {
        title: "Opportunity", deityName: "Ame-no-Uzume no Mikoto", deityNote: "Also written as Ame-no-Uzume-no-Mikoto or Ame-no-Uzume.", meaningTitle: "Opportunity",
        meaning: "The moment when movement begins within a situation that had seemed completely closed.\n\nThis card represents noticing a small opening, responding to it, and allowing that opening to change the course of events.",
        myth: "Ame-no-Uzume is best known for her role in the myth of Ama-no-Iwato, the Heavenly Rock Cave.\n\nDistressed by the actions of Susanoo no Mikoto, Amaterasu Omikami withdrew into the rock cave and sealed herself inside.\n\nBecause the sun goddess had disappeared, both Takamagahara and the earthly realm were plunged into darkness, and calamities began to spread.\n\nThe countless deities gathered at Amano-Yasukawara and discussed how they might bring Amaterasu back into the world.\n\nAme-no-Uzume took on a crucial role.\n\nEntering a divine trance, she began to dance.\n\nHer performance caused the assembled gods to burst into laughter.\n\nHearing the celebration outside, Amaterasu became curious.\n\nShe wondered:\n\n“Why are they laughing when the world should be dark because I am hidden?”\n\nShe opened the rock door slightly to look outside.\n\nThat tiny opening was enough.\n\nAt the right moment, Ame-no-Tajikarao no Kami pulled Amaterasu from the cave, and light returned to the world.\n\nAme-no-Uzume did not force the rock cave open herself.\n\nInstead, she created:\n\nthe first opening through which change could begin.",
        connectionHeading: "Why This Deity Represents “Opportunity”",
        connection: "Ame-no-Uzume did not solve everything alone.\n\nWhat she created was a turning point.\n\nLaughter arose.\n\nAmaterasu became curious.\n\nThe rock door opened slightly.\n\nThe other deities responded.\n\nAnd eventually, light returned to the world.\n\nOpportunity often works in the same way.\n\nA great change does not always arrive as a complete solution.\n\nIt may appear as:\n\na chance meeting,\nan invitation,\na sudden curiosity,\nor one small shift in circumstances.\n\nThat small opening may become the entrance to an entirely different future.\n\nThis card reminds you:\n\nDo not overlook the small opening that has appeared before you.",
        sacredSites: [{ mark: "★", name: "Tsubakikishi Jinja", location: "Suzuka, Mie" }, { mark: "○", name: "Sarume Jinja", location: "Ise, Mie" }, { mark: "○", name: "Ota Jinja", location: "Kyoto" }], sacredSitesNote: "",
      },
    },
    "06": {
      en: {
        title: "Choice", deityName: "Monju Bosatsu", deityNote: "", meaningTitle: "Choice",
        meaning: "The ability to recognize what truly matters among several possible paths.\n\nThis card represents choosing with wisdom rather than being carried away by fear, emotion, or confusion.",
        myth: "Monju Bosatsu is a bodhisattva who represents wisdom in Buddhism.\n\nIn Japan, Monju has long been revered as a figure of wisdom and insight.\n\nMonju is often depicted holding a sword in the right hand.\n\nThis is not a weapon used to harm others.\n\nIt symbolizes the sword of wisdom—the ability to cut through ignorance, confusion, and the things that prevent us from seeing clearly.\n\nMonju is also frequently shown riding a lion.\n\nAt Abe Monju-in in Nara, Monju Bosatsu is enshrined as part of a group known as the “Monju Crossing the Sea,” accompanied by four attendants.\n\nThe wisdom of Monju is not simply about knowing many facts.\n\nIt is the wisdom to see into the essence of a situation and understand what truly matters.",
        connectionHeading: "Why This Deity Represents “Choice”",
        connection: "When making a choice, the mind can easily become crowded with thoughts such as:\n\n“What if I fail?”\n“What will benefit me most?”\n“What will other people think?”\n\nBut sometimes what is truly needed is not more options.\n\nIt is the ability to recognize:\n\n“What is most important to me right now?”\n\nThe sword of Monju symbolizes the wisdom to separate what matters from what does not.\n\nFor this reason, in Kunimamori, Monju Bosatsu represents:\n\nthe wisdom to discern the path that is truly right for you.\n\nA real choice begins when you stop asking others to decide for you and become clear about what you value.",
        sacredSites: [{ mark: "★", name: "Abe Monju-in", location: "Sakurai, Nara" }, { mark: "○", name: "Chion-ji", location: "Miyazu, Kyoto" }, { mark: "○", name: "Monjusen-ji", location: "Kunisaki, Oita" }], sacredSitesNote: "",
      },
      id: "06",
      number: "06",
      special: false,
      title: "選択",
      deityName: "文殊菩薩",
      reading: "もんじゅぼさつ",
      deityNote: "",
      meaningTitle: "選択",
      meaning: "複数の道の中から、本当に必要なものを見極めること。\n感情や迷いだけに流されず、智慧によって進むべき方向を選ぶことを表す。",
      myth: "文殊菩薩は、仏教において「智慧」を象徴する菩薩です。\n\n「三人寄れば文殊の知恵」という言葉でも知られるように、日本では古くから智慧の仏として広く信仰されてきました。\n\n文殊菩薩の像にはさまざまな姿がありますが、右手に智慧の剣を持つ姿で表されることがあります。\n\nこの剣は、物理的に何かを斬るためのものではありません。\n\n迷いや無知、物事を正しく見ることを妨げるものを断ち切る「智慧」を象徴するものとされます。\n\nまた、獅子に乗る姿もよく知られています。\n\n奈良県の安倍文殊院では、獅子に乗った文殊菩薩を中心に四人の脇侍を従え、海を渡る「渡海文殊」の姿が本尊として祀られています。\n\n文殊菩薩の智慧とは、単に多くの知識を持つことではありません。\n\n目の前の物事を正しく見抜き、本質を知るための智慧です。",
      connectionHeading: "なぜ「選択」と結びつくのか",
      connection: "何かを選ぶ時、私たちはしばしば、\n\n「失敗したくない」\n「こちらの方が得かもしれない」\n「人からどう思われるだろう」\n\nといった思いに揺れます。\n\nけれど、本当に必要なのは選択肢を増やすことではなく、\n\n「今の自分にとって何が大切なのか」\n\nを見極めることなのかもしれません。\n\n文殊菩薩の智慧の剣は、迷いそのものを消すのではなく、\n迷いの中に入り込んだ余計なものを切り分け、本質を見る智慧を象徴します。\n\nそのため「國護り」では、\n\n智慧によって道を見極める力\n\nとして「選択」のカードに文殊菩薩を重ねています。\n\n正しい答えを誰かに決めてもらうのではなく、\n自分の中で何を大切にするのかを明らかにする。\n\nそこから、本当の選択が始まります。",
      sacredSites: [
        { mark: "★", name: "安倍文殊院", location: "奈良県桜井市" },
        { mark: "○", name: "智恩寺", location: "京都府宮津市" },
        { mark: "○", name: "文殊仙寺", location: "大分県国東市" },
      ],
      sacredSitesNote: "安倍文殊院の本尊は文殊菩薩で、快慶作の国宝「渡海文殊群像」として知られています。\n智恩寺も古くから文殊信仰の霊場として知られ、天橋立とともに信仰を集めてきました。",
    },
    "07": {
      en: {
        title: "Decision", deityName: "Kusanagi-no-Tsurugi", deityNote: "Also known as:\nAme-no-Murakumo-no-Tsurugi\n\nIt is one of the Three Sacred Treasures of Japan.", meaningTitle: "Decision",
        meaning: "The act of ending hesitation and determining the direction in which you will move.\n\nThis card represents making a clear judgment even in times of danger or uncertainty, and crossing the line from indecision into action.",
        myth: "The origin of Kusanagi-no-Tsurugi appears in the myth of Susanoo no Mikoto and the defeat of the eight-headed serpent Yamata-no-Orochi.\n\nAfter Susanoo defeated the serpent, he cut into its tail and discovered a sword hidden inside.\n\nThat sword was Ame-no-Murakumo-no-Tsurugi.\n\nSusanoo later presented the sword to Amaterasu Omikami.\n\nIn time, the sacred sword was passed down and eventually came into the possession of Yamato Takeru.\n\nBefore Yamato Takeru departed on his campaign toward eastern Japan, Yamato-hime gave him the sacred sword.\n\nDuring the journey, enemies lured him into a field and set fire to the surrounding grass.\n\nTrapped by the flames, Yamato Takeru drew the sacred sword and cut down the grass around him.\n\nHe then used fire of his own to turn the flames back toward his enemies and escaped the danger.\n\nAccording to tradition, it was from this event that the sword came to be known as Kusanagi-no-Tsurugi, “the Grass-Cutting Sword.”\n\nLater, Yamato Takeru left the sword with Miyazu-hime in Owari.\n\nAfter his death, the sword came to be enshrined at Atsuta, which became the foundation of Atsuta Jingu.",
        connectionHeading: "Why This Sacred Sword Represents “Decision”",
        connection: "The important part of this story is not simply that Yamato Takeru possessed a powerful sword.\n\nIt is that, when surrounded by fire and given no obvious way out, he made a decision.\n\nHe cut the grass.\nHe created a counterfire.\nHe opened a path through danger.\n\nHe did not wait until everything felt safe.\n\nHe acted in the middle of uncertainty.\n\nA decision does not always come after fear disappears.\n\nSometimes decision means drawing a line and saying:\n\n“From here, I will go this way.”\n\nFor this reason, in Kunimamori, Kusanagi-no-Tsurugi represents:\n\nthe power to cut through hesitation and determine your direction.",
        sacredSites: [{ mark: "★", name: "Atsuta Jingu", location: "Nagoya, Aichi" }, { mark: "○", name: "Hikami Anego Jinja", location: "Nagoya, Aichi" }, { mark: "○", name: "Yaizu Jinja", location: "Yaizu, Shizuoka" }], sacredSitesNote: "",
      },
      id: "07",
      number: "07",
      special: false,
      title: "決断",
      deityName: "草薙神剣",
      reading: "くさなぎのみつるぎ",
      deityNote: "別名・天叢雲剣\nあめのむらくものつるぎ\n\n三種の神器の一つとされる神剣です。",
      meaningTitle: "決断",
      meaning: "迷い続ける状態を終わらせ、行くべき方向を定めること。\n危機や変化の中でも、自ら判断し、一線を越えて進む力を表す。",
      myth: "草薙神剣の起源は、須佐之男命による八岐大蛇退治の神話にあります。\n\n須佐之男命が八岐大蛇を退治し、その尾を斬った時、一振りの剣が現れました。\n\nそれが「天叢雲剣」です。\n\n須佐之男命は、この神剣を天照大御神へ献上します。\n\nのちに神剣は天孫へ伝えられ、さらに時代を経て日本武尊の手へ渡ります。\n\n日本武尊が東国へ向かう際、伊勢の倭姫命から授けられたものの一つが、この天叢雲剣でした。\n\n東征の途中、日本武尊は敵の策略によって草原へ誘い込まれ、周囲から火を放たれます。\n\n逃げ道を失った日本武尊は、神剣を抜いて周囲の草を薙ぎ払い、さらに火打石で向かい火を放ちました。\n\n炎の流れを逆転させることで、危機を脱したと伝えられています。\n\nこの出来事から、天叢雲剣は「草薙神剣」と呼ばれるようになったとされています。\n\nその後、日本武尊は神剣を尾張の宮簀媛命のもとに残して旅立ちます。\n\n日本武尊の死後、宮簀媛命によって神剣が熱田の地に祀られたことが、熱田神宮の創祀につながったと伝えられています。",
      connectionHeading: "なぜ「決断」と結びつくのか",
      connection: "草薙神剣の物語で重要なのは、\n\n剣を持っていたことだけではありません。\n\n火に囲まれ、逃げ場を失った瞬間に、\n日本武尊自身が何をするかを決めたことです。\n\n草を薙ぐ。\n向かい火を放つ。\nそして窮地を突破する。\n\n状況が整ってから進んだのではなく、\n危機のただ中で判断し、自ら道を作りました。\n\n「決断」とは、迷いが完全になくなることではありません。\n\nむしろ、答えが完全には見えない中で、\n\n「ここからはこちらへ進む」\n\nと一線を引くことでもあります。\n\nそのため「國護り」では草薙神剣を、\n\n迷いを断ち、進む方向を定める「決断」\n\nの象徴としています。\n\n剣が草を薙いだように、\n決断とは、自分の前を塞いでいたものを断ち、次の一歩が通る道を作ることなのです。",
      sacredSites: [
        { mark: "★", name: "熱田神宮", location: "愛知県名古屋市" },
        { mark: "○", name: "氷上姉子神社", location: "愛知県名古屋市" },
        { mark: "○", name: "焼津神社", location: "静岡県焼津市" },
      ],
      sacredSitesNote: "熱田神宮は、三種の神器の一つである草薙神剣を御神体として祀る神社です。\n\n氷上姉子神社は日本武尊の妃・宮簀媛命を祀り、草薙神剣が熱田へ遷される以前に祀られていた地として、熱田神宮創祀に深く関わります。\n\n焼津神社では、日本武尊が草薙神剣によって火攻めの危機を脱した伝承が現在も伝えられています。",
    },
    "08": {
      en: {
        title: "Action", deityName: "Sarutahiko no Okami", deityNote: "In the Kojiki, the name is written as Sarutabiko no Kami.", meaningTitle: "Action",
        meaning: "Moving from thought into actual movement.\n\nThis card represents taking the first step in the direction you have chosen and opening the path through what you do.",
        myth: "Sarutahiko no Okami is best known for his role in the myth of the Descent of the Heavenly Grandson.\n\nWhen Ninigi no Mikoto was preparing to descend from Takamagahara to the earthly realm, a mysterious deity appeared at the crossroads between Heaven and Earth.\n\nHis presence was so powerful that he illuminated both the heavenly realm above and the earthly realm below.\n\nAmaterasu Omikami and Takagi no Kami sent Ame-no-Uzume to ask who he was.\n\nThe deity identified himself as Sarutabiko no Kami.\n\nHe explained that he had come to guide Ninigi along the path of descent.\n\nSarutahiko then went ahead of Ninigi and served as the guide for the heavenly descent.\n\nAfterward, Ame-no-Uzume accompanied Sarutahiko toward his home in the region associated with Ise.\n\nBecause of this myth, Sarutahiko has long been revered as a deity of guidance and path-opening.",
        connectionHeading: "Why This Deity Represents “Action”",
        connection: "Sarutahiko did not simply point from a distance and say:\n\n“The path is over there.”\n\nHe stood at the road and moved ahead.\n\nHe did not only know the direction.\n\nHe acted within it.\n\nNo matter how good an idea or plan may be, reality does not change until movement begins.\n\nThe moment you take the first step, what existed only in your mind begins to connect with the real world.\n\nFor this reason, in Kunimamori, Sarutahiko no Okami represents:\n\nthe act of actually walking the path before you.\n\nYou do not need to wait until everything is perfect.\n\nThe next part of the road may only become visible after you begin moving.",
        sacredSites: [{ mark: "★", name: "Sarutahiko Jinja", location: "Ise, Mie" }, { mark: "★", name: "Tsubaki Grand Shrine", location: "Suzuka, Mie" }, { mark: "○", name: "Futami Okitama Jinja", location: "Ise, Mie" }], sacredSitesNote: "",
      },
      id: "08",
      number: "08",
      special: false,
      title: "行動",
      deityName: "猿田彦大神",
      reading: "さるたひこのおおかみ",
      deityNote: "『古事記』では「猿田毘古神」と記されます。",
      meaningTitle: "行動",
      meaning: "考えているだけの状態から、実際に動き始めること。\n進むべき方向へ一歩を踏み出し、自分の力で道を開いていくことを表す。",
      myth: "猿田彦大神が登場する代表的な物語が「天孫降臨」です。\n\n天照大御神の孫である邇邇芸命が、高天原から地上へ降りようとしていた時のこと。\n\n天地の境となる天の八衢に、\n高天原から葦原中国までを照らす不思議な神が立っていました。\n\nそこで天照大御神と高木神は、天宇受売命を遣わし、その神が何者であるか尋ねさせます。\n\nその神こそ猿田毘古神でした。\n\n猿田毘古神は、天孫が降臨すると聞き、その道を先導するために迎えに来たのだと告げます。\n\nそして邇邇芸命を先導し、天孫降臨の道を開きました。\n\n天孫を送り届けた後、猿田彦大神は天宇受売命とともに伊勢方面へ向かったと伝えられています。\n\nこの天孫降臨の物語から、猿田彦大神は現在も「みちひらき」「導き」の神として広く信仰されています。",
      connectionHeading: "なぜ「行動」と結びつくのか",
      connection: "猿田彦大神は、\n\n「道はこちらです」\n\nと遠くから教えただけの神ではありません。\n\n自ら道の前に立ち、\n実際に先頭を歩いて天孫を導きました。\n\nつまり、方向を知るだけではなく、\n\nその方向へ実際に進む存在\n\nなのです。\n\nどれほど素晴らしい考えや計画があっても、\n動かなければ現実は変わりません。\n\n最初の一歩を踏み出した瞬間から、\nそれまで頭の中にしかなかったものが現実とつながり始めます。\n\nそのため「國護り」では猿田彦大神を、\n\n道を現実に歩き始める「行動」\n\nの象徴としています。\n\n完璧な準備ができるまで待つのではなく、\n今いる場所から一歩を踏み出す。\n\nその一歩によって、初めて次の道が見えてくるのです。",
      sacredSites: [
        { mark: "★", name: "猿田彦神社", location: "三重県伊勢市" },
        { mark: "★", name: "椿大神社", location: "三重県鈴鹿市" },
        { mark: "○", name: "二見興玉神社", location: "三重県伊勢市" },
      ],
      sacredSitesNote: "猿田彦神社では猿田彦大神を「みちひらきの大神」として祀り、天孫降臨を先導した神として由緒を伝えています。\n\n椿大神社も猿田彦大神を主祭神として祀り、「みちびきの祖神」として厚く信仰されています。",
    },
    "09": {
      en: {
        title: "Passion", deityName: "Hinokagutsuchi no Kami", deityNote: "In the Kojiki, the deity is also referred to by names including:\nHino-Yagihayao no Kami\nHino-Kagabiko no Kami", meaningTitle: "Passion",
        meaning: "A powerful energy rising from within.\n\nThis card represents the heat that drives creation, movement, and transformation.\n\nAt the same time, because intense passion can also harm yourself or others when uncontrolled, this card also asks how you choose to use that energy.",
        myth: "Hinokagutsuchi no Kami is the deity of fire, born near the end of the divine births performed by Izanagi no Mikoto and Izanami no Mikoto.\n\nBut his birth brought great tragedy.\n\nBecause she gave birth to the fire deity, Izanami suffered severe burns and became gravely ill.\n\nEven in her suffering, additional deities were born from her body, but eventually Izanami died.\n\nOvercome by grief and anger, Izanagi drew his sword and struck down Kagutsuchi.\n\nFrom the blood on the sword, several new deities were born, including Takemikazuchi.\n\nAdditional mountain deities were also born from the divided body of Kagutsuchi.\n\nIn other words, the birth and death of Kagutsuchi do not end only in destruction.\n\nAn overwhelming force causes loss, but from that same force, new divine beings emerge.",
        connectionHeading: "Why This Deity Represents “Passion”",
        connection: "Fire warms people.\n\nIt cooks food.\nIt brings light into darkness.\nIt can be used to create and transform.\n\nBut when it escapes control, it can also destroy everything in its path.\n\nThe myth of Kagutsuchi expresses this double nature of fire with extraordinary intensity.\n\nPassion works in much the same way.\n\n“I want to accomplish this.”\n“I want to create this.”\n“I want to go there.”\n\nSuch inner fire can become a tremendous force in life.\n\nBut when passion grows too strong, it can also exhaust you or make you lose sight of everything around you.\n\nFor this reason, in Kunimamori, Hinokagutsuchi no Kami represents:\n\nthe fire of life powerful enough to move reality.\n\nThe important thing is not to extinguish the fire.\n\nIt is to ask:\n\n“What am I choosing to burn this fire for?”\n\nWhen passion is directed wisely, fire becomes a force of creation rather than destruction.",
        sacredSites: [{ mark: "★", name: "Akihasan Hongu Akiha Jinja", location: "Hamamatsu, Shizuoka" }, { mark: "○", name: "Atago Jinja", location: "Kyoto" }], sacredSitesNote: "",
      },
      id: "09",
      number: "09",
      special: false,
      title: "情熱",
      deityName: "火之迦具土神",
      reading: "ひのかぐつちのかみ",
      deityNote: "『古事記』では、\n火之夜藝速男神\n火之炫毘古神\nという名も記されています。",
      meaningTitle: "情熱",
      meaning: "内側から湧き上がる強いエネルギー。\n何かを生み出し、動かし、変えていくための熱を表す。\n\nただし、その力が強すぎれば自分や周囲を傷つけることもあるため、\n情熱をどのように使うかという問いも含むカード。",
      myth: "火之迦具土神は、伊邪那岐命と伊邪那美命による「神生み」の最後に近い場面で誕生する火の神です。\n\nしかし、その誕生は大きな悲劇をもたらしました。\n\n火の神を産んだことで伊邪那美命は大きな火傷を負い、病に伏します。\n\nその苦しみの中で吐瀉物や排泄物などからも新たな神々が生まれますが、やがて伊邪那美命は亡くなってしまいます。\n\n妻の死を嘆いた伊邪那岐命は、怒りと悲しみのあまり十拳剣を抜き、火之迦具土神を斬りました。\n\nすると、その剣についた血から建御雷神をはじめとする神々が生まれ、\nさらに斬られた火之迦具土神の身体からも数多くの山の神々が誕生します。\n\nつまり火之迦具土神の誕生と死は、\n\n破壊だけでは終わりません。\n\n強烈な火の力によって多くのものが失われる一方、\nそこからさらに新たな神々が生まれていくという、\n非常に大きなエネルギーの転換が描かれています。",
      connectionHeading: "なぜ「情熱」と結びつくのか",
      connection: "火は、人を温めます。\n\n食べ物を調理し、\n暗闇を照らし、\nものを作るための力にもなります。\n\nしかし制御を失えば、すべてを焼き尽くす力にもなります。\n\n火之迦具土神の神話には、\nまさにその火の二面性が強烈な形で描かれています。\n\n「情熱」も同じです。\n\n何かを成し遂げたい。\nこれを作りたい。\nここへ行きたい。\n\nそんな内側の熱は、人生を動かす大きな力になります。\n\nけれど、情熱が強すぎると、\n自分自身を疲れさせたり、周囲が見えなくなったりすることもあります。\n\nそのため「國護り」では火之迦具土神を、\n\n現実を動かすほど強い生命の火\n\nとして「情熱」の象徴にしています。\n\n大切なのは火を消すことではありません。\n\nその火を、何のために燃やすのか。\n\n情熱を正しい方向へ使うことで、\n火は破壊ではなく創造の力へと変わっていきます。",
      sacredSites: [
        { mark: "★", name: "秋葉山本宮秋葉神社", location: "静岡県浜松市" },
        { mark: "○", name: "愛宕神社", location: "京都府京都市" },
      ],
      sacredSitesNote: "秋葉山本宮秋葉神社では、火之迦具土大神を御祭神として祀っています。\n\n同社では火を、光・熱・エネルギーをもたらす力である一方、畏れるべき力でもあるものとして捉え、火防・開運の神として信仰しています。",
    },
    "10": {
      en: {
        title: "Progress", deityName: "Ukanomitama no Okami", deityNote: "Also written as:\nUkanomitama no Kami\nUkanomitama no Mikoto", meaningTitle: "Progress",
        meaning: "The stage when what you have planted begins to grow and visible change starts to appear.\n\nThis card represents steady movement forward and the process of developing toward a result.",
        myth: "In the Kojiki, Ukanomitama no Kami appears in the genealogy of Susanoo no Mikoto.\n\nSusanoo took Kamu-Oichi-hime, a daughter of Oyamatsumi no Kami, as his wife.\n\nTheir children included Otoshi no Kami and Ukanomitama no Kami.\n\nThe Kojiki does not tell a long individual story about Ukanomitama.\n\nHowever, the name “Uka” is associated with food, and the deity became closely connected with grain, especially rice.\n\nIn later tradition, Ukanomitama became one of the central deities of Inari worship.\n\nAt Fushimi Inari Taisha, Ukanomitama no Okami is enshrined as one of the principal deities.\n\nRice does not become a harvest the moment a seed is planted.\n\nThe seed sprouts.\nThe seedling grows.\nIt is transplanted into the field.\nIt continues to develop.\nEventually, the grain ripens.\n\nOver time, faith in Ukanomitama became deeply connected with harvest, food, livelihood, and prosperity.",
        connectionHeading: "Why This Deity Represents “Progress”",
        connection: "When we hear the word “progress,” we may imagine a dramatic breakthrough.\n\nBut real progress often begins as something small.\n\nLike a sprout appearing where yesterday there was only soil.\n\nA seed cannot be harvested immediately after it is planted.\n\nIt must sprout.\nTake root.\nGrow little by little.\n\nThe growth of rice and grain associated with Ukanomitama reflects the meaning of progress very naturally.\n\nFor this reason, in Kunimamori, Ukanomitama no Okami represents:\n\nthe stage when something already begun is growing and visible movement starts to appear in reality.\n\nIt is not yet completion.\n\nBut something is clearly different from before.\n\nEven a small visible change can mean that the process has already begun to move forward.",
        sacredSites: [{ mark: "★", name: "Fushimi Inari Taisha", location: "Kyoto" }, { mark: "○", name: "Kasama Inari Jinja", location: "Kasama, Ibaraki" }, { mark: "○", name: "Yutoku Inari Jinja", location: "Kashima, Saga" }], sacredSitesNote: "",
      },
      id: "10",
      number: "10",
      special: false,
      title: "進展",
      deityName: "宇迦之御魂大神",
      reading: "うかのみたまのおおかみ",
      deityNote: "「宇迦之御魂神」「倉稲魂命」などとも表記されます。",
      meaningTitle: "進展",
      meaning: "蒔いたものが育ち、現実に変化が現れ始めること。\n物事が少しずつ前へ進み、成果へ向かって成長していく流れを表す。",
      myth: "宇迦之御魂神は、『古事記』では須佐之男命の系譜の中に登場します。\n\n須佐之男命が、大山津見神の娘である神大市比売を妻とし、\nその間に生まれたのが大年神と宇迦之御魂神です。\n\n『古事記』では、宇迦之御魂神自身の具体的な物語はほとんど語られていません。\n\nしかし、その名前の「ウカ」は食物を意味する言葉と関係すると考えられ、\n古くから穀物、とくに稲の霊と深く結びつく神として信仰されてきました。\n\n『日本書紀』では「倉稲魂命」と記される伝承もあります。\n\n後世、宇迦之御魂大神は稲荷信仰の中心的な神となりました。\n\n伏見稲荷大社では、本殿中央の下社に宇迦之御魂大神が祀られています。\n\n稲は、一粒の種籾を蒔いて終わるものではありません。\n\n芽が出て、\n苗となり、\n田へ植えられ、\n成長し、\nやがて稲穂を実らせます。\n\n宇迦之御魂大神への信仰には、\nそうした食物の実りと、人々の暮らしの繁栄が長く重ねられてきました。",
      connectionHeading: "なぜ「進展」と結びつくのか",
      connection: "「進展」というと、\n突然大きな結果が出ることを想像するかもしれません。\n\nけれど、本当の進展は、\n\n昨日まで見えなかった芽が出ること\n\nのような、小さな変化から始まることがあります。\n\n種を蒔いてすぐに収穫することはできません。\n\n芽が出て、\n根を張り、\n少しずつ伸びていく。\n\n宇迦之御魂大神が象徴する稲や穀物の成長は、\nまさに「進展」という言葉と重なります。\n\nそのため「國護り」では、\n\nすでに始めたことが育ち、現実に動きが現れてくる段階\n\nとして宇迦之御魂大神を「進展」のカードに重ねています。\n\nまだ完成ではありません。\n\nけれど、確かに以前とは違う。\n\n小さくても変化が見えているなら、\n物事はすでに前へ進み始めています。",
      sacredSites: [
        { mark: "★", name: "伏見稲荷大社", location: "京都府京都市" },
        { mark: "○", name: "笠間稲荷神社", location: "茨城県笠間市" },
        { mark: "○", name: "祐徳稲荷神社", location: "佐賀県鹿島市" },
      ],
      sacredSitesNote: "伏見稲荷大社では、宇迦之御魂大神を本殿の中心となる御祭神の一柱として祀っています。\n\n祐徳稲荷神社でも「倉稲魂大神」の名で祀られ、衣食住を司り、生活全般を守護する神として信仰されています。",
    },
    "11": {
      en: {
        title: "Continuity", deityName: "Yasakani-no-Magatama", deityNote: "One of the Three Sacred Treasures of Japan.", meaningTitle: "Continuity",
        meaning: "Continuing what has been started and carrying it forward without breaking the connection.\n\nThis card represents how small acts, repeated and linked together, gradually become something enduring.",
        myth: "The sacred jewel associated with Yasakani-no-Magatama appears in the Kojiki during the myth of Ama-no-Iwato, the Heavenly Rock Cave.\n\nWhen Amaterasu Omikami withdrew into the cave, the countless deities prepared a sacred ritual to bring her back into the world.\n\nAmong the ritual objects was a magnificent strand of sacred jewels made by Tamanooya no Mikoto.\n\nThe Kojiki describes a great cluster of curved jewels, many individual beads joined together into a single sacred ornament.\n\nThe jewels were hung from a sacred sakaki tree together with the mirror and used in the ritual to call Amaterasu out of the cave.\n\nLater, during the Descent of the Heavenly Grandson, the sacred jewels, mirror, and sword were passed on and brought from the heavenly realm to the earth.\n\nIn this way, the sacred jewel was not limited to one single event.\n\nIt was carried forward from the myth of Ama-no-Iwato into the next stage of the divine story.\n\nIn later tradition, Yasakani-no-Magatama came to be regarded as one of the Three Sacred Treasures of Japan.",
        connectionHeading: "Why This Sacred Object Represents “Continuity”",
        connection: "A strand of magatama is not complete with only one bead.\n\nMany individual pieces are joined together to create one form.\n\nEach piece may be small, but when they are connected, they become something greater.\n\nThe sacred jewel used during the Ama-no-Iwato ritual was also carried forward into the story of the Heavenly Descent.\n\nFor this reason, in Kunimamori, Yasakani-no-Magatama represents:\n\nconnecting, inheriting, and continuing without breaking the chain.\n\nContinuity does not require doing something great every single day.\n\nIt may simply mean connecting today’s small effort with tomorrow’s.\n\nOver time, those small links can become something that is not easily lost.",
        sacredSites: [{ mark: "★", name: "Tamanooya Jinja", location: "Hofu, Yamaguchi" }, { mark: "○", name: "Tamatsukuri-yu Jinja", location: "Matsue, Shimane" }], sacredSitesNote: "",
      },
      id: "11", number: "11", special: false, title: "継続", deityName: "八尺瓊勾玉", reading: "やさかにのまがたま",
      deityNote: "三種の神器の一つとされる神宝です。",
      meaningTitle: "継続",
      meaning: "一度始めたことを途切れさせず、次へつないでいくこと。\n小さな積み重ねが連なり、やがて大きな力となって残っていくことを表す。",
      myth: "八尺瓊勾玉につながる玉は、『古事記』の天岩戸神話に登場します。\n\n天照大御神が天岩戸に籠もった時、八百万の神々は、再び天照大御神を外へ招き出すための祭りを準備しました。\n\nその中で玉祖命が作ったのが、\n\n「八尺の勾璁の五百津の御すまるの珠」\n\nと記される、多くの玉を連ねた神聖な玉飾りです。\n\nこれを鏡などとともに榊へ掛け、天照大御神を迎え出す祭祀に用いました。\n\nさらに天孫降臨の場面では、天岩戸で使われた勾玉・鏡・草薙剣が邇邇芸命に伴って地上へ伝えられます。\n\nつまりこの神宝は、一つの出来事だけで役割を終えるのではなく、天岩戸から天孫降臨へと受け継がれていくものとして描かれています。\n\n後世、八尺瓊勾玉は鏡・剣とともに「三種の神器」として語り継がれてきました。",
      connectionHeading: "なぜ「継続」と結びつくのか",
      connection: "勾玉は、一つの玉だけで完結するものではありません。\n\n『古事記』に描かれた玉飾りも、たくさんの玉が連なって一つのものとなる姿でした。\n\n一つひとつは小さくても、\nそれをつなげていくことで形になる。\n\nそして、天岩戸で用いられた神宝は、次の時代を象徴する天孫降臨へと受け継がれていきます。\n\n「國護り」では、この\n\n「つなぐこと、受け継ぐこと、途切れさせないこと」\n\nを「継続」と重ねています。\n\n継続とは、毎回大きなことをすることではありません。\n\n今日の一つを、明日の一つへつなぐ。\n\nその小さな連なりが、やがて簡単には失われないものを作っていきます。",
      sacredSites: [{ mark: "★", name: "玉祖神社", location: "山口県防府市" }, { mark: "○", name: "玉作湯神社", location: "島根県松江市" }], sacredSitesNote: "",
    },
    "12": {
      en: {
        title: "Patience", deityName: "Sukunahikona no Mikoto", deityNote: "In the Kojiki, the name is written as Sukunabikona no Kami.", meaningTitle: "Patience",
        meaning: "Continuing to do what is necessary even when the result does not appear immediately.\n\nThis card represents respecting small steps and allowing time for something to grow.",
        myth: "While Okuninushi no Kami was at the cape of Miho in Izumo, a very small deity came toward him from across the sea.\n\nThe mysterious deity arrived in a tiny boat and wore a small garment.\n\nAt first, no one knew who he was.\n\nWith the help of Kuebiko, his identity was revealed:\n\nhe was Sukunabikona no Kami, a child of Kamimusubi no Kami.\n\nKamimusubi instructed Okuninushi to treat Sukunabikona as a brother and to work together with him in forming and developing the land.\n\nFrom that point, Okuninushi and Sukunabikona worked together in the process of building and establishing Ashihara-no-Nakatsukuni.\n\nAfter their work had progressed, Sukunabikona eventually departed for Tokoyo, the Eternal Land.\n\nIn later tradition, Sukunahikona became strongly associated with medicine, healing, hot springs, and the protection of health.",
        connectionHeading: "Why This Deity Represents “Patience”",
        connection: "The Kojiki does not explicitly call Sukunahikona a deity of patience.\n\nIn Kunimamori, the connection comes from the fact that:\n\nalthough he was a very small deity, he helped carry out the enormous task of building a country.\n\nA nation cannot be completed in a single action.\n\nLand must be developed.\nPeople’s lives must be supported.\nOne thing must be built upon another.\n\nHealing also often requires time.\n\nNot every wound disappears immediately.\n\nSometimes recovery happens little by little.\n\nFor this reason, in Kunimamori, Sukunahikona represents:\n\nthe strength to continue small, necessary actions until the right time arrives.\n\nPatience does not mean silently enduring suffering forever.\n\nIt means continuing to do what you can while allowing change to unfold in its own time.",
        sacredSites: [{ mark: "★", name: "Sukunahikona Jinja", location: "Osaka" }, { mark: "○", name: "Oarai Isosaki Jinja", location: "Oarai, Ibaraki" }, { mark: "○", name: "Sakatsura Isosaki Jinja", location: "Hitachinaka, Ibaraki" }], sacredSitesNote: "",
      },
      id: "12", number: "12", special: false, title: "忍耐", deityName: "少彦名命", reading: "すくなひこなのみこと",
      deityNote: "『古事記』では「少名毘古那神」と記されます。", meaningTitle: "忍耐",
      meaning: "すぐに結果が出なくても、必要なことを積み重ね続ける力。\n小さな歩みを軽んじず、時間をかけて物事を育てていくことを表す。",
      myth: "大国主神が出雲の御大の岬にいた時、海の彼方から非常に小さな神がやってきました。\n\n天の羅摩の船に乗り、小さな皮衣をまとったその神の正体を誰も知りませんでした。\n\n久延毘古の助言によって、その神が神産巣日神の子・少名毘古那神であることが判明します。\n\n神産巣日神は大国主神に、少名毘古那神と兄弟となり、二柱で国を作り固めるよう命じました。\n\nそれから大国主神と少名毘古那神は力を合わせ、葦原中国の国作りを進めていきます。\n\nそして国作りを終えた後、少名毘古那神は常世国へ渡ったと『古事記』は伝えています。\n\n後世、少彦名命は医薬や治病、温泉などとも深く結びつけられました。",
      connectionHeading: "なぜ「忍耐」と結びつくのか",
      connection: "『古事記』に「少彦名命は忍耐の神である」と書かれているわけではありません。\n\n「國護り」で注目したのは、\n\n「小さな神でありながら、大国主神とともに国を作り固めたこと」\n\nです。\n\n国作りは、一度の行動ですべてが完成するものではありません。\n\n土地を整え、人々の暮らしを支え、一つずつ国を形にしていく。\n\nさらに後世、少彦名命が深く結びついた「癒し」も、すぐに結果が出るものばかりではありません。\n\n少しずつ整えていく時間が必要なことがあります。\n\nだから「國護り」では少彦名命を、\n\n「小さな働きを重ねながら、必要なところまで歩み続ける力」\n\nとして「忍耐」と重ねています。\n\n忍耐とは、ただ苦しみを我慢することではありません。\n\n今できることを続けながら、\n変化が訪れる時まで歩みを止めないことなのです。",
      sacredSites: [{ mark: "★", name: "少彦名神社", location: "大阪府大阪市" }, { mark: "○", name: "大洗磯前神社", location: "茨城県大洗町" }, { mark: "○", name: "酒列磯前神社", location: "茨城県ひたちなか市" }], sacredSitesNote: "",
    },
    "13": {
      en: {
        title: "Stability", deityName: "Oyamatsumi no Kami", deityNote: "Also written as:\nOyama-zumi no Kami\nOyama-tsumi no Kami", meaningTitle: "Stability",
        meaning: "Creating a firm foundation within changing circumstances.\n\nThis card represents support, steadiness, and the kind of strength that allows something to continue over time.",
        myth: "Oyamatsumi no Kami was born during the divine births of Izanagi no Mikoto and Izanami no Mikoto and is known as a deity of mountains.\n\nOne especially important story connected with Oyamatsumi involves his daughters, Konohanasakuya-hime and Iwanagahime.\n\nWhen Ninigi no Mikoto fell in love with Konohanasakuya-hime and asked to marry her, Oyamatsumi was delighted.\n\nHe sent not only Konohanasakuya-hime, but also her elder sister Iwanagahime.\n\nHowever, Ninigi sent Iwanagahime back and accepted only Konohanasakuya-hime.\n\nOyamatsumi then explained why he had sent both daughters.\n\nIf Ninigi accepted Iwanagahime,\n\nhis descendants would endure firmly and eternally, like stone.\n\nIf he accepted Konohanasakuya-hime,\n\nhis descendants would flourish beautifully, like blossoms on a tree.\n\nThese blessings had been entrusted to the two sisters.\n\nBecause Iwanagahime was rejected, the Kojiki explains that the lives of the heavenly descendants became limited, like flowers that bloom and eventually fall.",
        connectionHeading: "Why This Deity Represents “Stability”",
        connection: "The connection here is especially direct.\n\nThe blessing Oyamatsumi entrusted to Iwanagahime was:\n\nto endure like stone, firm and unshaken.\n\nA mountain also represents a massive presence rooted in the earth, enduring through time.\n\nFlowers represent beauty and flourishing.\n\nBut for flourishing to continue, it also needs a foundation that does not easily collapse.\n\nFor this reason, in Kunimamori, Oyamatsumi no Kami represents:\n\nthe foundation that supports something over the long term.\n\nStability does not mean that nothing ever changes.\n\nIt means having a place of strength you can return to even when change occurs.\n\nBecause that foundation exists, you can move forward without losing yourself.",
        sacredSites: [{ mark: "★", name: "Oyamazumi Jinja", location: "Imabari, Ehime" }, { mark: "○", name: "Mishima Taisha", location: "Mishima, Shizuoka" }, { mark: "○", name: "Oyama Afuri Jinja", location: "Isehara, Kanagawa" }], sacredSitesNote: "",
      },
      id: "13", number: "13", special: false, title: "安定", deityName: "大山津見神", reading: "おおやまつみのかみ",
      deityNote: "「大山祇神」「大山積神」などとも表記されます。", meaningTitle: "安定",
      meaning: "揺らぎやすい状況の中に、しっかりとした土台を作ること。\n一時的な勢いではなく、長く支え続ける力や安心できる基盤を表す。",
      myth: "大山津見神は、伊邪那岐命・伊邪那美命の神生みによって生まれた山を司る神です。\n\nそして、大山津見神の性質を象徴する非常に重要な物語が、娘である木花之佐久夜毘売と石長比売の神話です。\n\n邇邇芸命が木花之佐久夜毘売を見初め、結婚を申し込むと、大山津見神は大いに喜びました。\n\nそして木花之佐久夜毘売だけではなく、姉の石長比売も一緒に送り出します。\n\nところが邇邇芸命は石長比売を送り返し、木花之佐久夜毘売だけを妻としました。\n\nすると大山津見神は、二人の娘を共に差し出した理由を明かします。\n\n石長比売を妻とすれば、\n天孫の命は岩のように永く揺るがないものとなる。\n\n木花之佐久夜毘売を妻とすれば、\n木の花が咲き栄えるように繁栄する。\n\nそのような誓約を込めて、二柱を送り出したのだというのです。\n\nしかし石長比売が返されたため、天孫の命は花のように限りあるものになった、と『古事記』は説明しています。",
      connectionHeading: "なぜ「安定」と結びつくのか",
      connection: "大山津見神が娘・石長比売に託したものは、\n\n「岩のように揺るがず、永く続くこと」\n\nでした。\n\n山もまた、一朝一夕に生まれて消えるものではなく、大地に根を張る巨大な存在です。\n\n華やかに咲く花には繁栄があります。\n\nけれど、その繁栄を長く支えるためには、動かない土台も必要です。\n\nそのため「國護り」では、山の神である大山津見神を\n\n「何かを長く支え続ける基盤」\n\nとして「安定」と結びつけています。\n\n安定とは、何も変わらないことではありません。\n\n変化が起きても戻ってこられる場所があること。\n\nその土台があるからこそ、安心して次へ進めるのです。",
      sacredSites: [{ mark: "★", name: "大山祇神社", location: "愛媛県今治市大三島" }, { mark: "○", name: "三嶋大社", location: "静岡県三島市" }, { mark: "○", name: "大山阿夫利神社", location: "神奈川県伊勢原市" }], sacredSitesNote: "",
    },
    "14": {
      en: {
        title: "Abundance", deityName: "Toyouke no Omikami", deityNote: "In the Kojiki, the deity appears as Toyouke-bime no Kami.", meaningTitle: "Abundance",
        meaning: "Having what is needed to sustain life, and allowing that nourishment to continue flowing onward.\n\nThis card represents food, harvest, blessings, and the abundance that supports everyday life.",
        myth: "In the Kojiki, when Izanami no Mikoto became gravely ill after giving birth to the fire deity Kagutsuchi, several new deities were born from her body.\n\nAmong the divine lineages that emerged from this event was Wakumusubi no Kami.\n\nToyouke-bime no Kami was born as a child of Wakumusubi.\n\nThe word “uke” is associated with food, and Toyouke became strongly connected with nourishment, grain, and the spiritual power of food.\n\nToday, at the Outer Shrine of Ise Jingu, Toyouke no Omikami is worshipped as the deity responsible for the sacred meals offered to Amaterasu Omikami.\n\nTradition says that around 1,500 years ago, Toyouke no Omikami was invited from the region of Tamba to Ise for this sacred role.\n\nEven today, morning and evening offerings of food are presented to Amaterasu and the other deities in a ritual that has continued for centuries.",
        connectionHeading: "Why This Deity Represents “Abundance”",
        connection: "When people hear the word “abundance,” they may first think of money or possessions.\n\nBut one of the most fundamental forms of abundance is much simpler:\n\nhaving enough to live.\n\nA single grain of rice.\nA cup of water.\nA daily meal.\n\nThese are what allow life to continue.\n\nThe abundance represented by Toyouke no Omikami is not simply about having more and more.\n\nIt is:\n\nreceiving what is needed, being nourished by it, and allowing that nourishment to continue moving through life.\n\nFor this reason, in Kunimamori, Toyouke no Omikami represents:\n\nthe blessing that continually supports life and daily living.\n\nAbundance is not always something far away or extraordinary.\n\nSometimes it is already present in the things that quietly sustain you every day.",
        sacredSites: [{ mark: "★", name: "Toyouke Daijingu, Ise Jingu", location: "Ise, Mie" }, { mark: "○", name: "Moto-Ise Toyouke Daijinja", location: "Fukuchiyama, Kyoto" }], sacredSitesNote: "",
      },
      id: "14", number: "14", special: false, title: "豊かさ", deityName: "豊受大御神", reading: "とようけのおおみかみ",
      deityNote: "『古事記』には「豊宇気毘売神」として登場します。", meaningTitle: "豊かさ",
      meaning: "生きるために必要なものが満たされ、さらに周囲へ巡っていくこと。\n食、実り、恵み、暮らしを支える豊かさを表す。",
      myth: "『古事記』では、伊邪那美命が火之迦具土神を生んで病に伏した際、さまざまな神々が誕生します。\n\nその流れの中で生まれた和久産巣日神の子が、豊宇気毘売神です。\n\n「ウケ」は食物と関係する言葉と考えられており、豊宇気毘売神は食物や稲の霊と結びつく神として捉えられてきました。\n\n現在、伊勢神宮の外宮・豊受大神宮では、豊受大御神を\n\n「天照大御神の御饌都神」\n\nすなわち、神々の食事を司る神としてお祀りしています。\n\n伝承では、約1500年前、天照大御神の御饌都神として丹波から伊勢へ迎えられました。\n\nそして外宮では現在まで、朝と夕の一日二度、天照大御神をはじめとする神々へ食事を奉る日別朝夕大御饌祭が続けられています。",
      connectionHeading: "なぜ「豊かさ」と結びつくのか",
      connection: "「豊かさ」と聞くと、お金や財産を思い浮かべることがあります。\n\nでも、人が生きるために最も根本的に必要なのは、\n\n「食べること」\n\n一粒の米。\n一杯の水。\n日々の食事。\n\nそれがあるから、命をつなぐことができます。\n\n豊受大御神の豊かさは、単に「たくさん持つこと」ではありません。\n\n「必要なものが与えられ、それを受け取り、また次へ巡らせていく豊かさ」\n\nです。\n\nそのため「國護り」では豊受大御神を、\n\n「命と暮らしを満たし続ける恵み」\n\nとして「豊かさ」の象徴にしています。\n\n豊かさは、遠くにある特別な何かだけではありません。\n\nすでに自分を生かしているものに気づいた時、\nそこにも豊かさは存在しています。",
      sacredSites: [{ mark: "★", name: "伊勢神宮 豊受大神宮・外宮", location: "三重県伊勢市" }, { mark: "○", name: "元伊勢豊受大神社", location: "京都府福知山市" }], sacredSitesNote: "",
    },
    "15": {
      en: {
        title: "Fulfillment", deityName: "Konohanasakuya-hime no Mikoto", deityNote: "In the Kojiki, the name appears as Konohana-no-Sakuya-bime.", meaningTitle: "Fulfillment",
        meaning: "The moment when something you have nurtured finally takes form and reaches a result.\n\nThis card represents effort becoming visible, a wish bearing fruit, and something new entering the world.",
        myth: "Konohanasakuya-hime was a daughter of Oyamatsumi no Kami.\n\nAfter descending from the heavenly realm, Ninigi no Mikoto met her at Cape Kasasa and took her as his wife.\n\nSoon afterward, Konohanasakuya-hime became pregnant after only one night together.\n\nNinigi became suspicious.\n\nHe questioned whether a child conceived so quickly could really be his, and wondered whether the child might belong to an earthly deity instead.\n\nTo prove that she was telling the truth, Konohanasakuya-hime performed a solemn pledge.\n\nShe built a birthing hut with no open doorway, entered it, sealed it from within, and set it on fire.\n\nShe declared:\n\n“If these children are not truly the children of Ninigi no Mikoto, they will not be born safely.\n\nBut if they truly are his divine children, they will be born safely even within the flames.”\n\nInside the burning hut, Konohanasakuya-hime safely gave birth to three children.\n\nThrough this act, she proved that her words were true.\n\nThe Kojiki also tells us that Oyamatsumi had given her to Ninigi with the blessing that his descendants would flourish like blossoms blooming on a tree.",
        connectionHeading: "Why This Deity Represents “Fulfillment”",
        connection: "The story of Konohanasakuya-hime contains two powerful images of completion:\n\na flower coming into bloom,\nand new life being safely brought into the world.\n\nA flower is the visible form of something that once existed only as a seed.\n\nIn the same way, Konohanasakuya-hime brought three children safely into the world, even within the extreme trial of fire.\n\nFor this reason, “Fulfillment” in Kunimamori does not simply mean that a wish has come true.\n\nIt means:\n\nwhat you have been nurturing finally becoming visible in the world.\n\nEffort becomes a result.\nA thought becomes reality.\nA new life or future takes form.\n\nThe very name of this goddess, associated with blossoms, beautifully reflects the meaning:\n\nwhat has been growing within you is finally coming into bloom.",
        sacredSites: [{ mark: "★", name: "Fujisan Hongu Sengen Taisha", location: "Fujinomiya, Shizuoka" }, { mark: "○", name: "Kitaguchi Hongu Fuji Sengen Jinja", location: "Fujiyoshida, Yamanashi" }, { mark: "○", name: "Fuji Omuro Sengen Jinja", location: "Fujikawaguchiko, Yamanashi" }], sacredSitesNote: "",
      },
      id: "15", number: "15", special: false, title: "成就", deityName: "木花咲耶姫命", reading: "このはなさくやひめのみこと",
      deityNote: "『古事記』では「木花之佐久夜毘売」と記されます。", meaningTitle: "成就",
      meaning: "育ててきたものが形となり、ひとつの結果へたどり着くこと。\n努力や願いが実を結び、新しいものがこの世界に生まれる瞬間を表す。",
      myth: "木花之佐久夜毘売は、大山津見神の娘です。\n\n天孫降臨した邇邇芸命は笠沙の岬で彼女と出会い、妻に迎えます。\n\nやがて木花之佐久夜毘売は、一夜の契りで身ごもりました。\n\nところが邇邇芸命は、「一夜で身ごもるはずがない。自分の子ではなく、国つ神の子なのではないか」と疑います。\n\n木花之佐久夜毘売は、自らの言葉が真実であることを証明するために誓約を行いました。\n\n戸口のない産屋を造り、その中へ入り、土で塞ぎます。\n\nそして、\n\n「もしこの子が邇邇芸命の子でなければ無事には生まれない。天つ神の御子であるなら、どれほど火が燃えても無事に生まれる」\n\nという趣旨の誓いを立て、自ら産屋へ火を放ちました。\n\n激しい炎の中で、木花之佐久夜毘売は無事に三柱の御子を産みます。\n\nその出産によって、子どもたちが邇邇芸命の御子であることを証明しました。\n\nまた、大山津見神は木花之佐久夜毘売について、\n\n「木の花が咲き栄えるように栄える」\n\nという意味を込めて邇邇芸命へ送り出したと『古事記』は伝えています。",
      connectionHeading: "なぜ「成就」と結びつくのか",
      connection: "木花咲耶姫命の神話には、\n\n「花が咲くこと」\nそして\n「命を無事に産み出すこと」\n\nという二つの「完成」が描かれています。\n\n花は、種のままでは見ることのできなかったものが、ついに外へ現れた姿です。\n\nそして木花咲耶姫命は、炎という極限の状況の中で三柱の御子を無事に出産し、自らの言葉が真実だったことまで証明しました。\n\nだから「國護り」の「成就」は、ただ願いが叶うことだけではありません。\n\n「ここまで育ててきたものが、目に見える形となって現れること」\n\n努力してきたものが完成する。\n思いが結果になる。\n新しい命や未来が、この世界へ姿を現す。\n\nその瞬間を木花咲耶姫命に重ねています。\n\n「咲く」という名前を持つ女神が「成就」なのは、\n\n「育ててきたものが、ついに花開く」\n\nという意味でも、とても美しい組み合わせです。",
      sacredSites: [{ mark: "★", name: "富士山本宮浅間大社", location: "静岡県富士宮市" }, { mark: "○", name: "北口本宮冨士浅間神社", location: "山梨県富士吉田市" }, { mark: "○", name: "冨士御室浅間神社", location: "山梨県富士河口湖町" }], sacredSitesNote: "",
    },
    "16": {
      en: {
        title: "Connection", deityName: "Okuninushi no Okami", deityNote: "Also known by several other names in ancient Japanese mythology.", meaningTitle: "Connection",
        meaning: "The bonds that link people, places, opportunities, and events.\n\nThis card represents meaningful encounters, relationships that shape your life, and the unseen threads through which one connection leads to another.",
        myth: "Okuninushi no Okami is one of the central deities of the Kojiki and is deeply associated with the development of the land and with human relationships.\n\nBefore becoming the great ruler of the land, Okuninushi endured many hardships.\n\nOne of the best-known stories is the tale of the White Hare of Inaba.\n\nThe hare had been badly injured after being deceived and stripped of its fur.\n\nOkuninushi’s elder brothers mocked the hare and gave it harmful advice, which made its suffering worse.\n\nOkuninushi, however, treated the hare with compassion and taught it how to heal.\n\nThe hare then foretold that Okuninushi would be the one to marry Yagami-hime, the woman his brothers were seeking.\n\nThroughout the myths, Okuninushi forms many important relationships with gods, companions, and partners.\n\nHe works together with Sukunahikona no Kami to develop the land.\n\nLater, after Sukunahikona departs, another divine presence appears and helps bring the work of nation-building toward completion.\n\nOkuninushi is also connected with the myth of the Transfer of the Land, in which he ultimately entrusts the earthly realm to the descendants of Amaterasu.\n\nOver time, worship of Okuninushi became strongly associated with en-musubi—the forming of meaningful bonds and relationships.",
        connectionHeading: "Why This Deity Represents “Connection”",
        connection: "The connections represented by Okuninushi are not limited to romantic relationships.\n\nHis myths are filled with meetings that change the direction of events.\n\nA wounded hare.\nA future wife.\nA small companion from across the sea.\nA mysterious divine presence.\nThe heavenly deities who later ask him to transfer the land.\n\nEach encounter leads to the next stage of his story.\n\nFor this reason, in Kunimamori, Okuninushi no Okami represents:\n\nthe bonds through which life moves and changes.\n\nA connection may introduce a person.\n\nIt may bring an opportunity.\n\nIt may lead you to a place you never expected to visit.\n\nAnd sometimes one encounter quietly changes the direction of everything that follows.",
        sacredSites: [{ mark: "★", name: "Izumo Taisha", location: "Izumo, Shimane" }, { mark: "○", name: "Izumo Daijingu", location: "Kameoka, Kyoto" }, { mark: "○", name: "Keta Taisha", location: "Hakui, Ishikawa" }], sacredSitesNote: "",
      },
      id: "16", number: "16", special: false, title: "縁", deityName: "大国主大神", reading: "おおくにぬしのおおかみ", deityNote: "", meaningTitle: "縁",
      meaning: "人と人。\n人と場所。\n人と出来事。\n\n自分ひとりでは生まれなかったものが、誰かとの出会いや結びつきによって動き始めること。\n\n今あるご縁だけではなく、これから結ばれていく縁、役目を終えて形を変えていく縁も含めて、人生を動かす「つながり」を表すカードです。",
      myth: "大国主大神は、『古事記』の中でも非常に多くの物語を持つ神です。\n\n若い頃は大穴牟遅神と呼ばれ、兄弟である八十神たちとともに、因幡の八上比売のもとへ向かいました。\n\nその途中、皮を剥がされ傷ついた兎に出会います。\n\n八十神たちは誤った治療法を教えましたが、大穴牟遅神は兎の話を聞き、正しい方法を教えて助けました。これがよく知られる「因幡の白兎」の物語です。\n\nその後、大穴牟遅神は八十神たちから命を狙われ、さらに根の堅州国では須佐之男命からいくつもの試練を課されます。\n\nその試練を乗り越える過程で、須佐之男命の娘・須勢理毘売命との結びつきが大きな支えとなりました。\n\nそして須佐之男命から「大国主神」と名乗るよう告げられ、葦原中国の国づくりへ向かいます。國學院大學の『古事記』神名データベースでも、大国主神は根の堅州国の試練を越えた後、少名毘古那神や大物主神とともに国づくりを進めた神として整理されています。\n\n国づくりでも、大国主大神は一柱だけで完成させたわけではありません。\n\n海の彼方から現れた少名毘古那神と力を合わせ、国土を造り固めます。\n\nしかし少名毘古那神は、やがて常世国へ去ってしまいます。\n\n国づくりをどう続ければよいのか大国主大神が悩んでいると、海を照らして現れた神が、自らを祀るなら国づくりに協力すると告げます。\n\nそれが、三輪山に鎮まる大物主大神です。\n\n大神神社ではこの伝承について、『古事記』では大物主大神が大国主神の前に現れ、国づくりを成就させるため三輪山に祀るよう求めたと伝えています。また『日本書紀』では、大物主大神が大国主神の「幸魂・奇魂」と名乗った伝承も紹介されています。\n\nこうして大国主大神の物語は、\n\n誰かを助け、\n誰かに助けられ、\n誰かと結ばれ、\n別れを経験し、\nまた新しい存在と出会う。\n\nその繰り返しの中で進んでいきます。",
      connectionHeading: "なぜ「縁」と結びつくのか",
      connection: "大国主大神は一般に「縁結びの神」として広く知られています。\n\nけれど、國護りでいう「縁」は、恋愛や結婚だけを意味していません。\n\n出雲大社公式でも、大国主大神は国譲りの後、目に見えない世界である「幽事・神事」を主宰する神となり、神在月には出雲に集う八百万の神々と、人々が幸せになるためのさまざまなご縁について議されることから、「縁結びの神」と敬われていると説明されています。\n\n大国主大神自身の神話を見ても、その人生は多くの「縁」によって動いています。\n\n白兎との出会い。\n須勢理毘売命との出会い。\n須佐之男命との関係。\n少名毘古那神との協力。\n大物主大神との出会い。\nそして、国譲りに至る天つ神々との関係。\n\n一つひとつの縁が、大国主大神を次の場所へ運んでいます。\n\nだから國護りでは、\n\n「縁とは、ただ人と結ばれることではなく、人生の流れそのものを変えていく力」\n\nとして大国主大神と結びつけました。\n\nご縁には、長く続くものもあります。\n\nほんの短い時間だけ交わるものもあります。\n\n嬉しい縁もあれば、そのときには意味がわからない縁もあるでしょう。\n\nそれでも後から振り返ったとき、\n\n「あの出会いがあったから、今ここにいる」\n\nと思えることがあります。\n\nNo.16「縁」は、そんな目には見えないつながりを見つめるカードです。\n\n縁とは、出会った人の数ではありません。\n\nあなたの人生を動かしたもの。\nあなたが誰かへ渡したもの。\nそして、目には見えなくても今もどこかで続いているもの。\n\n大国主大神の物語は、\n人は決して、一人の力だけでここまで来たのではないことを教えてくれます。",
      sacredSites: [{ mark: "★", name: "出雲大社", location: "島根県出雲市" }, { mark: "○", name: "大神神社", location: "奈良県桜井市" }],
      sacredSitesNote: "出雲大社｜大国主大神を御祭神として祀る、最も代表的な神社です。\n\n出雲大社公式では、大国主大神は人々とともに国土を開拓し、農耕や漁労、医薬など、人々の暮らしに関わるさまざまな営みを導いた神とされています。\n\n国譲りの後は幽事を主宰する神となり、現在も「縁結びの神」として広く信仰されています。\n\n大神神社｜御祭神は大物主大神。\n\n大国主大神そのものを主祭神とする神社ではありませんが、国づくりの神話において非常に深い関係があります。\n\n大国主大神が少名毘古那神と別れた後、大物主大神が現れ、自らを三輪山に祀ることで国づくりが成就すると告げたと伝えられています。\n\n「ひとつの縁が終わったあと、新しい縁が現れて次の道が開く」というNo.16の意味とも、非常に深く響き合う場所です。",
    },
    "17": {
      en: {
        title: "Love", deityName: "Aizen Myoo", deityNote: "A Buddhist wisdom deity associated with the transformation of desire and passion.", meaningTitle: "Love",
        meaning: "The power to care deeply, connect wholeheartedly, and transform strong emotion into something that supports life.\n\nThis card represents love not only as romance, but also as devotion, affection, compassion, and the energy that draws one being toward another.",
        myth: "Aizen Myoo belongs to the esoteric Buddhist tradition.\n\nUnlike many peaceful Buddhist figures, Aizen Myoo is often depicted with a fierce expression and a red body.\n\nThis appearance may seem surprising for a deity associated with love.\n\nHowever, the symbolism is important.\n\nIn esoteric Buddhism, powerful emotions such as desire are not always treated as something that must simply be rejected.\n\nInstead, they may be transformed through wisdom.\n\nThis principle is often expressed through the idea that worldly passions can become a path toward awakening when their energy is understood and redirected.\n\nAizen Myoo therefore came to be associated with strong attraction, affection, harmony between people, and the transformation of desire.\n\nIn Japan, devotion to Aizen Myoo also became connected with prayers concerning love and relationships.",
        connectionHeading: "Why This Deity Represents “Love”",
        connection: "Love is not always gentle from the beginning.\n\nIt may include longing, desire, jealousy, fear of loss, or an intense wish to be close to someone.\n\nAizen Myoo represents the possibility of transforming that powerful emotional energy.\n\nRather than pretending that desire does not exist, this figure asks:\n\n“What can this feeling become when it is guided by wisdom?”\n\nFor this reason, in Kunimamori, Aizen Myoo represents:\n\nthe transformation of intense feeling into a form of love that gives life rather than consuming it.\n\nLove is more than possession.\n\nIt is not simply wanting someone or something for yourself.\n\nAt its deepest, love becomes a force that allows both yourself and others to live more fully.",
        sacredSites: [{ mark: "★", name: "Aizendo Shoman-in", location: "Osaka" }, { mark: "○", name: "Saidai-ji Aizendo", location: "Nara" }], sacredSitesNote: "",
      },
      id: "17", number: "17", special: false, title: "愛", deityName: "愛染明王", reading: "あいぜんみょうおう", deityNote: "", meaningTitle: "愛",
      meaning: "誰かを想う心だけではなく、自分の中にある強い欲求や情熱さえも受け入れ、より大きな愛へと育てていくこと。\n\n人を惹きつけ、結びつける力と、愛することで自分自身も変わっていくことを表す。",
      myth: "愛染明王は、日本神話の神のように「物語を持つ存在」ではなく、密教の教えを象徴する明王です。\n\n全身を真紅に染め、怒りに満ちたような表情をしています。\n\n「愛」という名前から優しい姿を想像しがちですが、その姿は非常に力強く、三つの目と六本の腕を持つ忿怒の姿で表されます。\n\n愛染明王が象徴する重要な教えが、\n\n「煩悩即菩提」\n\nです。\n\n人間には、愛されたい、手に入れたい、離したくないという欲望や執着があります。\n\nしかし愛染明王は、その強い欲望そのものを完全に捨て去るのではなく、\n\n煩悩を浄化し、悟りへ向かう生命力へと転じていく\n\nという密教の教えを象徴しています。",
      connectionHeading: "なぜ「愛」と結びつくのか",
      connection: "「愛」は、いつも美しく穏やかな感情だけではありません。\n\n会いたい。\n離れたくない。\n自分を見てほしい。\n大切にされたい。\n\nそんな強い気持ちも、人が誰かを愛する時には生まれます。\n\n愛染明王が教えるのは、\n\nその強いエネルギーを否定するのではなく、どう生かすか\n\nということです。\n\nだから「國護り」の「愛」は、ただ「愛されています」「恋が叶います」という意味ではありません。\n\n自分の中に生まれた強い想いを、より深い愛へ育てていくこと。\n\n愛染明王の真紅の姿には、その激しく、力強い愛のエネルギーが重なります。",
      sacredSites: [{ mark: "★", name: "愛染堂勝鬘院", location: "大阪府大阪市" }, { mark: "○", name: "西大寺 愛染堂", location: "奈良県奈良市" }], sacredSitesNote: "",
    },
    "18": {
      en: {
        title: "Exchange", deityName: "Munakata Sanjoshin", deityNote: "The Three Goddesses of Munakata:\n\nTagorihime no Kami\nTagitsuhime no Kami\nIchikishimahime no Mikoto", meaningTitle: "Exchange",
        meaning: "The movement of people, words, feelings, knowledge, and blessings between one side and another.\n\nThis card represents communication, connection across distance, and the flow created when something is given and something is received.",
        myth: "The Three Goddesses of Munakata were born during the sacred oath between Amaterasu Omikami and Susanoo no Mikoto.\n\nWhen Susanoo came to Takamagahara, Amaterasu questioned his intentions.\n\nSusanoo proposed a ritual oath to demonstrate that he had no intention of taking over her realm.\n\nDuring the ritual, the two deities exchanged sacred objects and created new deities through them.\n\nFrom Susanoo’s sword, when it was received and transformed by Amaterasu, the Three Goddesses of Munakata were born.\n\nThe exact details differ among ancient sources, but the three goddesses are consistently connected with this divine exchange.\n\nThey later came to be worshipped at Munakata in northern Kyushu.\n\nThe Munakata region faced the sea routes that connected the Japanese archipelago with the Korean Peninsula and the Asian continent.\n\nFor centuries, people prayed to the Munakata goddesses for safety during sea voyages.\n\nBecause of this, their worship became deeply connected with travel, navigation, overseas exchange, and the movement of people and culture across the sea.",
        connectionHeading: "Why These Deities Represent “Exchange”",
        connection: "The Three Goddesses were themselves born from an exchange between two deities.\n\nAnd later, they came to protect the sea routes through which people, goods, knowledge, beliefs, and cultures traveled.\n\nThis gives the card two layers of meaning.\n\nExchange begins when something moves between one side and another.\n\nWords are spoken.\nSomeone listens.\nSomething is offered.\nSomething is received.\n\nFor this reason, in Kunimamori, the Munakata Sanjoshin represent:\n\nthe flow that is created when people and worlds connect.\n\nExchange does not require you to become the same as someone else.\n\nIt means allowing something to move between you while each side remains itself.",
        sacredSites: [{ mark: "★", name: "Munakata Taisha", location: "Munakata, Fukuoka" }, { mark: "○", name: "Itsukushima Jinja", location: "Hatsukaichi, Hiroshima" }, { mark: "○", name: "Enoshima Jinja", location: "Fujisawa, Kanagawa" }], sacredSitesNote: "",
      },
      id: "18", number: "18", special: false, title: "交流", deityName: "宗像三女神", reading: "むなかたさんじょしん",
      deityNote: "田心姫神\nたごりひめのかみ\n\n湍津姫神\nたぎつひめのかみ\n\n市杵島姫神\nいちきしまひめのかみ", meaningTitle: "交流",
      meaning: "人と人、場所と場所、異なる世界をつなぐこと。\n\n出会い、言葉、情報、行き来によって、新しい関係や流れが生まれることを表す。",
      myth: "宗像三女神は、天照大御神と須佐之男命の「誓約（うけい）」によって誕生しました。\n\n須佐之男命が高天原を訪れた時、天照大御神は、弟が高天原を奪いに来たのではないかと警戒します。\n\n須佐之男命は、自分に邪心がないことを証明するため、天照大御神との誓約を申し出ました。\n\n天照大御神が須佐之男命の剣を受け取り、噛み砕いて息を吹きかけると、そこから三柱の女神が誕生します。\n\nそれが宗像三女神です。\n\n三女神はその後、宗像の地に祀られました。\n\n宗像大社では、\n\n沖津宮に田心姫神、\n中津宮に湍津姫神、\n辺津宮に市杵島姫神\n\nを祀り、この三宮を合わせて宗像大社としています。\n\n宗像の地は古くから大陸へ向かう海上交通の重要な場所でした。\n\n沖ノ島では、航海の安全や大陸との交流に関わる国家的な祭祀が長期間行われていました。",
      connectionHeading: "なぜ「交流」と結びつくのか",
      connection: "宗像三女神が守った海は、\n\n人と人を隔てるものでもあり、人と人をつなぐものでもあります。\n\n海を渡ることで、\n\n人が移動する。\n物が運ばれる。\n文化が伝わる。\n新しい情報が入ってくる。\n\n宗像の海は、日本と大陸を結ぶ重要な道でもありました。\n\nさらに三女神自身も、天照大御神と須佐之男命が互いの持ち物を交換する誓約の中から誕生しています。\n\nそのため「國護り」では宗像三女神を、\n\n異なるもの同士をつなぎ、新しい流れを生み出す「交流」\n\nの象徴としています。\n\n交流とは、ただたくさん話すことではありません。\n\n自分とは違う誰かと関わることで、それまで自分の世界になかったものが入ってくる。\n\nその出会いが、新しい航路を開いていくことがあります。",
      sacredSites: [{ mark: "★", name: "宗像大社", location: "福岡県宗像市" }, { mark: "○", name: "嚴島神社", location: "広島県廿日市市" }, { mark: "○", name: "江島神社", location: "神奈川県藤沢市" }], sacredSitesNote: "",
    },
    "19": {
      en: {
        title: "Trust", deityName: "Hachiman Okami", deityNote: "The identity and interpretation of Hachiman developed over a long period of Japanese history.\n\nHachiman is especially associated with Emperor Ojin in later worship traditions.", meaningTitle: "Trust",
        meaning: "The ability to place confidence in something built through repeated experience.\n\nThis card represents relationships, beliefs, and foundations that become dependable because they have been tested over time.",
        myth: "Hachiman is unusual among the deities in Kunimamori because the figure is not defined by a single ancient myth.\n\nInstead, Hachiman worship developed gradually through history.\n\nUsa in present-day Oita Prefecture became one of the most important centers of Hachiman worship.\n\nOver time, Hachiman came to be associated with Emperor Ojin and was revered as a powerful protective deity.\n\nDuring the Nara period, the oracle of Hachiman became involved in major national events.\n\nHachiman worship also became closely connected with the protection of Buddhist institutions, making Hachiman one of the most important examples of the historical blending of kami worship and Buddhism.\n\nLater, warrior families also revered Hachiman as a guardian deity.\n\nHachiman shrines spread throughout Japan, and Hachiman became one of the most widely worshipped deities in the country.\n\nThis widespread devotion was not created by a single event.\n\nIt accumulated gradually through generations of prayer, protection, historical experience, and faith.",
        connectionHeading: "Why This Deity Represents “Trust”",
        connection: "Trust is rarely created in a single moment.\n\nIt grows through repetition.\n\nA promise is kept.\nSupport appears when it is needed.\nSomething continues to remain dependable over time.\n\nHachiman worship developed in much the same way.\n\nAcross centuries, people from different social groups and historical periods continued to place their faith in Hachiman.\n\nFor this reason, in Kunimamori, Hachiman Okami represents:\n\ntrust that has been built and strengthened through accumulated experience.\n\nTrust does not mean believing blindly.\n\nIt means recognizing what has repeatedly shown itself to be dependable.",
        sacredSites: [{ mark: "★", name: "Usa Jingu", location: "Usa, Oita" }, { mark: "○", name: "Iwashimizu Hachimangu", location: "Yawata, Kyoto" }, { mark: "○", name: "Tsurugaoka Hachimangu", location: "Kamakura, Kanagawa" }], sacredSitesNote: "",
      },
      id: "19", number: "19", special: false, title: "信頼", deityName: "八幡大神", reading: "はちまんおおかみ",
      deityNote: "宇佐神宮では、八幡大神を誉田別尊（応神天皇）の御神霊として祀っています。", meaningTitle: "信頼",
      meaning: "すべてを自分一人で抱えるのではなく、人や流れを信じて任せること。\n\n長い時間の中で築かれてきた関係や、自分自身が信じるものに身を預ける強さを表す。",
      myth: "八幡大神は、『古事記』の神代神話に登場する神とは性格が異なり、歴史の中で成立し、広がっていった信仰の神です。\n\n八幡信仰の中心となる宇佐神宮では、一之御殿に八幡大神を祀り、その御神霊を誉田別尊、すなわち応神天皇としています。\n\n八幡大神は571年に宇佐の地へ示顕したと伝えられ、725年に現在の地へ御殿が建てられました。\n\n八幡大神は、長い歴史の中で国家や人々から大きな信頼を寄せられていきます。\n\n奈良時代、東大寺の大仏建立という国家的大事業に際しても、宇佐八幡の神意が重視されました。\n\nさらに皇位継承をめぐる大きな問題が起きた際には、和気清麻呂が宇佐へ赴き、八幡大神の神託を受けたことでも知られています。\n\n宇佐神宮はこうした歴史を通して皇室からも篤く崇敬され、現在では全国に数多く存在する八幡社の総本宮となっています。",
      connectionHeading: "なぜ「信頼」と結びつくのか",
      connection: "八幡大神と「信頼」の結びつきは、一つの神話エピソードだけから生まれるものではありません。\n\nむしろ、\n\n長い年月をかけて、人々が八幡大神を頼り続けてきた歴史そのもの\n\nにあります。\n\n国の重大な局面で神意を求められ、\n人々の暮らしでは鎮守の神として祀られ、\nその信仰は全国へ広がっていきました。\n\n信頼も、一瞬で完成するものではありません。\n\n小さな経験を重ね、\n\n「ここなら大丈夫」\n「この人なら任せられる」\n「私はこれを信じて進もう」\n\nと思えるようになっていくものです。\n\nそのため「國護り」では八幡大神を、\n\n積み重ねの中で生まれる揺るぎない「信頼」\n\nと重ねています。",
      sacredSites: [{ mark: "★", name: "宇佐神宮", location: "大分県宇佐市" }, { mark: "○", name: "石清水八幡宮", location: "京都府八幡市" }, { mark: "○", name: "鶴岡八幡宮", location: "神奈川県鎌倉市" }], sacredSitesNote: "",
    },
    "20": {
      en: {
        title: "Commitment", deityName: "Omononushi no Okami", deityNote: "A deity closely associated with Mount Miwa and enshrined at Omiwa Jinja in Nara.", meaningTitle: "Commitment",
        meaning: "Making a promise, accepting a role, and taking responsibility for what follows.\n\nThis card represents the point at which an intention becomes something you are prepared to uphold through your actions.",
        myth: "During the process of developing the land, Okuninushi no Kami worked together with Sukunahikona no Kami.\n\nEventually, however, Sukunahikona departed for Tokoyo, the Eternal Land.\n\nLeft alone, Okuninushi wondered how he could continue and complete the work of nation-building.\n\nAt that moment, a mysterious divine being appeared from across the sea, shining brightly.\n\nThe deity told Okuninushi that if he wished to complete the land, he should enshrine this divine presence on a mountain in the eastern part of Yamato.\n\nThat mountain came to be associated with Mount Miwa.\n\nThe deity was Omononushi no Okami.\n\nIn a version recorded in the Nihon Shoki, Omononushi is described as the saki-mitama and kushi-mitama of Okuninushi—the divine spiritual powers connected with bringing blessings and wondrous results.\n\nThrough enshrining Omononushi at Mount Miwa, the work of establishing the land was able to move toward completion.\n\nThis is one of the foundational myths associated with Omiwa Jinja.",
        connectionHeading: "Why This Deity Represents “Commitment”",
        connection: "In this story, Omononushi does not simply appear and solve everything for Okuninushi.\n\nA condition is presented.\n\nThe divine presence asks to be properly enshrined.\n\nOkuninushi must recognize that presence, accept what is being asked, and take action.\n\nThis creates a relationship based on responsibility.\n\nFor this reason, in Kunimamori, Omononushi no Okami represents:\n\nthe moment when a promise becomes something you actually agree to carry.\n\nCommitment is more than saying:\n\n“I want this.”\n\nIt means also asking:\n\n“What am I willing to take responsibility for in order to bring this into reality?”\n\nA true commitment changes your actions.",
        sacredSites: [{ mark: "★", name: "Omiwa Jinja", location: "Sakurai, Nara" }, { mark: "★", name: "Kotohira-gu", location: "Kotohira, Kagawa" }], sacredSitesNote: "",
      },
      id: "20", number: "20", special: false, title: "誓約", deityName: "大物主大神", reading: "おおものぬしのおおかみ", deityNote: "", meaningTitle: "誓約",
      meaning: "自分が決めたことを言葉だけで終わらせず、約束として引き受けること。\n\n誰かとの約束だけではなく、自分自身との約束、役割や責任を受け入れることを表す。",
      myth: "大国主神と少彦名神は、力を合わせて国作りを進めていました。\n\nところが少彦名神が常世国へ去ったあと、大国主神は一人になってしまいます。\n\n「これから、この国をどう作っていけばよいのか」\n\n大国主神が思い悩んでいた時、海の彼方から光り輝きながら近づいてくる神が現れました。\n\nその神は、大国主神に、\n\n「自分を大和の青垣の東の山に祀るなら、国作りに協力しよう」\n\nという趣旨のことを告げます。\n\nその神こそ大物主大神でした。\n\n大国主神はその言葉を受け、大物主大神を三輪山に祀ります。\n\nそして、大物主大神の助けを得て国作りを成し遂げたと伝えられています。\n\n『日本書紀』ではさらに、大物主大神は大国主神自身の\n\n「幸魂・奇魂」\n\nであると名乗ったとされています。\n\nつまり大物主大神は、大国主神の国作りを外から助けるだけではなく、大国主神自身に宿る特別な御魂としても語られているのです。",
      connectionHeading: "なぜ「誓約」と結びつくのか",
      connection: "この物語で大切なのは、\n\n「祀ること」と「国作りを助けること」が結びついている\n\n点です。\n\n大物主大神は、ただ突然現れて国を完成させたわけではありません。\n\n大国主神が大物主大神を三輪山へ祀り、\n大物主大神が国作りを助ける。\n\n互いの役割が定まり、それによって国作りが再び動き始めます。\n\nそこには、\n\n「私はこれを担う。あなたはこれを担う」\n\nという約束にも似た構造があります。\n\n「誓約」とは、ただ口にする願いではありません。\n\n約束した瞬間から、自分にも役割が生まれます。\n\nだから「國護り」では大物主大神を、\n\n約束を結び、それに伴う役割を引き受ける「誓約」\n\nの象徴としています。\n\n誰かとの約束かもしれない。\n仕事や使命との約束かもしれない。\n\nそして時には、\n\n「私はこう生きる」\n\nという、自分自身との約束かもしれません。",
      sacredSites: [{ mark: "★", name: "大神神社", location: "奈良県桜井市" }, { mark: "★", name: "金刀比羅宮", location: "香川県琴平町" }], sacredSitesNote: "",
    },
    "21": {
      en: {
        title: "Boundaries", deityName: "Dosojin", deityNote: "Dosojin is a collective name for protective deities traditionally enshrined at village borders, crossroads, mountain passes, and roadsides.", meaningTitle: "Boundaries",
        meaning: "Recognizing where you end and where someone or something else begins.\n\nThis card represents protection, healthy distance, and the ability to create a clear line between what belongs within your space and what does not.",
        myth: "Unlike many other deities in Kunimamori, Dosojin does not have one single myth in the Kojiki or Nihon Shoki.\n\nInstead, Dosojin worship developed through local traditions across Japan.\n\nStone statues and sacred markers were often placed at the edges of villages, at crossroads, and along roads.\n\nThese places were considered important boundaries.\n\nThey marked the line between the familiar world of the community and the unknown world beyond it.\n\nBecause travelers, strangers, disease, and unseen influences could enter through such places, Dosojin came to be worshipped as protective deities of roads and boundaries.\n\nIn some regions, Dosojin also became connected with travel safety, fertility, marriage, and community protection.\n\nThe form of Dosojin varies greatly from place to place.\n\nSome are represented by simple stones.\nOthers appear as paired male and female figures.\n\nWhat remains consistent is their connection with:\n\nthe place where one world meets another.",
        connectionHeading: "Why This Deity Represents “Boundaries”",
        connection: "A boundary is not always a wall.\n\nIt can be a line that helps you recognize:\n\n“This is mine.”\n“That belongs to someone else.”\n“I can go this far.”\n“Beyond this point, I need to protect myself.”\n\nDosojin stand precisely at such lines.\n\nThey guard the entrance.\nThey mark the border.\nThey protect the space on either side.\n\nFor this reason, in Kunimamori, Dosojin represents:\n\nthe wisdom to create boundaries that protect both yourself and your relationships.\n\nA healthy boundary does not necessarily reject others.\n\nIt allows connection to happen without losing yourself.",
        sacredSites: [{ mark: "★", name: "Dosojin Jinja", location: "Kyoto" }, { mark: "○", name: "Dosojin of Azumino", location: "Azumino, Nagano" }], sacredSitesNote: "",
      },
      id: "21", number: "21", special: false, title: "境界", deityName: "道祖神", reading: "どうそじん", deityNote: "", meaningTitle: "境界",
      meaning: "自分と他者、内側と外側、安全な場所とそうでない場所を分ける線。\n何を受け入れ、何を入れないのかを自分で決めることを表す。",
      myth: "道祖神は、一柱の神だけを指すというより、村境や道の辻、峠などに祀られてきた神々・石神の総称的な信仰です。\n\n昔の人々にとって、村の外は今よりずっと未知で危険な場所でした。\n\nそこで村と外の世界が接する場所に道祖神を祀り、\n\n「ここから内側を守る」\n\nという願いを込めました。\n\n道祖神は村の中心や道の辻、三叉路などに立ち、村の守り神として祀られてきました。\n\n五穀豊穣、無病息災、子孫繁栄、旅の安全などを願う、とても身近な神でもあります。",
      connectionHeading: "なぜ「境界」と結びつくのか",
      connection: "道祖神が祀られた場所そのものが、\n\n「こちら側と、向こう側の境目」\n\nでした。\n\n村の内と外。\n安全な場所と未知の場所。\n日常と旅の世界。\n\nだから「國護り」では道祖神を、\n\n自分を守るために必要な境界\n\nの象徴としています。\n\n境界を作ることは、誰かを拒絶することではありません。\n\nどこまでなら受け入れられるのか。\n何を大切にしたいのか。\nどこから先は踏み込ませないのか。\n\nそれを自分で知ることです。\n\n自分の内側を守る境界があるからこそ、安心して人と関わることもできるのです。",
      sacredSites: [{ mark: "★", name: "道祖神社", location: "京都府京都市" }, { mark: "○", name: "安曇野の道祖神群", location: "長野県安曇野市" }], sacredSitesNote: "",
    },
    "22": {
      en: {
        title: "Reconciliation", deityName: "Kukurihime no Kami", deityNote: "Also known as Kukurihime no Mikoto.", meaningTitle: "Reconciliation",
        meaning: "Bringing a relationship, conflict, or emotional division to a place where it can be settled.\n\nThis card represents restoring harmony when possible, or reaching a peaceful conclusion even when returning to the previous relationship is no longer appropriate.",
        myth: "Kukurihime appears only briefly in one version of the Nihon Shoki.\n\nAfter Izanami no Mikoto died and entered Yomi, Izanagi no Mikoto followed her into the land of the dead.\n\nTheir reunion ended in conflict.\n\nIzanagi fled from Yomi, and the relationship between the two had reached a point of complete separation.\n\nIn one alternate account of this myth, Kukurihime no Kami appears during the confrontation between Izanagi and Izanami.\n\nThe Nihon Shoki does not preserve the exact words spoken by Kukurihime.\n\nIt only tells us that she said something to Izanagi, and that he praised what she had said.\n\nBecause the actual words are unknown, we cannot say with certainty exactly what Kukurihime told them.\n\nHowever, later tradition came to regard her as a deity connected with mediation, harmony, and the tying together of relationships.\n\nThis interpretation became especially important in Hakusan worship.",
        connectionHeading: "Why This Deity Represents “Reconciliation”",
        connection: "Reconciliation does not always mean returning to the way things were before.\n\nSometimes two people can continue together.\n\nSometimes the healthiest conclusion is to separate without continuing the conflict.\n\nThe appearance of Kukurihime occurs at a moment when the relationship between Izanagi and Izanami can no longer return to its former state.\n\nFor this reason, in Kunimamori, Kukurihime represents:\n\nfinding a way to bring conflict to a peaceful conclusion.\n\nReconciliation may mean reconnecting.\n\nBut it may also mean understanding, releasing resentment, or accepting that a relationship has changed.\n\nThe important thing is not to force the past to return.\n\nIt is to bring the conflict to a place where you can move forward.",
        sacredSites: [{ mark: "★", name: "Shirayama Hime Jinja", location: "Hakusan, Ishikawa" }, { mark: "○", name: "Niigata Hakusan Jinja", location: "Niigata" }], sacredSitesNote: "",
      },
      id: "22", number: "22", special: false, title: "和解", deityName: "菊理媛神", reading: "くくりひめのかみ", deityNote: "「菊理媛尊」とも表記されます。", meaningTitle: "和解",
      meaning: "対立していたものの間に、新しい結び方を見つけること。\n相手と完全に同じになるのではなく、違いを認めながら関係を整理し、次へ進むことを表す。",
      myth: "菊理媛神は、『古事記』には登場せず、『日本書紀』の一書にのみ登場する、とても謎の多い女神です。\n\n伊邪那岐尊が亡くなった伊邪那美尊を追って黄泉国へ向かった後、二柱は黄泉の国とこの世との境で向き合います。\n\nそこで二柱の間に現れるのが菊理媛神です。\n\n菊理媛神が何を言ったのか、その言葉自体は『日本書紀』には記されていません。\n\nただ、\n\n「菊理媛神が何かを申し上げ、それを伊邪那岐尊が褒めた」\n\nという非常に短い記述だけが残っています。\n\n白山比咩神社では、この場面を菊理媛尊が伊邪那岐尊・伊邪那美尊の仲裁をしたものとして伝えています。\n\nまた、「くくり」が「括る」にも通じることから、和合や縁結びの神としても信仰されています。",
      connectionHeading: "なぜ「和解」と結びつくのか",
      connection: "菊理媛神の物語には、ひとつ大切な特徴があります。\n\n「何を言ったのかが残っていない」\n\nそれなのに、その言葉によって場面が動きました。\n\n和解とは、必ずしも以前と同じ関係に戻ることではありません。\n\n時には、\n\nもうここで終わりにする。\n互いの違いを認める。\nそれぞれの場所へ戻る。\n\nということも和解です。\n\n伊邪那岐尊と伊邪那美尊も、結局は以前の夫婦関係へ戻ったわけではありません。\n\nだから「國護り」では菊理媛神を、\n\n絡まった関係を整理し、それぞれが次へ進める形に結び直す存在\n\nとして「和解」と重ねています。",
      sacredSites: [{ mark: "★", name: "白山比咩神社", location: "石川県白山市" }, { mark: "○", name: "新潟白山神社", location: "新潟県新潟市" }], sacredSitesNote: "",
    },
    "23": {
      en: {
        title: "Acceptance", deityName: "Kannon Bosatsu", deityNote: "Also known as:\nAvalokiteshvara\nKanzeon Bosatsu\nKanjizai Bosatsu", meaningTitle: "Acceptance",
        meaning: "Seeing what is present without immediately rejecting, denying, or trying to change it.\n\nThis card represents compassion, openness, and the ability to meet reality as it is before deciding what to do next.",
        myth: "Kannon Bosatsu is one of the most widely revered bodhisattvas in Buddhism.\n\nThe name Kanzeon can be understood as:\n\n“the one who perceives the sounds of the world.”\n\nIn Buddhist tradition, Kannon listens to the suffering and cries of living beings and responds with compassion.\n\nThe Lotus Sutra describes Kannon as a bodhisattva who appears in many different forms according to what is needed.\n\nDepending on the person and situation, Kannon may take the form of a Buddha, monk, woman, child, ruler, or many other beings.\n\nIn Japan, this idea developed into many forms of Kannon worship.\n\nAmong them are:\nSho Kannon,\nSenju Kannon,\nJuichimen Kannon,\nNyoirin Kannon,\nand others.\n\nThe form changes, but the central principle remains the same:\n\nto perceive suffering and respond to it.",
        connectionHeading: "Why This Deity Represents “Acceptance”",
        connection: "Before suffering can be healed, it first has to be seen.\n\nKannon does not begin by saying:\n\n“You should not feel that way.”\n\nInstead, Kannon listens.\n\nThis is the starting point of acceptance.\n\nAcceptance does not mean approving of everything.\n\nIt does not mean giving up or refusing to change.\n\nIt means recognizing:\n\n“This is what is happening right now.”\n\nOnly after reality is seen clearly can the next step truly begin.\n\nFor this reason, in Kunimamori, Kannon Bosatsu represents:\n\nthe compassion to meet yourself and your circumstances as they are.\n\nSometimes the first thing you need is not an answer.\n\nIt is permission to acknowledge what you are actually feeling.",
        sacredSites: [{ mark: "★", name: "Senso-ji", location: "Taito, Tokyo" }, { mark: "○", name: "Hase-dera", location: "Sakurai, Nara" }, { mark: "○", name: "Kiyomizu-dera", location: "Kyoto" }], sacredSitesNote: "",
      },
      id: "23", number: "23", special: false, title: "受容", deityName: "観音菩薩", reading: "かんのんぼさつ", deityNote: "正式には観世音菩薩。\nまた「観自在菩薩」とも呼ばれます。", meaningTitle: "受容",
      meaning: "今ある自分や現実を、すぐに否定せず受け止めること。\n苦しみや弱さも含め、あるがままの状態に気づき、そこから必要な助けや変化を受け取ることを表す。",
      myth: "観音菩薩は、人々の苦しみの声を聞き、その苦しみを救う慈悲の菩薩です。\n\n「観世音」という名前には、\n\n「世の人々の声を観る」\n\nという意味が込められています。\n\n観音菩薩は、生きとし生けるものの声を観じ、その苦しみを除き、願いを聞いて安楽を与える仏として信仰されてきました。\n\nまた観音菩薩は、相手に応じてさまざまな姿となって救う存在として説かれます。\n\n十一面観音、千手観音、如意輪観音など、多くの姿で信仰されているのもそのためです。\n\n浅草寺の縁起では、628年、檜前浜成・竹成兄弟が隅田川で漁をしていた際、一体の像が網にかかりました。\n\n何度場所を変えて網を投げても同じ像がかかったため持ち帰ったところ、それが聖観世音菩薩であることが分かり、祀られたことが浅草寺の始まりと伝えられています。",
      connectionHeading: "なぜ「受容」と結びつくのか",
      connection: "観音菩薩は、\n\n「こういう人だけを救う」\n\nとはしません。\n\n苦しんでいる声があれば、その声を聞く。\n\nその人に必要な姿となり、救いの手を差し伸べます。\n\nそこにはまず、\n\nその人が今どんな状態にあるのかを受け止めること\n\nがあります。\n\n受容とは、\n\n「何でも我慢すること」\n「嫌なことまで肯定すること」\n\nではありません。\n\n悲しいなら悲しい。\n怖いなら怖い。\n今はできないなら、できない。\n\nまずその状態を否定せずに認めることです。\n\nそのため「國護り」では観音菩薩を、\n\n今あるものをそのまま受け止め、そこから救いや変化へつなげる「受容」\n\nの象徴としています。",
      sacredSites: [{ mark: "★", name: "浅草寺", location: "東京都台東区" }, { mark: "○", name: "長谷寺", location: "奈良県桜井市" }, { mark: "○", name: "清水寺", location: "京都府京都市" }], sacredSitesNote: "",
    },
    "24": {
      en: {
        title: "Conflict", deityName: "Bishamonten", deityNote: "The Japanese form of Vaishravana, one of the Four Heavenly Kings in Buddhism.", meaningTitle: "Conflict",
        meaning: "A situation in which opposing forces, values, desires, or positions meet.\n\nThis card represents confrontation, tension, and the moment when you are forced to recognize what you are truly trying to protect.",
        myth: "Bishamonten originated from the Indian deity Vaishravana and entered Buddhism as a guardian figure.\n\nIn Buddhist tradition, he is one of the Four Heavenly Kings and protects the northern direction.\n\nIn Japan, Bishamonten became widely worshipped as a powerful guardian deity.\n\nHe is often depicted wearing armor and carrying a weapon, symbolizing his role as a defender against harmful forces.\n\nHe may also hold a small treasure pagoda, representing protection of the Buddhist teachings and sacred treasures.\n\nOver time, Bishamonten became associated not only with protection, but also with victory, prosperity, and good fortune.\n\nAt places such as Shigisan Chogosonshi-ji, Bishamonten has long been revered as a powerful protector.",
        connectionHeading: "Why This Deity Represents “Conflict”",
        connection: "Conflict is uncomfortable.\n\nMany people instinctively want to avoid it.\n\nBut confrontation can reveal something important.\n\nWhen challenged, you may suddenly understand:\n\n“What am I trying to protect?”\n“What am I unwilling to give up?”\n“What really matters to me?”\n\nBishamonten does not represent fighting for the sake of fighting.\n\nHe is a guardian.\n\nHis power is used to protect what is considered precious.\n\nFor this reason, in Kunimamori, Bishamonten represents:\n\nthe conflict that reveals what you truly value.\n\nNot every battle needs to be fought.\n\nBut when conflict appears, it may be showing you where your values, boundaries, or responsibilities really lie.",
        sacredSites: [{ mark: "★", name: "Shigisan Chogosonshi-ji", location: "Heguri, Nara" }, { mark: "○", name: "Kurama-dera", location: "Kyoto" }, { mark: "○", name: "Bishamondo Monzeki", location: "Kyoto" }], sacredSitesNote: "",
      },
      id: "24", number: "24", special: false, title: "対立", deityName: "毘沙門天", reading: "びしゃもんてん", deityNote: "四天王として祀られる場合は「多聞天」とも呼ばれます。", meaningTitle: "対立",
      meaning: "自分と相手の考えや目的がぶつかり合うこと。\n避けるだけではなく、何を守り、何のために立つのかを明確にする必要がある状態を表す。",
      myth: "毘沙門天は、仏教世界を守る四天王の一尊です。\n\n四天王は東西南北を守護し、その中で毘沙門天＝多聞天は北方を守る存在とされます。\n\n甲冑を身につけ、武器を持つ勇ましい姿で表されることが多く、仏法を脅かすものに立ち向かう守護神です。\n\nしかし、ただ戦うための存在ではありません。\n\n「多聞天」という名の通り、仏の教えをよく聞き、その教えを守る存在でもあります。\n\n信貴山朝護孫子寺では、聖徳太子が物部守屋との戦いを前に毘沙門天王を感得し、その加護によって勝利したという寺伝が残っています。\n\n勝利後、聖徳太子は自ら毘沙門天王像を刻み、祀ったと伝えられています。",
      connectionHeading: "なぜ「対立」と結びつくのか",
      connection: "「対立」は、必ずしも悪いことではありません。\n\n違う考えを持つ人がいる。\n譲れないものがある。\n守らなければならないものがある。\n\nそんな時、衝突が起こることがあります。\n\n毘沙門天は、\n\n「何のために立つのか」\n\nが明確な守護者です。\n\nただ感情的に争うのではなく、守るものがあるから戦う。\n\nそのため「國護り」では毘沙門天を、\n\n対立の中で、自分が何を守ろうとしているのかを知る存在\n\nとして重ねています。\n\n対立は時に、自分が本当に大切にしているものを見せてくれます。",
      sacredSites: [{ mark: "★", name: "信貴山朝護孫子寺", location: "奈良県平群町" }, { mark: "○", name: "鞍馬寺", location: "京都府京都市" }, { mark: "○", name: "毘沙門堂門跡", location: "京都府京都市" }], sacredSitesNote: "",
    },
    "25": {
      en: {
        title: "Confusion", deityName: "Fudo Myoo", deityNote: "The Japanese form of Acala, one of the principal wisdom kings of Esoteric Buddhism.", meaningTitle: "Confusion",
        meaning: "A state in which the way forward is difficult to see.\n\nThis card represents uncertainty, mental noise, hesitation, and the challenge of finding a stable center when everything around you feels unclear.",
        myth: "Fudo Myoo is a central figure in Japanese Esoteric Buddhism.\n\nHis name means:\n\n“the Immovable Wisdom King.”\n\nHe is often depicted with a fierce expression, surrounded by flames.\n\nIn one hand, he holds a sword.\n\nIn the other, he holds a rope.\n\nThe sword symbolizes wisdom that cuts through ignorance and delusion.\n\nThe rope symbolizes the power to bind harmful impulses and guide beings back toward the right path.\n\nThe flames surrounding Fudo Myoo are associated with burning away obstacles and worldly attachments.\n\nDespite the intense appearance, Fudo Myoo is fundamentally a protective figure.\n\nHis fierce form expresses the determination to guide beings even when gentler methods are not enough.\n\nThe most important part of his symbolism is contained in his name:\n\nImmovable.",
        connectionHeading: "Why This Deity Represents “Confusion”",
        connection: "At first, Fudo Myoo may seem like the opposite of confusion.\n\nThat is exactly why he was chosen for this card.\n\nWhen everything around you feels uncertain, what matters most is not finding an instant answer.\n\nIt is finding the place within yourself that does not move with every passing fear or thought.\n\nConfusion pulls the mind in many directions.\n\n“What if this happens?”\n“What if I choose wrong?”\n“Maybe I should go back.”\n“Maybe I should wait.”\n\nFudo Myoo represents the point that remains steady within that movement.\n\nFor this reason, in Kunimamori, Fudo Myoo represents:\n\nfinding an unmoving center in the middle of confusion.\n\nYou do not always need to eliminate uncertainty before moving forward.\n\nSometimes you first need to ask:\n\n“What remains true for me, even while I am unsure?”\n\nFrom that stable point, the path can begin to appear.",
        sacredSites: [{ mark: "★", name: "Naritasan Shinshoji", location: "Narita, Chiba" }, { mark: "○", name: "Takahata Fudoson Kongo-ji", location: "Hino, Tokyo" }, { mark: "○", name: "Meguro Fudoson Ryusen-ji", location: "Meguro, Tokyo" }], sacredSitesNote: "",
      },
      id: "25", number: "25", special: false, title: "迷い", deityName: "不動明王", reading: "ふどうみょうおう", deityNote: "", meaningTitle: "迷い",
      meaning: "進みたいのに決めきれない状態。\n不安や恐れ、余計な思考に揺さぶられ、本当に大切なものが見えなくなっていることを表す。\n\n同時に、揺れるものの中にあっても動かない「軸」を取り戻すことを示すカード。",
      myth: "不動明王は、密教における代表的な明王です。\n\nその名の「不動」が示すように、\n\n「揺るがない存在」\n\nとして表されます。\n\n一般に右手には剣を持ち、左手には羂索と呼ばれる縄を持ちます。\n\n剣は迷いや煩悩を断ち切る智慧を表し、羂索は迷う者を救い取る働きを象徴します。\n\nそして不動明王の背後には、激しく燃える炎が描かれます。\n\n怒ったような恐ろしい顔をしているのも、衆生を力強く迷いから救うための姿です。\n\n成田山新勝寺では、弘法大師空海が敬刻開眼したと伝えられる不動明王を御本尊として祀っています。\n\n開山以来、千年以上にわたり御護摩の火を絶やさず、不動明王への祈りが続けられてきました。",
      connectionHeading: "なぜ「迷い」と結びつくのか",
      connection: "一見すると、\n\n「不動明王なのに迷い？」\n\nと思うかもしれません。\n\nでも、この組み合わせの意味はそこにあります。\n\n迷っている時、私たちの心は、\n\nこちらかもしれない。\nやっぱり違うかもしれない。\n失敗したらどうしよう。\n\nと揺れ続けます。\n\nだから必要なのは、\n\n「迷わない人になること」\n\nではなく、\n\n迷いの中でも動かない自分の軸を見つけること。\n\n不動明王の剣が断つのは、外の世界ではなく、迷いを生み出している煩悩や執着です。\n\nそのため「國護り」では、\n\n「迷いの中にいる時こそ、自分の中心へ戻る」\n\nという意味を込めて不動明王を「迷い」のカードに重ねています。\n\n答えが見つからない時、無理に動かなくてもいい。\n\nまず、自分の中で何が揺れているのかを見る。\n\nその奥に、簡単には動かないものが残っています。",
      sacredSites: [{ mark: "★", name: "成田山新勝寺", location: "千葉県成田市" }, { mark: "○", name: "高幡不動尊 金剛寺", location: "東京都日野市" }, { mark: "○", name: "目黒不動尊 瀧泉寺", location: "東京都目黒区" }], sacredSitesNote: "",
    },
    "26": {
      en: {
        title: "Attachment", deityName: "Shaka Nyorai", deityNote: "The historical Buddha, Siddhartha Gautama, after enlightenment.", meaningTitle: "Attachment",
        meaning: "Holding tightly to something that is changing, passing, or no longer meant to remain as it was.\n\nThis card represents the suffering that can arise when we cling to people, possessions, identities, expectations, or outcomes.",
        myth: "Shaka Nyorai is the enlightened form of Siddhartha Gautama, the historical Buddha.\n\nBorn as a prince in ancient India, Siddhartha lived a protected life in the palace.\n\nAccording to Buddhist tradition, his view of the world changed after encountering old age, illness, and death.\n\nHe came to understand that suffering is an unavoidable part of human life.\n\nLeaving the palace, he began a spiritual search for the cause of suffering and the path beyond it.\n\nAfter years of practice, he attained enlightenment beneath the Bodhi tree.\n\nOne of the central insights of Buddhism is that suffering is closely connected with craving and attachment.\n\nEverything changes.\n\nBodies age.\nRelationships change.\nPossessions are lost.\nEmotions rise and pass.\nEven the self we think of as fixed is constantly changing.\n\nWhen we demand that something impermanent remain exactly as we want it to be, suffering grows.",
        connectionHeading: "Why This Deity Represents “Attachment”",
        connection: "Attachment does not mean that caring is wrong.\n\nThe problem begins when love, desire, or hope turns into:\n\n“This must never change.”\n“This person must stay exactly as I want.”\n“I cannot be okay unless I receive this result.”\n\nShaka Nyorai teaches the importance of seeing impermanence clearly.\n\nFor this reason, in Kunimamori, Shaka Nyorai represents:\n\nthe suffering created by holding too tightly to what cannot remain unchanged.\n\nLetting go does not mean saying that something never mattered.\n\nIt means loosening your grip enough to allow reality to move.\n\nSometimes what needs to be released is not the person or thing itself.\n\nIt is the demand that it must always remain exactly the same.",
        sacredSites: [{ mark: "★", name: "Horyu-ji", location: "Ikaruga, Nara" }, { mark: "○", name: "Seiryo-ji", location: "Kyoto" }], sacredSitesNote: "",
      },
      id: "26", number: "26", special: false, title: "執着", deityName: "釈迦如来", reading: "しゃかにょらい", deityNote: "仏教の開祖である釈迦牟尼仏、すなわちお釈迦さまです。", meaningTitle: "執着",
      meaning: "失いたくない、手放したくない、思い通りにしたいという心。\n大切にすることと、そこへ必要以上にしがみつくことの違いに気づき、苦しみを生み出している握りしめを緩めることを表す。",
      myth: "釈迦如来は、日本神話の神ではなく、約2500年前のインドで生きた釈迦の悟りと教えを表す仏です。\n\n王子として生まれた釈迦は、老い・病・死という、人間が避けることのできない苦しみに向き合い、城を離れて修行の道へ進みました。\n\n厳しい苦行を続けましたが、それだけでは悟りに至らないと気づき、極端な快楽にも苦行にも偏らない「中道」を選びます。\n\nそして菩提樹の下で坐禅を続け、悟りを開いたと伝えられています。\n\n釈迦が見いだした教えの中心の一つが、苦しみがどこから生まれるのかという問いでした。\n\n仏教では、物事は常に変化していくにもかかわらず、\n\n「ずっとこのままであってほしい」\n「これは私のものだ」\n「こうならなければならない」\n\nと握りしめることによって、苦しみが生じると説きます。",
      connectionHeading: "なぜ「執着」と結びつくのか",
      connection: "何かを大切にすること自体が悪いわけではありません。\n\n人を愛する。\n夢を持つ。\n物を大切にする。\n\nそれは自然なことです。\n\nけれど、\n\n「絶対に失ってはいけない」\n\nとなった瞬間、その大切なものが、自分を苦しめるものへ変わることがあります。\n\n釈迦の教えは、\n\n「何も欲しがってはいけない」\n\nという単純なものではありません。\n\n変わっていくものを、変わらないものとして握りしめようとする心に気づくこと。\n\nだから「國護り」では釈迦如来を、\n\n執着に気づき、握りしめている手を少し緩める智慧\n\nとして「執着」のカードに重ねています。\n\n手放すとは、捨てることではありません。\n\n大切にしながらも、\nそれなしでは自分は生きられないという状態から自由になることなのです。",
      sacredSites: [{ mark: "★", name: "法隆寺", location: "奈良県斑鳩町" }, { mark: "○", name: "清凉寺", location: "京都府京都市" }], sacredSitesNote: "",
    },
    "27": {
      en: {
        title: "Illusion", deityName: "Marishiten", deityNote: "Derived from the Buddhist deity Marici.", meaningTitle: "Illusion",
        meaning: "A situation in which appearance and reality do not fully match.\n\nThis card represents uncertainty created by assumptions, projections, impressions, and things that seem real but may disappear when viewed more carefully.",
        myth: "Marishiten originates from the Buddhist deity Marici.\n\nThe Sanskrit name Marici is associated with rays of light and shimmering light.\n\nIn Buddhist tradition, Marici came to be connected with phenomena such as sunlight, radiance, and mirage-like appearances.\n\nA mirage can be seen, but it cannot be grasped.\n\nIt appears to exist clearly in front of you, yet changes or disappears as you approach it.\n\nIn Japan, Marishiten became especially important as a protective deity.\n\nWarriors prayed to Marishiten for protection, believing in the deity’s power to remain unseen by enemies and avoid harm.\n\nThis association with invisibility, light, and elusive appearance gave Marishiten a distinctive character.",
        connectionHeading: "Why This Deity Represents “Illusion”",
        connection: "Something can look completely real and still not be the whole truth.\n\nA first impression.\nA fear.\nA hope.\nA rumor.\nAn image created in your mind.\n\nAll of these can feel convincing.\n\nBut feeling certain does not always mean seeing clearly.\n\nMarishiten is associated with light that shimmers, appears, and cannot easily be grasped.\n\nFor this reason, in Kunimamori, Marishiten represents:\n\nthe space between what appears to be true and what actually is true.\n\nThis card does not tell you that everything is false.\n\nIt asks you to look again.\n\nWhat are you seeing?\n\nAnd how much of what you see comes from reality itself, rather than from your expectations, fears, or desires?",
        sacredSites: [{ mark: "★", name: "Tokudaiji Marishiten", location: "Taito, Tokyo" }, { mark: "○", name: "Zenko-an Marishitendo", location: "Kyoto" }], sacredSitesNote: "",
      },
      id: "27", number: "27", special: false, title: "幻惑", deityName: "摩利支天", reading: "まりしてん", deityNote: "", meaningTitle: "幻惑",
      meaning: "見えているものだけでは真実を判断できない状態。\n思い込み、錯覚、恐れ、期待などによって、本当の姿が見えにくくなっていることを表す。",
      myth: "摩利支天は、古代インドの信仰に由来する仏教の守護尊です。\n\n「摩利支」はサンスクリット語のマリーチに由来し、陽炎や光線を意味するとされます。\n\n摩利支天は、陽炎の光が神格化された存在で、本来は目に見えないものとされています。\n\n陽炎は、確かにそこに何かが見えるのに、近づけば同じ姿では存在しません。\n\n摩利支天は、その見えない性質から、敵から姿を隠し、災いを避け、身を守る力を持つ尊格として信仰されるようになりました。\n\n像にはいくつかの姿があり、天女の姿をしたものや、三つの顔と複数の腕を持つ忿怒の姿があります。\n\nまた、猪を眷属として従える姿もよく知られています。",
      connectionHeading: "なぜ「幻惑」と結びつくのか",
      connection: "摩利支天を「幻惑」と結びつける最大の理由は、\n\nその本質が「陽炎」であること。\n\n見える。\nけれど、つかめない。\n\n確かにあるように思える。\nけれど、本当にそうなのかは分からない。\n\n人の心にも同じことがあります。\n\n「あの人はきっとこう思っている」\n「絶対にこうなる」\n「これは間違いなく悪いことだ」\n\nそう思い込んでいても、それが事実とは限りません。\n\n不安が見せている景色かもしれない。\n願望が見せている景色かもしれない。\n\nだから「國護り」では摩利支天を、\n\n目に映るものと真実を混同しないための「幻惑」\n\nの象徴としています。\n\n今見えているものがすべてだと決める前に、\n\n「本当にそうなのだろうか」\n\nと確かめる。\n\n陽炎の向こうに、本当の景色があります。",
      sacredSites: [{ mark: "★", name: "徳大寺 摩利支天", location: "東京都台東区" }, { mark: "○", name: "禅居庵 摩利支天堂", location: "京都府京都市" }], sacredSitesNote: "",
    },
    "28": {
      en: {
        title: "The Unknown", deityName: "Dainichi Nyorai", deityNote: "The Japanese form of Mahavairocana, the central Buddha of Esoteric Buddhism.", meaningTitle: "The Unknown",
        meaning: "What lies beyond the limits of what you currently understand.\n\nThis card represents mystery, uncertainty, and the reality that not everything can be explained from your present point of view.",
        myth: "Dainichi Nyorai is one of the most important figures in Esoteric Buddhism.\n\nThe name can be translated approximately as:\n\n“Great Sun Buddha.”\n\nHowever, Dainichi Nyorai is not simply a deity of the physical sun.\n\nIn Esoteric Buddhist thought, Dainichi Nyorai represents the fundamental truth of the universe itself.\n\nAll things arise within this greater reality.\n\nAll beings, forms, movements, and phenomena are understood as expressions of this cosmic truth.\n\nBecause Dainichi Nyorai represents a reality far larger than ordinary human perception, complete understanding cannot be reached through everyday thinking alone.\n\nEsoteric Buddhism therefore makes use of mandalas, mudras, mantras, ritual, and symbolic practices to approach truths that cannot easily be expressed in ordinary language.",
        connectionHeading: "Why This Deity Represents “The Unknown”",
        connection: "Human beings naturally want explanations.\n\nWe feel safer when we can understand:\n\nwhy something happened,\nwhat will happen next,\nand what everything means.\n\nBut some parts of life cannot be fully understood from where we stand now.\n\nDainichi Nyorai represents a reality greater than the limited perspective of the individual.\n\nFor this reason, in Kunimamori, Dainichi Nyorai represents:\n\nwhat exists beyond the boundaries of your current understanding.\n\nThe unknown is not automatically dangerous.\n\nSometimes it is simply something you have not yet reached.\n\nYou do not have to force an answer before its time.\n\nThere are moments when the most honest response is:\n\n“I do not know yet.”\n\nAnd that can be enough.",
        sacredSites: [{ mark: "★", name: "Enjo-ji", location: "Nara" }, { mark: "○", name: "To-ji", location: "Kyoto" }, { mark: "○", name: "Konpon Daito, Mount Koya", location: "Koya, Wakayama" }], sacredSitesNote: "",
      },
      id: "28", number: "28", special: false, title: "未知", deityName: "大日如来", reading: "だいにちにょらい", deityNote: "サンスクリット名はマハーヴァイローチャナ。\n真言密教の中心となる仏です。", meaningTitle: "未知",
      meaning: "まだ理解できないもの、見えていない世界、これから知る可能性。\n分からないことを恐れるだけではなく、その向こうに自分の理解を超えた大きな世界が存在することを表す。",
      myth: "大日如来は、人間として生まれて悟りを開いた釈迦如来とは少し性格が異なります。\n\n密教では、大日如来は宇宙そのものの真理を仏の姿として表した存在とされます。\n\n「大日」とは、大いなる太陽という意味。\n\nしかし普通の太陽よりもさらに大きく、その光は時間や場所に制限されることなく、すべてを照らすと考えられました。\n\n密教では、大日如来を中心として多くの如来・菩薩・明王などが配置されます。\n\nそれらは互いにばらばらな存在ではなく、大日如来の智慧や働きがさまざまな姿となって現れたものとして捉えられます。\n\n高野山の根本大塔でも、中央に胎蔵大日如来が祀られています。\n\n周囲には四仏や十六大菩薩などが配置され、堂内全体が立体の曼荼羅として造られています。\n\nつまり大日如来とは、私たちが普段見ている世界の奥にある、\n\n「すべてをつなぐ大きな真理」\n\nを象徴する仏なのです。",
      connectionHeading: "なぜ「未知」と結びつくのか",
      connection: "人は、分からないものを怖いと感じます。\n\n先が見えない。\n何が起きるか分からない。\n理解できない。\n\nでも、\n\n「分からない＝悪いこと」\n\nではありません。\n\n今の自分にはまだ理解できていないだけかもしれません。\n\n大日如来が表す密教世界は、人間の目に見える範囲よりはるかに大きな世界です。\n\n自分が理解できている部分は、その一部にすぎない。\n\nだから「國護り」では大日如来を、\n\nまだ見えていないものの中にも、大きな可能性と秩序が存在する\n\nという意味で「未知」のカードに重ねています。\n\nすべてを理解してから進むことはできません。\n\n分からないまま一歩を踏み出した時、\n初めて見えてくる世界もあります。",
      sacredSites: [{ mark: "★", name: "円成寺", location: "奈良県奈良市" }, { mark: "○", name: "東寺", location: "京都府京都市" }, { mark: "○", name: "高野山 根本大塔", location: "和歌山県高野町" }], sacredSitesNote: "",
    },
    "29": {
      en: {
        title: "Obstacles", deityName: "Futsunushi no Kami", deityNote: "A warrior deity closely associated with Katori Jingu.", meaningTitle: "Obstacles",
        meaning: "Something that prevents you from moving forward in the way you originally expected.\n\nThis card represents resistance, difficulty, and the need to reconsider how you approach a situation.",
        myth: "Futsunushi no Kami is a major deity in Japanese mythology and is particularly important in the Nihon Shoki traditions.\n\nDuring the process known as the Transfer of the Land, the heavenly deities repeatedly sent messengers to the earthly realm.\n\nHowever, earlier missions did not produce the intended result.\n\nSome messengers became attached to the earthly world.\n\nOthers failed to complete the task entrusted to them.\n\nEventually, powerful warrior deities were chosen for the mission.\n\nIn the Nihon Shoki, Futsunushi no Kami and Takemikazuchi no Kami descend together to confront the rulers of the earthly realm and bring the transfer of authority toward completion.\n\nFutsunushi later became deeply associated with Katori Jingu and with martial strength, protection, and the ability to overcome difficult situations.",
        connectionHeading: "Why This Deity Represents “Obstacles”",
        connection: "Futsunushi is not an obstacle.\n\nHe appears because obstacles already exist.\n\nPrevious attempts have failed.\nThe situation has not moved.\nA different kind of strength is now required.\n\nThis is the important point.\n\nAn obstacle does not always mean:\n\n“Stop.”\n\nSometimes it means:\n\n“This method is no longer enough.”\n\nFor this reason, in Kunimamori, Futsunushi no Kami represents:\n\nthe obstacle that forces you to discover a different approach.\n\nWhen something repeatedly refuses to move, simply pushing harder may not be the answer.\n\nYou may need a new method.\nA different perspective.\nMore strength.\nOr help from someone with abilities different from your own.\n\nAn obstacle can reveal what must change before progress becomes possible.",
        sacredSites: [{ mark: "★", name: "Katori Jingu", location: "Katori, Chiba" }, { mark: "○", name: "Kasuga Taisha", location: "Nara" }, { mark: "○", name: "Shiogama Jinja", location: "Shiogama, Miyagi" }], sacredSitesNote: "",
      },
      id: "29", number: "29", special: false, title: "障害", deityName: "経津主神", reading: "ふつぬしのかみ", deityNote: "香取神宮では「経津主大神」と称されます。", meaningTitle: "障害",
      meaning: "進もうとする道を塞いでいるもの。\nただの邪魔ではなく、乗り越えることで自分の力や覚悟が問われる壁を表す。",
      myth: "経津主神は、香取神宮の御祭神です。\n\n代表的な物語が「国譲り神話」です。\n\n高天原の神々は、葦原中国を治めるため何度か使者を遣わしました。\n\nしかし最初に遣わされた天穂日命は大国主神に従い、次の天若日子も使命を果たさず戻りませんでした。\n\nつまり、地上の平定は二度にわたってうまくいかなかったのです。\n\nそこで神々が改めて相談した結果、経津主神が適任であると選ばれます。\n\n武甕槌神も加わり、二柱は出雲へ降りました。\n\n稲佐の浜で剣を逆さに突き立てて武威を示し、大国主神に国譲りを求めます。\n\nさまざまなやり取りを経て、大国主神は国譲りを受け入れます。\n\n経津主神と武甕槌神はその後、国を平定して高天原へ復命したと伝えられています。",
      connectionHeading: "なぜ「障害」と結びつくのか",
      connection: "経津主神自身が「障害」なのではありません。\n\nむしろ、\n\n障害を前にした時に現れる力\n\nとしてこのカードに重ねています。\n\n国譲りの使命は、それ以前の使者では成し遂げられませんでした。\n\nすんなり進んだ道ではないのです。\n\n何度やってもうまくいかない。\n相手が動かない。\n道を塞ぐものがある。\n\nそんな状況で、\n\n「では、どう突破するのか」\n\nを問われます。\n\n経津主神は、困難な使命から退かず、必要な力を示し、最後まで役割を果たしました。\n\nだから「國護り」の「障害」は、\n\n「もう進めない」\n\nという意味だけではありません。\n\n目の前の壁によって、\n今までとは違う力や方法を求められている状態。\n\n壁があるからこそ、自分の本気や力が表に出てくることもあります。",
      sacredSites: [{ mark: "★", name: "香取神宮", location: "千葉県香取市" }, { mark: "○", name: "春日大社", location: "奈良県奈良市" }, { mark: "○", name: "鹽竈神社", location: "宮城県塩竈市" }], sacredSitesNote: "",
    },
    "30": {
      en: {
        title: "Sacrifice", deityName: "Ukemochi no Kami", deityNote: "A deity of food appearing in the Nihon Shoki.", meaningTitle: "Sacrifice",
        meaning: "Something that is lost, given up, or transformed in order for something else to continue or be born.\n\nThis card represents the reality that some forms of growth come with a cost.",
        myth: "The story of Ukemochi no Kami is recorded in the Nihon Shoki.\n\nAmaterasu Omikami sent Tsukuyomi no Mikoto to visit Ukemochi.\n\nWhen Tsukuyomi arrived, Ukemochi prepared a feast.\n\nShe produced food from her body and presented it as an offering.\n\nTsukuyomi was deeply offended by the way the food had been produced.\n\nIn anger, he killed Ukemochi.\n\nWhen Amaterasu learned what had happened, she was furious with Tsukuyomi and refused to meet him again.\n\nThis myth is used in the Nihon Shoki to explain why the sun and moon are separated between day and night.\n\nAfter Ukemochi’s death, new forms of nourishment appeared from her body.\n\nDifferent versions describe grains, animals, and other sources of food emerging from her remains.\n\nThese were then brought to Amaterasu and became sources of sustenance for the world.\n\nThe story is violent and tragic.\n\nYet from death and loss, the foods that support life emerge.",
        connectionHeading: "Why This Deity Represents “Sacrifice”",
        connection: "The story of Ukemochi does not present sacrifice as something simple or beautiful.\n\nSomething is lost.\n\nAnd that loss cannot simply be undone.\n\nAt the same time, what remains is transformed into nourishment for others.\n\nFor this reason, in Kunimamori, Ukemochi no Kami represents:\n\nthe cost that sometimes accompanies creation, change, or continuation.\n\nNot every sacrifice is necessary.\n\nAnd suffering should never be glorified simply because something good might come afterward.\n\nBut there are times when choosing one path means giving up another.\n\nTime may be spent.\nEnergy may be used.\nSomething familiar may have to end.\n\nThis card asks you to recognize the cost clearly.\n\nIf something must be given up, let it be for something you truly believe is worth carrying forward.",
        sacredSites: [{ mark: "★", name: "Ukemochi Jinja", location: "Tsubura, Kurashiki, Okayama" }, { mark: "○", name: "Ukemochi Jinja", location: "Yuwa Hiraodori, Akita" }], sacredSitesNote: "",
      },
      id: "30", number: "30", special: false, title: "代償", deityName: "保食神", reading: "うけもちのかみ", deityNote: "", meaningTitle: "代償",
      meaning: "何かを得るために、同時に失われるものがあること。\n選択や変化には、時間・労力・古い関係・これまでの自分など、何らかの形で差し出すものが生じることを表す。",
      myth: "保食神は、『日本書紀』の一書に登場する食物の神です。\n\n天照大神は月夜見尊に、\n\n「葦原中国に保食神という神がいるので訪ねてみなさい」\n\nと命じます。\n\n月夜見尊が訪れると、保食神は客をもてなすため、陸へ顔を向けて米飯を、海へ向けて魚を、山へ向けて獣などを口から出し、たくさんの食物を並べました。\n\nところが月夜見尊は、口から出したものでもてなされたことを「穢らわしい」と感じ、怒って保食神を殺してしまいます。\n\nそのことを知った天照大神は月夜見尊を強く責め、二柱が昼と夜に分かれて住むようになった理由としても語られています。\n\nしかし物語は、保食神の死だけでは終わりません。\n\nその身体から、\n\n牛や馬、\n粟、\n蚕、\n稗、\n稲、\n麦、\n大豆、\n小豆\n\nなどが生まれました。\n\n天照大神はそれらを人々が生きるための食物として定め、農耕や養蚕の起源へつながったと伝えられます。",
      connectionHeading: "なぜ「代償」と結びつくのか",
      connection: "この神話は、とても強烈です。\n\n一つの命が失われ、その身体から多くの命を支える食物が生まれる。\n\nもちろん、\n\n「何かを得るには誰かを犠牲にしなければならない」\n\nという意味ではありません。\n\n「國護り」で重ねているのは、\n\n新しいものが生まれる時、以前の形のままではいられないことがある\n\nという部分です。\n\n何かを選べば、選ばなかった道があります。\n\n新しい生活を始めれば、以前の生活は終わります。\n\n時間を注げば、その時間を別のことには使えません。\n\nつまり、どんな選択にも少なからず「代償」があります。\n\n保食神の物語では、失われたものが無意味に消えるのではなく、別の形となって命を支えるものへ変わっていきます。\n\nだから「國護り」の「代償」は、\n\nただ「何かを失う」というカードではありません。\n\n何を得るために、何を差し出すのか。\nそして差し出したものを、どのように次へ生かすのか。\n\nその問いを持つカードです。",
      sacredSites: [{ mark: "★", name: "保食神社", location: "岡山県倉敷市粒浦" }, { mark: "○", name: "保食神社", location: "秋田県秋田市雄和平尾鳥" }], sacredSitesNote: "",
    },
    "31": {
      en: {
        title: "Stagnation", deityName: "Miroku Bosatsu", deityNote: "The Japanese form of Maitreya, the future Buddha.", meaningTitle: "Stagnation",
        meaning: "A period when things do not seem to move forward.\n\nThis card represents waiting, delay, and the possibility that the time for action has not yet fully arrived.",
        myth: "Miroku Bosatsu is one of the most important bodhisattvas in Buddhism.\n\nAccording to Buddhist tradition, Miroku is currently waiting in Tushita Heaven and will one day descend into the human world.\n\nIn the distant future, after the teachings of Shaka Nyorai have disappeared, Miroku is destined to become the next Buddha and teach the Dharma.\n\nThis makes Miroku a unique figure.\n\nMiroku is already connected with awakening and salvation.\n\nAnd yet, the time for that role has not arrived.\n\nThe bodhisattva remains in a state of waiting until the appropriate moment comes.\n\nIn Japan, images of Miroku often express quiet contemplation and stillness.\n\nThis calm waiting became one of the strongest symbolic qualities associated with Miroku.",
        connectionHeading: "Why This Deity Represents “Stagnation”",
        connection: "Stagnation can feel like failure.\n\nNothing changes.\nNo answer comes.\nThe situation does not move.\n\nBut not every pause means that you have done something wrong.\n\nMiroku Bosatsu represents a being whose future role is already known, yet who still waits for the right time.\n\nFor this reason, in Kunimamori, Miroku Bosatsu represents:\n\nthe period when something is not moving because its time has not yet arrived.\n\nWaiting does not always mean doing nothing.\n\nIt may be a time to prepare.\nTo observe.\nTo mature.\nTo allow conditions to become ready.\n\nThis card asks you to consider:\n\n“Is this truly blocked, or is it simply not time yet?”",
        sacredSites: [{ mark: "★", name: "Koryu-ji", location: "Kyoto" }, { mark: "○", name: "Chugu-ji", location: "Ikaruga, Nara" }, { mark: "○", name: "Miroku-do, Muro-ji", location: "Uda, Nara" }], sacredSitesNote: "",
      },
      id: "31", number: "31", special: false, title: "停滞", deityName: "弥勒菩薩", reading: "みろくぼさつ", deityNote: "", meaningTitle: "停滞",
      meaning: "まだ動く時ではない状態。\n結果が見えず、物事が止まっているように感じても、その時間の中で準備されているものがあることを表す。",
      myth: "弥勒菩薩は、仏教において未来にこの世界へ現れる仏とされています。\n\n釈迦如来がこの世を去った後、弥勒菩薩は兜率天で修行を続け、はるかな未来に人間世界へ降り、悟りを開いて人々を救うと説かれています。\n\nつまり弥勒菩薩は、\n\n「まだ現れていない仏」\n\nなのです。\n\n日本では古くから弥勒信仰が広まりました。\n\n京都の広隆寺には、右足を左膝に乗せ、頬に指を添えて静かに思索する有名な弥勒菩薩半跏思惟像があります。\n\nその姿は、今すぐ何かを起こそうとする姿ではありません。\n\n静かに座り、考え、時を待つ姿です。",
      connectionHeading: "なぜ「停滞」と結びつくのか",
      connection: "「停滞」という言葉には、\n\n何も進んでいない。\n遅れている。\nうまくいっていない。\n\nという悪い印象があります。\n\nでも弥勒菩薩は、\n\nまだその時が来ていないから、現れていない。\n\n未来に役割を果たすことが決まっていても、その時までは待つのです。\n\nだから「國護り」の「停滞」は、\n\n「何も起きていない時間＝無駄な時間」\n\nとは考えません。\n\n外から見れば止まっているようでも、内側では考えが深まり、準備が整い、次の時を迎えるための時間になっていることがあります。\n\n動かないことと、終わったことは違います。\n\n今はまだ、動く時ではないだけかもしれません。",
      sacredSites: [{ mark: "★", name: "広隆寺", location: "京都府京都市" }, { mark: "○", name: "中宮寺", location: "奈良県斑鳩町" }, { mark: "○", name: "室生寺 弥勒堂", location: "奈良県宇陀市" }], sacredSitesNote: "",
    },
    "32": {
      en: {
        title: "Change", deityName: "Kumano Gongen", deityNote: "A collective sacred identity connected with the deities of the three great Kumano shrines.\n\nKumano worship developed through a deep blending of Shinto and Buddhism.", meaningTitle: "Change",
        meaning: "Moving from one state into another.\n\nThis card represents transition, transformation, and the process of leaving behind an old condition in order to enter something new.",
        myth: "Kumano worship developed around the sacred landscape of the Kii Peninsula.\n\nThe three major shrines are:\n\nKumano Hongu Taisha\nKumano Hayatama Taisha\nKumano Nachi Taisha\n\nTogether, they are known as the Kumano Sanzan.\n\nOver centuries, Kumano became one of Japan’s most important pilgrimage destinations.\n\nPeople from many different backgrounds traveled difficult mountain routes in order to reach the sacred sites.\n\nThe pilgrimage itself became part of the spiritual experience.\n\nTravelers left their ordinary surroundings, crossed mountains and rivers, and entered a landscape understood as sacred.\n\nKumano was also strongly influenced by shinbutsu-shugo, the historical blending of kami worship and Buddhism.\n\nThe Kumano deities were interpreted together with Buddhist figures, and the sacred region became associated with death, rebirth, purification, and renewal.\n\nFor many pilgrims, visiting Kumano symbolically meant entering another world and returning transformed.",
        connectionHeading: "Why This Deity Represents “Change”",
        connection: "Change often begins with leaving something familiar.\n\nA pilgrimage works in the same way.\n\nYou leave home.\nYou cross a boundary.\nYou walk through unfamiliar terrain.\nAnd when you return, you are not exactly the same person who left.\n\nKumano represents movement between worlds:\n\nthe ordinary and the sacred,\nthe old self and the renewed self,\nending and beginning.\n\nFor this reason, in Kunimamori, Kumano Gongen represents:\n\nthe transformation that occurs when you cross from one stage of life into another.\n\nChange can be unsettling because the old shape of your life may no longer fit.\n\nBut crossing that boundary can also open the way to something new.",
        sacredSites: [{ mark: "★", name: "Kumano Hongu Taisha", location: "Tanabe, Wakayama" }, { mark: "★", name: "Kumano Hayatama Taisha", location: "Shingu, Wakayama" }, { mark: "★", name: "Kumano Nachi Taisha", location: "Nachikatsuura, Wakayama" }], sacredSitesNote: "",
      },
      id: "32", number: "32", special: false, title: "変化", deityName: "熊野権現", reading: "くまのごんげん", deityNote: "熊野三山に祀られる神々を、神仏習合の中で総称した呼び名です。", meaningTitle: "変化",
      meaning: "今までの状態を離れ、新しい状態へ移っていくこと。\n古い形を保ち続けるのではなく、経験を通して自分自身が変わり、新しい段階へ進むことを表す。",
      myth: "熊野信仰は、一柱の神の神話だけではなく、長い歴史の中で神道と仏教が重なり合って形成されました。\n\n熊野本宮大社、熊野速玉大社、熊野那智大社の三社を熊野三山と呼びます。\n\n平安時代以降、熊野の神々は仏と結びつけて考えられるようになり、「熊野権現」と呼ばれました。\n\nそして熊野には、上皇や貴族だけでなく、のちには武士や庶民まで多くの人々が参詣しました。\n\n険しい山道を長い時間歩き、俗世から神域へ入り、熊野の神々へ祈る。\n\n熊野詣は、ただ目的地を見る旅ではありません。\n\n道を歩き、祓い清め、神域へ入り、再び日常へ帰っていく。\n\nその過程そのものが、人を以前とは違う状態へ移していく信仰の旅でもありました。",
      connectionHeading: "なぜ「変化」と結びつくのか",
      connection: "熊野には、\n\n「境界を越えて、違う世界へ入る」\n\nという性格があります。\n\n日常を離れ、山へ入る。\n祓い清める。\n神と仏が重なった世界に触れる。\nそして再び日常へ戻る。\n\n帰ってくる場所は同じでも、経験した自分は以前とまったく同じではありません。\n\n「変化」とは、すべてを捨てて別人になることではありません。\n\nこれまでの経験を抱えたまま、新しい自分の状態へ移ること。\n\nそのため「國護り」では熊野権現を、人生の節目を越えていく「変化」の象徴としています。",
      sacredSites: [{ mark: "★", name: "熊野本宮大社", location: "和歌山県田辺市" }, { mark: "★", name: "熊野速玉大社", location: "和歌山県新宮市" }, { mark: "★", name: "熊野那智大社", location: "和歌山県那智勝浦町" }], sacredSitesNote: "",
    },
    "33": {
      en: {
        title: "Collapse", deityName: "Susanoo no Mikoto", deityNote: "Also written as Susanoo no Mikoto or Susanoo no Kami.", meaningTitle: "Collapse",
        meaning: "The breaking apart of a structure, situation, or way of living that can no longer remain as it was.\n\nThis card represents disruption, destruction, and the moment when what once seemed stable suddenly falls apart.",
        myth: "Susanoo no Mikoto is one of the Three Noble Children born from the purification of Izanagi no Mikoto.\n\nHe was entrusted with rule over the seas.\n\nHowever, Susanoo continued to grieve for his mother and caused great disorder.\n\nHe eventually went to Takamagahara, where his actions became increasingly violent.\n\nAmong the acts described in the Kojiki, he destroyed rice-field boundaries, interfered with sacred agricultural rites, and committed acts that deeply disturbed the heavenly realm.\n\nThe final incident caused such distress that Amaterasu Omikami withdrew into the Heavenly Rock Cave.\n\nWhen the sun goddess disappeared, darkness spread through both Heaven and Earth.\n\nThe order of the world collapsed.\n\nThe other deities eventually brought Amaterasu back, and Susanoo was punished and expelled from Takamagahara.\n\nBut his story did not end there.\n\nAfter descending to the earthly realm, Susanoo changed.\n\nHe encountered a family threatened by Yamata-no-Orochi, defeated the serpent, and rescued Kushinadahime.\n\nThe deity who once caused disorder became a hero who restored order.",
        connectionHeading: "Why This Deity Represents “Collapse”",
        connection: "Susanoo shows both sides of collapse.\n\nFirst, his uncontrolled actions destroy the balance of the heavenly world.\n\nSomething stable breaks apart.\n\nBut after that collapse, his own life also changes.\n\nHe leaves Takamagahara.\nHe enters a new stage.\nHe becomes capable of acting differently.\n\nFor this reason, in Kunimamori, Susanoo no Mikoto represents:\n\nthe collapse of a form that can no longer continue.\n\nCollapse is painful.\n\nIt may feel like everything has gone wrong.\n\nBut sometimes what breaks apart was already unable to remain as it was.\n\nThe end of one structure can become the place where a completely different way of living begins.",
        sacredSites: [{ mark: "★", name: "Susa Jinja", location: "Izumo, Shimane" }, { mark: "○", name: "Yasaka Jinja", location: "Kyoto" }, { mark: "○", name: "Kumano Taisha", location: "Matsue, Shimane" }], sacredSitesNote: "",
      },
      id: "33", number: "33", special: false, title: "崩壊", deityName: "須佐之男命", reading: "すさのおのみこと", deityNote: "「須佐能袁命」「素戔嗚尊」などとも表記されます。", meaningTitle: "崩壊",
      meaning: "これまで保たれていた秩序や形が、一度大きく崩れること。\n突然の出来事によって、それまで当たり前だったものが維持できなくなる状態を表す。\n\nしかし同時に、古い形が崩れた後に新しい流れが始まる可能性も含む。",
      myth: "須佐之男命は、伊邪那岐命の禊によって天照大御神、月読命とともに生まれた三貴子の一柱です。\n\nしかし高天原での須佐之男命は、非常に激しい行動を取ります。\n\n田の畔を壊し、溝を埋め、神聖な御殿を汚すなど、天照大御神が治める高天原の秩序を乱していきました。\n\nそして最後には、機織りをしていた神聖な建物へ皮を剥いだ馬を投げ込みます。\n\n驚いた機織女が亡くなる出来事まで起こり、天照大御神は天岩戸へ籠もってしまいました。\n\n太陽神が姿を隠したことで、高天原も葦原中国も暗闇となり、さまざまな災いが起こります。\n\nひとりの激しい行動によって、それまで保たれていた世界の秩序そのものが崩れてしまったのです。\n\nしかし須佐之男命の物語は、そこで終わりません。\n\n高天原を追放された後、出雲へ降り、八岐大蛇を退治し、櫛名田比売を救います。\n\nつまり須佐之男命自身も、崩壊の後に別の姿へ変わっていく神なのです。",
      connectionHeading: "なぜ「崩壊」と結びつくのか",
      connection: "須佐之男命の高天原での行動は、少し問題が起きたという程度ではありません。\n\nその結果、太陽そのものが世界から消えるほどの事態が起こりました。\n\nそれまでの秩序が保てなくなったのです。\n\nだから「國護り」では須佐之男命を、\n\n「今までの形が維持できなくなる崩壊」\n\nの象徴としています。\n\nでも「崩壊」は、すべての終わりとは限りません。\n\n須佐之男命自身が、高天原を追われた後に八岐大蛇を倒す神へ変わったように、\n\n古い形が壊れたからこそ、それまでとは違う生き方が始まることもあります。",
      sacredSites: [{ mark: "★", name: "須佐神社", location: "島根県出雲市" }, { mark: "○", name: "八坂神社", location: "京都府京都市" }, { mark: "○", name: "熊野大社", location: "島根県松江市" }], sacredSitesNote: "",
    },
    "34": {
      en: {
        title: "Loss", deityName: "Nakisawame no Kami", deityNote: "A goddess born from the tears of Izanagi no Mikoto.", meaningTitle: "Loss",
        meaning: "The pain created when something precious is no longer there.\n\nThis card represents grief, absence, and the emotions that arise when a relationship, place, possibility, or part of life has been lost.",
        myth: "The story of Nakisawame no Kami is closely connected with the death of Izanami no Mikoto.\n\nIzanami died after being severely burned while giving birth to the fire deity Kagutsuchi.\n\nIzanagi no Mikoto was overwhelmed by grief.\n\nHe wept beside her body.\n\nFrom the tears that fell as he mourned, a goddess was born.\n\nThat goddess was Nakisawame no Kami.\n\nThe Kojiki therefore gives this deity an unusually direct origin.\n\nShe is born not from victory, creation, or celebration.\n\nShe is born from grief itself.\n\nThe myth does not tell a long story about Nakisawame afterward.\n\nBut the moment of her birth preserves something deeply human within the myth:\n\neven a god weeps when someone irreplaceable is lost.",
        connectionHeading: "Why This Deity Represents “Loss”",
        connection: "Loss is not an abstract idea in this story.\n\nIzanagi has lost Izanami.\n\nHe cannot simply decide not to feel pain.\n\nHe cries.\n\nAnd from those tears, Nakisawame is born.\n\nFor this reason, in Kunimamori, Nakisawame no Kami represents:\n\nthe grief that naturally follows the loss of something precious.\n\nSadness does not mean weakness.\n\nTears do not mean that you are failing to move forward.\n\nSometimes grief is simply evidence that something mattered deeply.\n\nThis card does not ask you to hurry and become positive again.\n\nIt allows you to recognize the place where something is gone.",
        sacredSites: [{ mark: "★", name: "Uneo Tsutamoto Jinja", location: "Kashihara, Nara" }], sacredSitesNote: "",
      },
      id: "34", number: "34", special: false, title: "喪失", deityName: "泣沢女神", reading: "なきさわめのかみ", deityNote: "", meaningTitle: "喪失",
      meaning: "大切なものを失った悲しみ。\nすぐに前向きになろうとせず、失ったものの大きさを認め、悲しむ時間そのものを受け入れることを表す。",
      myth: "伊邪那美命は、火之迦具土神を産んだ際に大きな火傷を負い、亡くなってしまいます。\n\n妻を失った伊邪那岐命は、深い悲しみに包まれました。\n\n亡くなった伊邪那美命のもとに伏し、泣き続けます。\n\nそして、\n\n「伊邪那岐命が流した涙から生まれた神」\n\nが泣沢女神です。\n\nつまり泣沢女神は、何かを失った後に残る「涙」そのものから生まれた女神なのです。\n\n奈良県橿原市の畝尾都多本神社は「哭澤の神社」とも呼ばれ、哭澤女神を御祭神とします。",
      connectionHeading: "なぜ「喪失」と結びつくのか",
      connection: "これはほとんど、そのままです。\n\n泣沢女神は、\n\n「大切な存在を失った悲しみの涙から生まれた神」\n\nです。\n\nだから「國護り」の「喪失」は、\n\n「早く忘れよう」\n「前向きになろう」\n\nというカードではありません。\n\n悲しいなら、悲しんでいい。\n\n失ったものが大きければ、その分だけ涙が出るのは自然なことです。\n\n涙は弱さではありません。\n\nそれほど大切なものがあったという証でもあります。\n\n泣沢女神は、\n\n悲しみを消すのではなく、悲しむことそのものを許してくれる存在\n\nとして「喪失」のカードと重なります。",
      sacredSites: [{ mark: "★", name: "畝尾都多本神社", location: "奈良県橿原市" }], sacredSitesNote: "",
    },
    "35": {
      en: {
        title: "Ending", deityName: "Chigaeshi no Okami", deityNote: "A divine name associated with the great rock that sealed the entrance to Yomi.\n\nAlso connected with the name Sayarimasuyomido no Okami in the Kojiki tradition.", meaningTitle: "Ending",
        meaning: "Recognizing that something has truly come to an end and closing the path back to what can no longer be restored.\n\nThis card represents finality, separation, and the acceptance that a particular chapter cannot continue in its former form.",
        myth: "After Izanami no Mikoto died, Izanagi no Mikoto followed her into Yomi, the land of the dead.\n\nHe wanted to bring her back.\n\nAt first, Izanami said that she would consult the deities of Yomi.\n\nShe warned Izanagi not to look at her.\n\nBut Izanagi eventually broke the promise and saw her transformed body.\n\nTerrified, he fled.\n\nIzanami, humiliated and enraged, pursued him together with the beings of Yomi.\n\nIzanagi finally reached Yomotsu Hirasaka, the slope that formed the boundary between Yomi and the living world.\n\nThere, he placed a huge rock across the passage.\n\nThe rock sealed the road between the worlds.\n\nStanding on opposite sides of the barrier, Izanagi and Izanami exchanged final words.\n\nThe relationship that had once created the land and many gods could no longer continue as before.\n\nThe enormous rock itself received a divine name and came to be associated with Chigaeshi no Okami.",
        connectionHeading: "Why This Deity Represents “Ending”",
        connection: "No.34, Loss, represents the pain of realizing that someone or something is gone.\n\nNo.35 goes one step further.\n\nThe road is closed.\n\nThe boundary is placed.\n\nThere is no return to the relationship exactly as it existed before.\n\nThis is why Chigaeshi no Okami represents:\n\nthe moment when an ending is finally acknowledged.\n\nEnding does not erase what happened.\n\nIt does not mean that the past had no value.\n\nIt means accepting that the path leading back to the old form has been closed.\n\nSome endings are necessary precisely because continuing to return to the same place prevents a new life from beginning.",
        sacredSites: [{ mark: "★", name: "Kurihara Jinja", location: "Zama, Kanagawa" }, { mark: "○", name: "Yomotsu Hirasaka", location: "Matsue, Shimane" }, { mark: "○", name: "Iya Jinja", location: "Matsue, Shimane" }], sacredSitesNote: "",
      },
      id: "35", number: "35", special: false, title: "終焉", deityName: "道反之大神", reading: "ちがえしのおおかみ", deityNote: "別名\n塞坐黄泉戸大神\nふさがりますよもつとのおおかみ", meaningTitle: "終焉",
      meaning: "一つの物語が完全に終わること。\n以前の状態には戻れないことを受け入れ、境界を閉じ、次の世界へ進むための区切りをつけることを表す。",
      myth: "伊邪那美命を失った伊邪那岐命は、妻を取り戻そうとして黄泉国へ向かいます。\n\nしかし伊邪那美命はすでに黄泉の国の食物を口にしており、簡単には戻ることができませんでした。\n\n伊邪那岐命は「自分の姿を見ないでほしい」という約束を破り、変わり果てた伊邪那美命の姿を見てしまいます。\n\n恐ろしくなった伊邪那岐命は黄泉国から逃げます。\n\n伊邪那美命は黄泉の神々を遣わして追わせ、最後には自ら追いかけてきました。\n\n伊邪那岐命は黄泉比良坂まで逃げると、\n\n千人がかりでなければ動かせないほど巨大な岩を置き、黄泉国への道を塞ぎます。\n\nこの岩につけられた神名が、\n\n「道反之大神」\n\nです。\n\n岩を挟み、伊邪那岐命と伊邪那美命は最後の言葉を交わします。\n\n伊邪那美命が一日に千人を死なせると告げると、伊邪那岐命は一日に千五百の産屋を建てると答えました。\n\nこうして生と死の世界が完全に分かれたと、『古事記』は語ります。",
      connectionHeading: "なぜ「終焉」と結びつくのか",
      connection: "伊邪那岐命は、一度は伊邪那美命を取り戻そうとしました。\n\nでも最後には、\n\n「戻るための道そのものを岩で塞ぎます。」\n\nここが重要です。\n\nまだ好きかもしれない。\nまだ悲しいかもしれない。\n本当なら元に戻したかったかもしれない。\n\nそれでも、\n\nもう戻れないものがある。\n\n道反之大神は、その現実に区切りをつける巨大な石です。\n\nだから「國護り」では、\n\n終わったものを終わったものとして受け入れ、境界を閉じること\n\nを「終焉」としています。\n\n終焉は、失敗ではありません。\n\n一つの物語を閉じなければ、次の物語へ進めないことがあります。\n\n扉を閉じることもまた、人生に必要な選択なのです。",
      sacredSites: [{ mark: "★", name: "栗原神社", location: "神奈川県座間市" }, { mark: "○", name: "黄泉比良坂", location: "島根県松江市" }, { mark: "○", name: "揖夜神社", location: "島根県松江市" }], sacredSitesNote: "",
    },
    "36": {
      en: {
        title: "Release", deityName: "Seoritsuhime", deityNote: "A purification deity named in the Great Purification Prayer, the Oharae no Kotoba.", meaningTitle: "Release",
        meaning: "Letting go of what has become unnecessary, heavy, or stagnant.\n\nThis card represents cleansing, flow, and the process of allowing burdens to move away rather than continuing to hold them.",
        myth: "Seoritsuhime is not a central figure in the Kojiki or Nihon Shoki narratives.\n\nShe is best known from the Oharae no Kotoba, the Great Purification Prayer used in Shinto ritual.\n\nIn this prayer, sins, impurities, and defilements are removed through ritual purification and carried away.\n\nSeoritsuhime is described as a deity who dwells in the swift currents of rivers.\n\nWhat has been purified is carried downstream by the flowing water and taken toward the sea.\n\nThe process does not end with simply identifying impurity.\n\nIt continues through movement.\n\nWhat no longer belongs is carried away.\n\nBecause of this role, Seoritsuhime became strongly associated with purification, flowing water, and the release of spiritual impurity.",
        connectionHeading: "Why This Deity Represents “Release”",
        connection: "Release is not the same as pretending something never happened.\n\nIt is allowing what has already served its purpose to move on.\n\nWater does not hold everything in one place.\n\nIt flows.\n\nIt carries.\nIt cleanses.\nIt continues onward.\n\nSeoritsuhime represents this movement.\n\nFor this reason, in Kunimamori, Seoritsuhime represents:\n\nthe act of letting what is no longer needed leave your hands and return to the flow.\n\nYou do not have to keep carrying every emotion, memory, responsibility, or pain forever.\n\nSome things can be acknowledged, purified, and allowed to pass.",
        sacredSites: [{ mark: "★", name: "Hayachine Jinja", location: "Iwate" }, { mark: "○", name: "Hayachine Jinja, Tono", location: "Tono, Iwate" }], sacredSitesNote: "",
      },
      id: "36", number: "36", special: false, title: "解放", deityName: "瀬織津姫", reading: "せおりつひめ", deityNote: "「瀬織津比売」とも表記されます。", meaningTitle: "解放",
      meaning: "抱え続けてきたものを、自分の内側から外へ流していくこと。\n罪悪感、過去へのこだわり、重くなった感情などを手放し、本来の自分へ戻っていくことを表す。",
      myth: "瀬織津姫は、『古事記』の物語に大きく登場する神ではありません。\n\nその名が重要な形で現れるのが、神道の代表的な祝詞である「大祓詞」です。\n\n大祓詞では、人々の罪や穢れが祓われた後、それらを運び去る神々が語られます。\n\nその最初に登場するのが瀬織津比売です。\n\n瀬織津比売は、山々から勢いよく流れ落ちる速い川の瀬にいて、\n\n「祓われた罪や穢れを大海原へ運び出す」\n\n神として描かれています。\n\nその後、海へ運ばれたものを速開都比売が呑み込み、気吹戸主が根の国・底の国へ吹き放ち、速佐須良比売が消し去るという流れが続きます。\n\nつまり瀬織津姫は、\n\n「不要になったものを、その場所に留めず流れへ返す役割」\n\nを担う神なのです。",
      connectionHeading: "なぜ「解放」と結びつくのか",
      connection: "解放とは、\n\n「無理やり忘れること」\n\nではありません。\n\nずっと握りしめてきたものを、\n\n「もうここに置いておかなくてもいい」\n\nと手から離すことです。\n\n瀬織津姫が罪や穢れを川から大海原へ運ぶように、\n\n感情も、経験も、過去も、\n留め続けなければ流れていきます。\n\nだから「國護り」では瀬織津姫を、\n\n自分の中で役目を終えたものを流し、本来の状態へ戻る「解放」\n\nの象徴としています。\n\n手放した後に残るのは、何もない空白ではありません。\n\n余計なものがなくなったことで、新しいものを受け取れる場所が生まれるのです。",
      sacredSites: [{ mark: "★", name: "早池峯神社", location: "岩手県" }, { mark: "○", name: "遠野・早池峯神社", location: "岩手県遠野市" }], sacredSitesNote: "",
    },
    "37": {
      en: {
        title: "Rebirth", deityName: "Yakushi Nyorai", deityNote: "The Medicine Buddha, known in Sanskrit as Bhaisajyaguru.", meaningTitle: "Rebirth",
        meaning: "Recovering after suffering and entering a new stage of life.\n\nThis card represents healing, restoration, and the ability to rise again after weakness, illness, loss, or exhaustion.",
        myth: "Yakushi Nyorai is one of the most widely revered Buddhas in Japan.\n\nHe is associated especially with healing, medicine, and relief from suffering.\n\nIn Buddhist tradition, before attaining Buddhahood, Yakushi made twelve great vows.\n\nThese vows included promises connected with healing, protection, nourishment, freedom from suffering, and helping beings move toward awakening.\n\nYakushi Nyorai is often depicted holding a medicine jar in one hand.\n\nThis jar symbolizes the medicine that relieves suffering.\n\nIn Japan, devotion to Yakushi became especially important in prayers for recovery from illness and protection of health.\n\nTemples such as Yakushi-ji and Shin-Yakushi-ji became major centers of this faith.",
        connectionHeading: "Why This Deity Represents “Rebirth”",
        connection: "Healing does not always mean returning to exactly who you were before.\n\nAfter suffering, a person may emerge changed.\n\nSomething may have been lost.\n\nSomething may have been learned.\n\nA new way of living may begin.\n\nThis is why the card is not simply called “Healing.”\n\nIn Kunimamori, Yakushi Nyorai represents:\n\nthe process of recovering and beginning again in a new form.\n\nRebirth does not erase the past.\n\nIt includes what you have been through and allows life to move forward from there.\n\nSometimes becoming well again means becoming someone slightly different from who you were before.",
        sacredSites: [{ mark: "★", name: "Yakushi-ji", location: "Nara" }, { mark: "○", name: "Shin-Yakushi-ji", location: "Nara" }], sacredSitesNote: "",
      },
      id: "37", number: "37", special: false, title: "再生", deityName: "薬師如来", reading: "やくしにょらい", deityNote: "正式には\n薬師瑠璃光如来\nやくしるりこうにょらい\n\n「医王如来」とも呼ばれます。", meaningTitle: "再生",
      meaning: "傷ついたものが癒え、もう一度生きる力を取り戻していくこと。\n以前とまったく同じ状態へ戻るのではなく、経験を経た自分として新しく立ち上がることを表す。",
      myth: "薬師如来は、病や苦しみから人々を救う仏として信仰されてきました。\n\n薬師如来は悟りを開く以前、菩薩として修行していた時に、\n\n人々の病を癒し、苦しみを除き、健やかに生きられるようにする\n\nなど十二の大願を立てたと説かれます。\n\nその願いを成就して仏となったのが薬師如来です。\n\n日本では古くから病気平癒や身体健全を願う信仰が広まりました。\n\n奈良の薬師寺も、天武天皇が皇后、後の持統天皇の病気平癒を願って680年に建立を発願した寺院です。\n\n薬師如来は、来世だけではなく、\n\n「今この世界で苦しんでいる人を救う仏」\n\nとして厚く信仰されてきました。",
      connectionHeading: "なぜ「再生」と結びつくのか",
      connection: "「再生」は、\n\n何もなかった頃へ完全に戻ることではありません。\n\n傷ついたこと。\n苦しかったこと。\n一度崩れたこと。\n\nそれらを経験したあとで、\n\n「もう一度、自分の力を取り戻すこと」\n\nです。\n\n薬師如来が象徴する癒しは、その流れと重なります。\n\n病が癒える。\n弱っていたものが力を取り戻す。\nもう一度、日常へ戻っていく。\n\nだから「國護り」では薬師如来を、\n\n一度弱ったものが再び生命力を取り戻す「再生」\n\nの象徴としています。\n\n再生したものは、以前とまったく同じではありません。\n\n傷を知ったからこそ持てる強さもあります。",
      sacredSites: [{ mark: "★", name: "薬師寺", location: "奈良県奈良市" }, { mark: "○", name: "新薬師寺", location: "奈良県奈良市" }], sacredSitesNote: "",
    },
    "38": {
      en: {
        title: "Truth", deityName: "Yata-no-Kagami", deityNote: "One of the Three Sacred Treasures of Japan.", meaningTitle: "Truth",
        meaning: "Seeing what is actually there without distortion.\n\nThis card represents clarity, self-recognition, and the ability to face reality without replacing it with what you hope, fear, or assume to be true.",
        myth: "Yata-no-Kagami plays a central role in the myth of Ama-no-Iwato, the Heavenly Rock Cave.\n\nAfter Amaterasu Omikami withdrew into the cave, the world was covered in darkness.\n\nThe assembled deities created a plan to bring her back.\n\nAmong the sacred objects prepared for the ritual was a mirror made by Ishikoridome no Mikoto.\n\nThe mirror was hung from a sacred sakaki tree together with jewels and other ritual offerings.\n\nOutside the cave, Ame-no-Uzume danced, and the gods began to laugh.\n\nCurious about the celebration, Amaterasu opened the rock door slightly.\n\nThe gods told her that a deity even greater than herself had appeared.\n\nWhen she looked outside, she saw the shining figure before her.\n\nIt was her own reflection in the mirror.\n\nAs Amaterasu moved closer to look, Ame-no-Tajikarao no Kami drew her out of the cave.\n\nLight returned to the world.\n\nThe sacred mirror was later passed down as one of the treasures associated with the heavenly lineage.",
        connectionHeading: "Why This Sacred Object Represents “Truth”",
        connection: "A mirror does not tell you what you want to see.\n\nIt reflects what stands before it.\n\nIn the Ama-no-Iwato story, Amaterasu encounters her own image.\n\nThe moment is especially powerful because the truth she sees is not something far away.\n\nIt is herself.\n\nFor this reason, in Kunimamori, Yata-no-Kagami represents:\n\nthe truth that becomes visible when you look without turning away.\n\nTruth can sometimes be uncomfortable.\n\nBut it can also restore light.\n\nYou may discover that the answer you were searching for outside yourself has been reflected back to you all along.",
        sacredSites: [{ mark: "★", name: "Kotai Jingu, Ise Jingu", location: "Ise, Mie" }, { mark: "○", name: "Amano Iwato Jinja", location: "Takachiho, Miyazaki" }], sacredSitesNote: "",
      },
      id: "38", number: "38", special: false, title: "真実", deityName: "八咫鏡", reading: "やたのかがみ", deityNote: "三種の神器の一つとされる神鏡です。", meaningTitle: "真実",
      meaning: "思い込みや飾りを取り除き、ありのままを見ること。\n自分自身や目の前の現実を、都合よく変えることなく見つめることを表す。",
      myth: "八咫鏡が重要な役割を果たすのが「天岩戸神話」です。\n\n天照大御神が岩戸へ籠もったことで、世界から光が失われました。\n\n八百万の神々は天照大御神を外へ出すために策を考え、八咫鏡と八尺瓊勾玉を榊に掛けました。\n\n天宇受売命が舞い、神々が笑う声を聞いた天照大御神は、岩戸を少し開きます。\n\nすると、そこに置かれていた八咫鏡へ天照大御神自身の姿が映りました。\n\n天照大御神は、鏡に映る光り輝く存在を見て興味を持ち、さらに外を覗こうとします。\n\nその瞬間、天手力男神が岩戸を開き、世界に光が戻りました。\n\nその後、八咫鏡は天照大御神から邇邇芸命へ授けられ、\n\n「この鏡を私自身と思って祀りなさい」\n\nという趣旨の神勅とともに受け継がれます。\n\n現在、伊勢神宮内宮では八咫鏡が天照大御神の御神体として祀られていると伝えられています。",
      connectionHeading: "なぜ「真実」と結びつくのか",
      connection: "鏡は、\n\n見たいものを見せてくれる道具ではありません。\n\nそこにあるものを、そのまま映します。\n\n天岩戸の中にいた天照大御神も、鏡によって自分自身の姿を見ることになります。\n\nだから「國護り」では八咫鏡を、\n\n自分自身をありのままに映し出す「真実」\n\nの象徴としています。\n\n真実は、いつも心地よいものとは限りません。\n\n見たくない部分が映ることもあります。\n\nでも、現実を正しく見なければ、本当に必要な選択をすることもできません。\n\n鏡は判断しません。\n\nただ、そこにあるものを映します。",
      sacredSites: [{ mark: "★", name: "伊勢神宮 皇大神宮・内宮", location: "三重県伊勢市" }, { mark: "○", name: "天岩戸神社", location: "宮崎県高千穂町" }], sacredSitesNote: "",
    },
    "39": {
      en: {
        title: "Circulation", deityName: "Takaokami no Kami", deityNote: "Kuraokami no Kami\n\nWater deities associated with rain, water sources, and the movement of water through the natural world.", meaningTitle: "Circulation",
        meaning: "Allowing energy, resources, emotions, and blessings to move rather than remain stagnant.\n\nThis card represents flow, exchange, renewal, and the cycle through which what leaves eventually returns in another form.",
        myth: "Takaokami no Kami and Kuraokami no Kami are ancient deities associated with water.\n\nTheir names appear in traditions connected with the birth of deities following the death of Kagutsuchi, the fire god.\n\nWater was essential to agriculture and daily survival.\n\nRain fell on mountains.\n\nWater gathered in springs and rivers.\n\nRivers carried it toward the sea.\n\nFrom there, water eventually returned to the sky and once again fell as rain.\n\nAlthough ancient mythology does not describe this modern scientific water cycle in those terms, water worship naturally developed around the visible movement of water through mountains, valleys, rivers, fields, and human life.\n\nTakaokami became especially associated with water and rain worship at places such as Kifune Jinja.\n\nKuraokami is also connected with deep water, valleys, and water sources in various traditions.\n\nTogether, these deities express the sacred power of water that continues to move through the world.",
        connectionHeading: "Why These Deities Represent “Circulation”",
        connection: "Water survives because it moves.\n\nWhen it stops completely, it can become stagnant.\n\nWhen it flows, it nourishes life.\n\nRain falls.\nThe earth receives it.\nRivers carry it.\nThe sea gathers it.\nAnd the cycle begins again.\n\nFor this reason, in Kunimamori, Takaokami no Kami and Kuraokami no Kami represent:\n\nthe circulation that keeps life from becoming stagnant.\n\nThis applies to more than water.\n\nMoney.\nKindness.\nKnowledge.\nEmotion.\nSupport.\nEnergy.\n\nWhat is received can be used.\n\nWhat is used can be passed onward.\n\nAnd what is released may return in a different form.",
        sacredSites: [{ mark: "★", name: "Kifune Jinja", location: "Kyoto" }, { mark: "★", name: "Keyakurotatsu Jinja", location: "Fukui" }, { mark: "○", name: "Niu Kawakami Jinja", location: "Nara" }], sacredSitesNote: "",
      },
      id: "39", number: "39", special: false, title: "循環", deityName: "高龗神・闇龗神", reading: "たかおかみのかみ・くらおかみのかみ", deityNote: "高龗神\nたかおかみのかみ\n\n闇龗神\nくらおかみのかみ\n\nともに水を司る龍神として信仰されてきた神々です。", meaningTitle: "循環",
      meaning: "一つの場所に留まらず、受け取り、流し、また次へ巡らせること。\n終わりと始まり、与えることと受け取ることがつながり、絶えず巡っていく流れを表す。",
      myth: "高龗神・闇龗神は、水と深く結びつく神です。\n\n貴船神社では、高龗神を水の供給を司る神として祀っています。\n\n毛谷黒龍神社では、高龗神と闇龗神の二柱を御祭神として祀り、\n\n「人間生活の根源である水を司る神」\n\nとして信仰しています。\n\n水は、一つの場所に留まり続けません。\n\n雨として降り、\n山へ染み込み、\n湧水となり、\n川となって流れ、\n海へ注ぎ、\nやがて再び空へ戻っていきます。\n\nその循環によって、植物も、動物も、人も生きています。",
      connectionHeading: "なぜ「循環」と結びつくのか",
      connection: "水は、\n\n「流れているからこそ清らかさを保つもの」\n\nでもあります。\n\n受け取る。\n流す。\n満たす。\nまた巡る。\n\n人生にも同じ流れがあります。\n\n誰かから受け取ったものを、今度は自分が誰かへ渡す。\n\n終わったものが、別の形で次の始まりになる。\n\n「國護り」では高龗神・闇龗神を、\n\n命や恵みが一つの場所に止まらず巡り続ける「循環」\n\nの象徴としています。\n\n抱え込むだけでは、流れは止まります。\n\n必要なものを受け取り、\n役目を終えたものを流す。\n\nそうすることで、また新しいものが入ってくるのです。",
      sacredSites: [{ mark: "★", name: "貴船神社", location: "京都府京都市" }, { mark: "★", name: "毛谷黒龍神社", location: "福井県福井市" }, { mark: "○", name: "丹生川上神社", location: "奈良県" }], sacredSitesNote: "",
    },
    "40": {
      en: {
        title: "Union of Heaven and Earth", deityName: "Amaterasu Omikami", deityNote: "The great solar deity of Japanese mythology and ruler of Takamagahara.", meaningTitle: "Union of Heaven and Earth",
        meaning: "Bringing inner awareness and outer reality into alignment.\n\nThis card represents integration—the point at which thought, spirit, intention, action, and lived reality begin to move together as one.",
        myth: "Amaterasu Omikami was born when Izanagi no Mikoto purified himself after returning from Yomi.\n\nWhen he washed his left eye, Amaterasu appeared.\n\nIzanagi rejoiced at her birth and entrusted her with the rule of Takamagahara, the Plain of High Heaven.\n\nAmaterasu later became central to several of the most important myths in Japanese tradition.\n\nAfter conflict with Susanoo no Mikoto, she withdrew into the Heavenly Rock Cave.\n\nWithout her light, darkness spread through Heaven and Earth.\n\nThrough the cooperation of many deities, Amaterasu eventually emerged, and light returned.\n\nLater, Amaterasu and Takagi no Kami became central figures in the decision to send the heavenly lineage down to the earthly realm.\n\nNinigi no Mikoto was entrusted with this mission and descended from Takamagahara with sacred treasures and divine companions.\n\nThrough these myths, Amaterasu is connected not only with the heavenly realm, but also with the movement of sacred order, light, grain, and divine authority into the human world.",
        connectionHeading: "Why This Deity Represents “Union of Heaven and Earth”",
        connection: "Throughout Kunimamori, “Heaven” can be understood symbolically as:\n\ninner truth,\nspirit,\nintention,\npossibility,\nand awareness.\n\n“Earth” can be understood as:\n\nthe body,\naction,\ndaily life,\nrelationships,\nand physical reality.\n\nIf these remain separated, something is incomplete.\n\nAn intention that never becomes action stays in the mind.\n\nAction without inner alignment can lose its meaning.\n\nAmaterasu connects the heavenly realm with the earthly world through light, sacred treasures, grain, and the descent of the heavenly lineage.\n\nFor this reason, in Kunimamori, Amaterasu Omikami represents:\n\nthe moment when what is within you and how you live in the world come into alignment.\n\nThis final card is not about escaping ordinary life in order to become spiritual.\n\nIt is about allowing what you know within yourself to take form in the way you actually live.\n\nHeaven and Earth meet when inner truth becomes lived reality.",
        sacredSites: [{ mark: "★", name: "Kotai Jingu, Ise Jingu", location: "Ise, Mie" }, { mark: "○", name: "Amano Iwato Jinja", location: "Takachiho, Miyazaki" }, { mark: "○", name: "Hinomisaki Jinja", location: "Izumo, Shimane" }], sacredSitesNote: "",
      },
      id: "40", number: "40", special: false, title: "天地合一", deityName: "天照大御神", reading: "あまてらすおおみかみ", deityNote: "", meaningTitle: "天地合一",
      meaning: "自分の内側と外側、精神と現実、受け取るものと行動するものが一つにつながること。\nこれまでの経験が統合され、自分自身として世界の中に立つことを表す、40枚の最終カード。",
      myth: "天照大御神は、伊邪那岐命が黄泉国から帰り、禊を行った際に生まれた三貴子の一柱です。\n\n左目を洗った時に誕生し、伊邪那岐命から高天原を治めることを任されました。\n\nその後、須佐之男命の行動によって天岩戸へ籠もります。\n\n天照大御神が姿を隠すと、世界は闇に包まれます。\n\nしかし八百万の神々の働きによって再び岩戸の外へ出ると、\n\n「世界に光と秩序が戻りました。」\n\nさらに天孫降臨では、孫の邇邇芸命を地上へ送り、\n\n八咫鏡、八尺瓊勾玉、草薙剣を授けます。\n\nそして稲穂を授け、この地で国を治め、繁栄させるよう命じました。\n\nつまり天照大御神は、高天原という天の世界だけに留まる神ではありません。\n\n天から地上へ神宝や稲を授け、\n天と地をつなぐ役割を担っています。",
      connectionHeading: "なぜ「天地合一」と結びつくのか",
      connection: "40枚の最後にある「天地合一」は、\n\nただ成功した、願いが叶った、という意味ではありません。\n\nここまで、\n\n始まり、\n創造し、\n選び、\n動き、\n愛し、\n迷い、\n失い、\n終わり、\n解放し、\n再生してきました。\n\nそのすべてを、\n\n「これも自分の人生だった」\n\nと一つに統合する段階です。\n\n天照大御神は天の神でありながら、その光は地上まで照らします。\n\nそして天孫降臨によって、天のものを地上へ受け渡します。\n\nだから「國護り」では、\n\n天＝目に見えない意志や精神\n地＝目に見える現実や行動\n\nその二つが結ばれた状態を「天地合一」としています。\n\n思っていることと、やっていること。\n内側の自分と、外側の生き方。\n\nそれが一致した時、\n\n人は自分自身の光で世界に立つことができます。",
      sacredSites: [{ mark: "★", name: "伊勢神宮 皇大神宮・内宮", location: "三重県伊勢市" }, { mark: "○", name: "天岩戸神社", location: "宮崎県高千穂町" }, { mark: "○", name: "日御碕神社", location: "島根県出雲市" }], sacredSitesNote: "",
    },
    "41": {
      en: {
        title: "Sacred Oath", episodeName: "The Ukei at Amano-Yasukawara",
        characters: [{ name: "Amaterasu Omikami" }, { name: "Susanoo no Mikoto" }], charactersNote: "The ritual also gives rise to:\nMunakata Sanjoshin\nand five male deities", meaningTitle: "Sacred Oath",
        meaning: "Proving your intention through both words and actions.\n\nThis card represents commitment, accountability, and the willingness to stand behind what you say.",
        myth: "When Susanoo no Mikoto came to Takamagahara, Amaterasu Omikami became suspicious of his intentions.\n\nShe feared that he might be coming to seize control of the heavenly realm.\n\nSusanoo insisted that he had no such intention.\n\nTo prove it, the two performed a ritual oath known as ukei.\n\nDuring this sacred act, they exchanged and transformed one another’s sacred objects.\n\nFrom Susanoo’s sword, when it was received and transformed by Amaterasu, the Three Goddesses of Munakata were born.\n\nFrom Amaterasu’s jewels, when they were received and transformed by Susanoo, five male deities were born.\n\nThe Kojiki and Nihon Shoki preserve different versions of the details and of how the result of the oath was interpreted.\n\nWhat remains clear is that the ritual was used to test and reveal intention.",
        sceneExplanation: "Suspicion exists.\n\nWords alone are not enough.\n\nA ritual is performed.\n\nBoth deities place something of themselves into the process.\n\nNew divine beings are born.\n\nThe oath becomes something visible through action and consequence.",
        connectionHeading: "Why This Story Represents “Sacred Oath”",
        connection: "A promise has meaning only when your actions support it.\n\nSusanoo did not simply say:\n\n“Trust me.”\n\nHe entered into a ritual that placed his words under judgment.\n\nFor this reason, in Kunimamori, this story represents:\n\nthe moment when words become something you are willing to stand behind.\n\nA true oath asks:\n\n“Am I living in a way that allows me to trust my own words?”",
        storyMessage: "Commitment becomes real when your actions and your words point in the same direction.\n\nSometimes the most important question is not whether other people believe you.\n\nIt is whether you can believe yourself.",
        sacredSites: [{ mark: "★", name: "Munakata Taisha", location: "Munakata, Fukuoka" }], sacredSitesNote: "",
      },
      id: "41", number: "41", special: true, title: "誓約", episodeName: "天安河のうけい",
      characters: [{ name: "天照大御神", reading: "あまてらすおおみかみ" }, { name: "須佐之男命", reading: "すさのおのみこと" }],
      charactersNote: "そして、この誓約から宗像三女神と五柱の男神が誕生します。", meaningTitle: "誓約",
      meaning: "自分の言葉や意思が本物であることを、行動によって示すこと。\n\nただ約束するだけではなく、自分の真意を明らかにし、その結果を引き受けることを表す。",
      myth: "須佐之男命は、根の国へ向かう前に姉の天照大御神へ別れを告げようと、高天原へ向かいました。\n\nところが須佐之男命が近づく勢いはすさまじく、山や川が鳴り、大地が揺れるほどでした。\n\n天照大御神は、\n\n「高天原を奪いに来たのではないか」\n\nと疑い、武装して須佐之男命を迎えます。\n\n須佐之男命は、自分に邪心がないことを示すため、「誓約（うけい）」を行うことを提案しました。\n\n二柱は互いの持ち物を用います。\n\n天照大御神が須佐之男命の剣を受け取り、それを噛み砕いて息を吹き出すと、三柱の女神が生まれました。\n\nこれが後の宗像三女神です。\n\n続いて須佐之男命が天照大御神の勾玉を受け取り、噛み砕いて息を吹き出すと、五柱の男神が生まれました。\n\nこの誓約によって、須佐之男命は自らの真意を示します。\n\n※『古事記』『日本書紀』には、この誓約の勝敗条件などについて伝承の違いがあります。",
      sceneExplanation: "二柱の間には最初、強い疑いがありました。\n\n須佐之男命が「私は悪意を持っていない」と言うだけでは、天照大御神は信じません。\n\nそこで、\n\n「言葉ではなく、誓約によって真意を示す」\n\nという行動に出たのです。\n\nそして、その誓約から新しい神々まで誕生しました。",
      connectionHeading: "なぜ「誓約」と結びつくのか",
      connection: "誓約とは、口で約束することより重いもの。\n\n本当にそう思っているのなら、それを何によって示すのか。\n\nこのカードが問うのはそこです。\n\nただ「やります」と言う。\nただ「信じてください」と言う。\n\nそれだけではなく、\n\nその言葉に、自分自身を乗せること。\n\nそして誓いを立てたなら、その先に起こることも引き受ける。\n\n「國護り」では天安河のうけいを、\n\n自分の真意を明らかにし、言葉と行動を一致させる「誓約」\n\nとして描いています。",
      storyMessage: "誰かに信じてもらう前に、\n\n「自分自身が、自分の言葉を信じられる生き方をしているか。」\n\nこのカードは、そこを問いかけます。",
      sacredSites: [{ mark: "★", name: "宗像大社", location: "福岡県宗像市" }], sacredSitesNote: "",
    },
    "42": {
      en: {
        title: "Cooperation", episodeName: "Okuninushi no Okami & Sukunahikona no Mikoto",
        characters: [{ name: "Okuninushi no Okami" }, { name: "Sukunahikona no Mikoto" }], charactersNote: "", meaningTitle: "Cooperation",
        meaning: "Combining different strengths in order to accomplish something that would be difficult to achieve alone.\n\nThis card represents partnership, mutual support, and the wisdom to accept help.",
        myth: "While Okuninushi no Kami was working to develop the land, a tiny mysterious deity arrived from across the sea.\n\nHe came in a small boat and wore a very small garment.\n\nNo one initially knew who he was.\n\nWith the help of Kuebiko, his identity was revealed as Sukunabikona no Kami, a child of Kamimusubi no Kami.\n\nKamimusubi instructed Okuninushi to treat Sukunabikona as a brother and work together with him.\n\nFrom then on, the two cooperated in the development and establishment of the land.\n\nOkuninushi was a great deity associated with rulership and nation-building.\n\nSukunabikona was extraordinarily small and later became closely associated with medicine and healing.\n\nThey were very different.\n\nAnd precisely because of those differences, they could support the work in different ways.",
        sceneExplanation: "Okuninushi is carrying a great responsibility.\n\nA small and unexpected companion appears.\n\nHis identity is revealed.\n\nThe two are told to work together.\n\nThe work of building the land continues through partnership rather than through one deity acting alone.",
        connectionHeading: "Why This Story Represents “Cooperation”",
        connection: "Cooperation does not mean that everyone must have the same abilities.\n\nIn fact, difference is often what makes cooperation valuable.\n\nOne person may see what another cannot.\n\nOne may have strength where another has knowledge.\n\nFor this reason, in Kunimamori, Okuninushi and Sukunahikona represent:\n\nthe power created when different strengths are joined.\n\nAccepting help is not weakness.\n\nSometimes it is the choice that makes a larger result possible.",
        storyMessage: "You do not have to do everything alone.\n\nThe person who helps you may not look like the kind of person you expected.\n\nDifferent strengths can become complementary when they are allowed to work together.",
        sacredSites: [{ mark: "★", name: "Oarai Isosaki Jinja", location: "Oarai, Ibaraki" }, { mark: "○", name: "Sakatsura Isosaki Jinja", location: "Hitachinaka, Ibaraki" }], sacredSitesNote: "",
      },
      id: "42", number: "42", special: true, title: "協力", episodeName: "大国主大神 × 少彦名命",
      characters: [{ name: "大国主大神", reading: "おおくにぬしのおおかみ" }, { name: "少彦名命", reading: "すくなひこなのみこと" }], charactersNote: "", meaningTitle: "協力",
      meaning: "一人では成し遂げられないことを、異なる力を持つ者同士が力を合わせて形にすること。\n\n同じであることではなく、互いの違いを生かすことを表す。",
      myth: "大国主神が出雲の御大の岬にいた時、海の向こうから非常に小さな神がやってきました。\n\n小さな船に乗って現れたその神が誰なのか、最初は誰にも分かりません。\n\n久延毘古の助言によって、その正体が神産巣日神の子、少名毘古那神であることが分かります。\n\n神産巣日神は、\n\n「大国主神と少名毘古那神が力を合わせ、葦原中国を作り固めるように」\n\n命じました。\n\nこうして、体も性格も異なる二柱の神による国作りが始まります。\n\n『古事記』は具体的な国作りの内容を詳しく語りませんが、『日本書紀』の異伝には、二柱が人や家畜の病を治療する方法などを定めたという伝承もあります。\n\nそして国作りを進めた後、少彦名神は常世国へ去っていきます。",
      sceneExplanation: "大国主神は大きな国作りを担う神。\n\n一方、少彦名神は手のひらに乗るほど小さな神として描かれます。\n\nでも、大きい方だけでは国作りは完成しませんでした。\n\n神産巣日神は、この二柱を組ませます。\n\n違うもの同士だからこそ、できることがあったのです。",
      connectionHeading: "なぜ「協力」と結びつくのか",
      connection: "協力とは、\n\n「同じ考えの人を集めること」\n\nではありません。\n\n自分にできること。\n相手にできること。\n\nそれぞれが違うから、一緒にやる意味があります。\n\n「國護り」では大国主神と少彦名神を、\n\n違う力を持つ二人が並び、一つのものを作り上げる「協力」\n\nの象徴としています。\n\n一人で全部できることだけが強さではありません。\n\n誰かの力を借りられることも、立派な力です。",
      storyMessage: "「自分でやった方が早い」と思うことがあります。\n\nでも、自分一人では生まれないものもあります。\n\n誰かと力を合わせることで、自分の力まで大きくなることがあります。",
      sacredSites: [{ mark: "★", name: "大洗磯前神社", location: "茨城県大洗町" }, { mark: "○", name: "酒列磯前神社", location: "茨城県ひたちなか市" }], sacredSitesNote: "",
    },
    "43": {
      en: {
        title: "Trial", episodeName: "Konohanasakuya-hime, Ninigi no Mikoto & the Three Children",
        characters: [{ name: "Konohanasakuya-hime no Mikoto" }, { name: "Ninigi no Mikoto" }], charactersNote: "Their three children:\nHoderi no Mikoto\nHosuseri no Mikoto\nHoori no Mikoto", meaningTitle: "Trial",
        meaning: "A difficult experience that reveals what is true, what is strong, and what you are capable of carrying through.\n\nThis card represents being tested and discovering your own strength through the process.",
        myth: "After Ninigi no Mikoto married Konohanasakuya-hime, she became pregnant after only one night.\n\nNinigi doubted whether the children were truly his.\n\nKonohanasakuya-hime responded by making a solemn pledge.\n\nShe entered a birthing hut, sealed the entrance, and set the building on fire.\n\nShe declared that if the children were not truly the children of Ninigi, they would not be born safely.\n\nBut if they were truly his divine children, they would survive even within the flames.\n\nInside the burning hut, she safely gave birth to three children.\n\nThrough this act, she proved the truth of her words.",
        sceneExplanation: "Doubt is directed at Konohanasakuya-hime.\n\nShe chooses not merely to argue.\n\nShe places herself within an extreme test.\n\nFire surrounds her.\n\nShe gives birth safely.\n\nHer truth becomes impossible to deny.",
        connectionHeading: "Why This Story Represents “Trial”",
        connection: "A trial places pressure on what already exists.\n\nUnder pressure, weakness may become visible.\n\nBut so may strength.\n\nKonohanasakuya-hime does not become strong because the trial exists.\n\nThe trial reveals the strength that was already within her.\n\nFor this reason, in Kunimamori, this scene represents:\n\nthe test through which truth and ability become visible.\n\nA difficult period does not automatically mean punishment.\n\nSometimes it becomes the moment when you discover:\n\n“I was capable of more than I knew.”",
        storyMessage: "A trial can reveal qualities that ordinary circumstances never required you to see.\n\nYou may come out of difficulty with a clearer understanding of your own strength.",
        sacredSites: [{ mark: "★", name: "Fujisan Hongu Sengen Taisha", location: "Fujinomiya, Shizuoka" }, { mark: "○", name: "Kitaguchi Hongu Fuji Sengen Jinja", location: "Fujiyoshida, Yamanashi" }], sacredSitesNote: "",
      },
      id: "43", number: "43", special: true, title: "試練", episodeName: "木花咲耶姫 × 邇邇芸命＋三御子",
      characters: [{ name: "木花咲耶姫命", reading: "このはなさくやひめのみこと" }, { name: "邇邇芸命", reading: "ににぎのみこと" }, { name: "火照命", reading: "ほでりのみこと" }, { name: "火須勢理命", reading: "ほすせりのみこと" }, { name: "火遠理命", reading: "ほおりのみこと" }], charactersNote: "", meaningTitle: "試練",
      meaning: "自分の真価が問われる出来事。\n\n避けたい困難の中で、自分の強さや真実が明らかになることを表す。",
      myth: "邇邇芸命と結婚した木花咲耶姫は、一夜の契りで身ごもります。\n\nところが邇邇芸命は、\n\n「一夜で身ごもるはずがない。私の子ではなく、国つ神の子ではないのか」\n\nと疑いました。\n\n木花咲耶姫にとって、それは自らの貞節を疑われる非常に厳しい言葉でした。\n\nそこで彼女は、自分の言葉が真実であることを証明するために誓約を行います。\n\n戸口のない産屋を造り、中へ入って土で塞ぎ、出産の時に自ら火を放ちました。\n\nそして、\n\n「本当に邇邇芸命の御子なら、炎の中でも無事に生まれる」\n\nという誓いを立てます。\n\n激しく燃える炎の中で、木花咲耶姫は三柱の御子を無事に産みました。\n\nそれによって、自らの言葉が真実であったことを証明したのです。",
      sceneExplanation: "木花咲耶姫は、「疑われる」という試練を受けました。\n\nしかも、誰かに説明して終わりではありません。\n\n自分自身が危険の中へ入り、その真実を証明するという非常に強烈な物語です。\n\nそして火の中から、三つの新しい命が誕生します。",
      connectionHeading: "なぜ「試練」と結びつくのか",
      connection: "試練とは、\n\n「あなたを苦しめるために起こるもの」\n\nという意味だけではありません。\n\nその出来事によって、\n\n自分でも知らなかった強さが現れること\n\nがあります。\n\n木花咲耶姫は火に耐えただけではありません。\n\nその火の中で、命を生みました。\n\nだから「國護り」の「試練」は、\n\n困難の中で、自分の真実と力が明らかになること\n\nを表します。",
      storyMessage: "「なぜこんなことが起きるの？」\n\nと思う時があります。\n\nでも、そこを越えた後で初めて、\n\n「私はここまでできる人だったんだ」\n\nと知ることもあります。",
      sacredSites: [{ mark: "★", name: "富士山本宮浅間大社", location: "静岡県富士宮市" }, { mark: "○", name: "北口本宮冨士浅間神社", location: "山梨県富士吉田市" }], sacredSitesNote: "",
    },
    "44": {
      en: {
        title: "Guidance", episodeName: "Ninigi no Mikoto, Sarutahiko no Okami & Ame-no-Uzume no Mikoto",
        characters: [{ name: "Ninigi no Mikoto" }, { name: "Sarutahiko no Okami" }, { name: "Ame-no-Uzume no Mikoto" }], charactersNote: "", meaningTitle: "Guidance",
        meaning: "Receiving direction, signs, or support that help you recognize the path ahead.\n\nThis card represents being shown the way without giving away your own responsibility to walk it.",
        myth: "When Ninigi no Mikoto was preparing to descend from Takamagahara to the earthly realm, a powerful mysterious deity appeared at the heavenly crossroads.\n\nHis presence was so radiant that it seemed to illuminate both Heaven and Earth.\n\nAmaterasu Omikami and Takagi no Kami sent Ame-no-Uzume to ask who he was.\n\nThe deity revealed himself as Sarutahiko.\n\nHe explained that he had come to guide the heavenly grandson along the path to the earth.\n\nSarutahiko then led Ninigi toward his destination.\n\nAfterward, Ame-no-Uzume accompanied Sarutahiko toward the region associated with his home.",
        sceneExplanation: "A journey is about to begin.\n\nA mysterious figure appears at the crossroads.\n\nAme-no-Uzume approaches and identifies him.\n\nHe reveals that he has come as a guide.\n\nNinigi receives direction and continues the descent.",
        connectionHeading: "Why This Story Represents “Guidance”",
        connection: "Guidance does not mean that another person lives your life for you.\n\nSarutahiko shows the path.\n\nBut Ninigi is still the one who must descend and fulfill the journey.\n\nFor this reason, in Kunimamori, this story represents:\n\nthe sign or presence that helps you recognize where to go next.\n\nSometimes guidance appears as a person.\n\nSometimes as information.\n\nSometimes as a coincidence that catches your attention.\n\nThe guide may point.\n\nBut you still choose whether to walk.",
        storyMessage: "You do not need to know the entire road before you begin.\n\nSometimes the next direction appears only when you arrive at the crossroads.\n\nReceive guidance without surrendering your own choice.",
        sacredSites: [{ mark: "★", name: "Sarutahiko Jinja", location: "Ise, Mie" }, { mark: "★", name: "Tsubaki Grand Shrine", location: "Suzuka, Mie" }, { mark: "○", name: "Sarume Jinja", location: "Ise, Mie" }], sacredSitesNote: "",
      },
      id: "44", number: "44", special: true, title: "導き", episodeName: "邇邇芸命 × 猿田彦大神 × 天宇受売命",
      characters: [{ name: "邇邇芸命", reading: "ににぎのみこと" }, { name: "猿田彦大神", reading: "さるたひこのおおかみ" }, { name: "天宇受売命", reading: "あめのうずめのみこと" }], charactersNote: "", meaningTitle: "導き",
      meaning: "自分だけではまだ分からない道に、進むための手がかりや案内役が現れること。\n\n導きを受け取ることと、自分自身もその道を歩くことを表す。",
      myth: "邇邇芸命が高天原から地上へ降りようとした時、\n\n天地の分かれ道である天の八衢に、不思議な神が立っていました。\n\n上は高天原を、下は葦原中国を照らすほどの存在です。\n\n「いったい何者なのか」\n\nそこで天照大御神と高木神は、天宇受売命を向かわせます。\n\n天宇受売命が問いかけると、その神は自らを猿田毘古神と名乗りました。\n\nそして、\n\n「天孫が降りてくると聞いたので、その道を先導するために迎えに来た」\n\nと告げます。\n\n猿田彦大神は邇邇芸命を地上へ導き、天孫降臨の先導者となりました。\n\nその後、天宇受売命は猿田彦大神をその故郷まで送る役目も担います。",
      sceneExplanation: "これから全く新しい土地へ降りようとする邇邇芸命の前に、\n\n「道を知っている存在」\n\nが現れました。\n\nでも、ただ猿田彦大神が全部やってしまう物語ではありません。\n\n天宇受売命が、\n\n「あなたは誰なのか」\n\nと確かめる役割を果たします。\n\nそして邇邇芸命自身が、その導きを受けて地上へ進みます。",
      connectionHeading: "なぜ「導き」と結びつくのか",
      connection: "導きは、\n\n「誰かが自分の人生を代わりに決めてくれること」\n\nではありません。\n\n方向を示してくれる人。\n偶然目にした言葉。\nふと訪れた場所。\nなぜか気になるもの。\n\nそこに道しるべが現れることがあります。\n\nでも最後に歩くのは、自分です。\n\nだから「國護り」ではこの天孫降臨の場面を、\n\n道を示す存在と、その導きを受け取って進む存在が出会う「導き」\n\nとして描いています。",
      storyMessage: "道が分からない時、すべてを自分だけで知っている必要はありません。\n\n次の一歩だけを教えてくれる存在が現れることがあります。\n\n大切なのは、そのサインに気づくことです。",
      sacredSites: [{ mark: "★", name: "猿田彦神社", location: "三重県伊勢市" }, { mark: "★", name: "椿大神社", location: "三重県鈴鹿市" }, { mark: "○", name: "佐瑠女神社", location: "三重県伊勢市" }], sacredSitesNote: "",
    },
    "45": {
      en: {
        title: "Awakening", episodeName: "Ama-no-Iwato",
        characters: [{ name: "Amaterasu Omikami" }, { name: "Ame-no-Uzume no Mikoto" }, { name: "Ame-no-Tajikarao no Kami" }, { name: "Omoikane no Kami" }], charactersNote: "Sacred objects including:\nYata-no-Kagami\nYasakani-no-Magatama", meaningTitle: "Awakening",
        meaning: "Becoming aware of something that had been hidden from your own view.\n\nThis card represents opening your awareness, recognizing yourself more clearly, and allowing light to return where there had been darkness.",
        myth: "After being deeply distressed by the actions of Susanoo no Mikoto, Amaterasu Omikami withdrew into the Heavenly Rock Cave.\n\nShe sealed the entrance.\n\nWithout the sun goddess, darkness spread through both Takamagahara and the earthly realm.\n\nThe countless deities gathered and asked Omoikane no Kami, a deity of wisdom, to devise a plan.\n\nSacred jewels and a mirror were prepared.\n\nAme-no-Uzume began to dance outside the cave.\n\nThe gods laughed loudly.\n\nInside the darkness, Amaterasu heard them.\n\nCuriosity arose.\n\nShe wondered why everyone was celebrating when she believed the world should be dark without her.\n\nShe opened the rock door slightly.\n\nThe gods showed her the mirror.\n\nAmaterasu looked and saw the brilliant reflection before her.\n\nAs she moved closer, Ame-no-Tajikarao pulled her out of the cave.\n\nLight returned to the world.",
        sceneExplanation: "Darkness has become complete.\n\nThen laughter is heard.\n\nCuriosity appears.\n\nThe door opens only a little.\n\nA mirror reveals an image.\n\nAmaterasu comes out.\n\nThe world becomes bright again.",
        connectionHeading: "Why This Story Represents “Awakening”",
        connection: "Awakening does not always begin with a dramatic revelation.\n\nSometimes it begins with one small question:\n\n“What is happening outside?”\n\nThat tiny curiosity becomes an opening.\n\nThrough the mirror, Amaterasu encounters her own image.\n\nThe hidden light returns to the world.\n\nFor this reason, in Kunimamori, Ama-no-Iwato represents:\n\nthe moment when awareness opens and something you could not see before becomes visible.\n\nOpportunity creates the opening.\n\nTruth becomes visible in the mirror.\n\nAnd light returns.",
        storyMessage: "Awakening may begin with curiosity rather than certainty.\n\nYou do not need to understand everything at once.\n\nSometimes opening the door just a little is enough for the next truth to become visible.",
        sacredSites: [{ mark: "★", name: "Amano Iwato Jinja", location: "Takachiho, Miyazaki" }, { mark: "○", name: "Kotai Jingu, Ise Jingu", location: "Ise, Mie" }], sacredSitesNote: "",
      },
      id: "45", number: "45", special: true, title: "覚醒", episodeName: "天岩戸",
      characters: [{ name: "天照大御神", reading: "あまてらすおおみかみ" }, { name: "天宇受売命", reading: "あめのうずめのみこと" }, { name: "天手力男神", reading: "あめのたぢからおのかみ" }, { name: "思金神", reading: "おもいかねのかみ" }], charactersNote: "そして八百万の神々", meaningTitle: "覚醒",
      meaning: "閉じていた意識が開き、それまで見えていなかったものに気づくこと。\n\n外からのきっかけと、自分自身を見つめることによって、新しい光の中へ出ていくことを表す。",
      myth: "須佐之男命の激しい行動によって心を痛めた天照大御神は、天岩戸へ籠もります。\n\n太陽神が姿を隠したため、高天原も葦原中国も闇に包まれました。\n\n困った八百万の神々は天安河原へ集まり、どうすれば天照大御神を外へ出せるか相談します。\n\n思金神の知恵によって、さまざまな準備が行われました。\n\n八尺瓊勾玉。\n八咫鏡。\n天宇受売命の舞。\n\n天宇受売命が神がかりして舞うと、八百万の神々は大笑いします。\n\n岩戸の中にいる天照大御神は、\n\n「私が隠れて世界は暗いはずなのに、なぜ皆は楽しそうなのだろう」\n\nと不思議に思い、岩戸を少し開きます。\n\nそして外に置かれた鏡に、自分自身の光り輝く姿を見ます。\n\nさらに外を覗こうとしたその瞬間、天手力男神がその手を取り、天照大御神を岩戸の外へ導き出しました。\n\nこうして世界に再び光が戻ります。",
      sceneExplanation: "天照大御神は、誰かに無理やり扉を壊されて突然外へ出たわけではありません。\n\n最初に起きたのは、\n\n「外では何が起きているのだろう？」\n\nという小さな関心でした。\n\nそのため、自分自身で岩戸を少し開きます。\n\nそして鏡に映る自分を見る。\n\nそこへ天手力男神の力が加わり、ついに外へ出ます。",
      connectionHeading: "なぜ「覚醒」と結びつくのか",
      connection: "覚醒は、ある日突然、別人になることではありません。\n\n最初はほんの少し、\n\n「今まで自分が信じていた世界だけが、すべてではないのかもしれない」\n\nと思うところから始まります。\n\n岩戸を少し開く。\n外を見る。\n鏡を見る。\n自分を見る。\n\nそして、自分自身の光に気づく。\n\nだから「國護り」では天岩戸を、\n\n閉ざしていた意識が開き、自分自身の光をもう一度認識する「覚醒」\n\nとして描いています。",
      storyMessage: "誰かが外から、\n\n「出てきなさい」\n\nと言うだけでは、人は変われないことがあります。\n\nでも、自分自身が\n\n「外を見てみたい」\n\nと思った瞬間、岩戸はほんの少し開きます。\n\nその小さな隙間から、覚醒は始まります。",
      sacredSites: [{ mark: "★", name: "天岩戸神社", location: "宮崎県高千穂町" }, { mark: "○", name: "伊勢神宮 皇大神宮・内宮", location: "三重県伊勢市" }], sacredSitesNote: "",
    },
    "46": {
      en: {
        title: "Mission", episodeName: "Amaterasu Omikami, Takagi no Kami & Ninigi no Mikoto",
        characters: [{ name: "Amaterasu Omikami" }, { name: "Takagi no Kami" }, { name: "Ninigi no Mikoto" }, { name: "Ame-no-Oshihomimi no Mikoto" }], charactersNote: "", meaningTitle: "Mission",
        meaning: "Recognizing and accepting a role that has been entrusted to you.\n\nThis card represents responsibility, calling, and the moment when something becomes more than a personal wish and begins to feel like a task you are meant to carry forward.",
        myth: "After the Transfer of the Land had been completed, the heavenly deities prepared for the descent of the heavenly lineage to the earthly realm.\n\nAt first, Ame-no-Oshihomimi no Mikoto was chosen for this role.\n\nHowever, after Ninigi no Mikoto was born, Ame-no-Oshihomimi suggested that his son should descend instead.\n\nAmaterasu Omikami and Takagi no Kami then entrusted Ninigi with the mission of descending to Ashihara-no-Nakatsukuni and carrying the heavenly lineage into the earthly world.\n\nNinigi did not descend alone.\n\nHe was accompanied by several deities, including Ame-no-Koyane, Futodama, Ame-no-Uzume, Ishikoridome, and Tamanooya.\n\nSacred treasures were also entrusted to the descent.\n\nNinigi then left the heavenly realm and entered the earthly world.",
        sceneExplanation: "A role has been prepared.\n\nThe first person chosen passes it forward.\n\nA new generation receives the task.\n\nNinigi accepts the responsibility.\n\nHe leaves the heavenly realm and begins the descent.\n\nThe mission becomes real through action.",
        connectionHeading: "Why This Story Represents “Mission”",
        connection: "A mission is not always something you invent for yourself.\n\nSometimes it arrives through circumstance.\n\nA role is offered.\nA responsibility keeps returning.\nSomeone asks something of you.\nA path repeatedly draws your attention.\n\nNinigi receives a task that existed before he personally chose it.\n\nBut once he accepts it, the mission becomes his own.\n\nFor this reason, in Kunimamori, this story represents:\n\nthe moment when an entrusted role becomes something you choose to carry.\n\nA mission is not simply:\n\n“What do I want to do?”\n\nIt can also be:\n\n“What has come into my hands that only I can carry forward from here?”",
        storyMessage: "You may not recognize your mission at the beginning.\n\nSometimes it becomes visible only when you look back.\n\nThe places you were drawn to,\nthe experiences you repeatedly faced,\nthe things people kept asking you for—\n\nthey may have been pointing in the same direction all along.",
        sacredSites: [{ mark: "★", name: "Kirishima Jingu", location: "Kirishima, Kagoshima" }, { mark: "○", name: "Takachiho Jinja", location: "Takachiho, Miyazaki" }], sacredSitesNote: "",
      },
      id: "46", number: "46", special: true, title: "使命", episodeName: "天照大御神・高木神 × 邇邇芸命",
      characters: [{ name: "天照大御神", reading: "あまてらすおおみかみ" }, { name: "高木神", reading: "たかぎのかみ", note: "高御産巣日神の別名" }, { name: "邇邇芸命", reading: "ににぎのみこと" }], charactersNote: "", meaningTitle: "使命",
      meaning: "自分に託された役割を受け取り、その役割を現実の世界で果たしていくこと。\n\n誰かに言われたから従うのではなく、自分が担うべきものとして引き受け、行動へ移すことを表す。",
      myth: "高天原の神々による葦原中国の平定が終わると、いよいよ地上を治める者を送り出す時が来ます。\n\nもともとその役割を担う予定だったのは、天照大御神の御子である天忍穂耳命でした。\n\nしかし天忍穂耳命は、自分に邇邇芸命という御子が生まれたため、\n\n「この子を地上へ降ろすのがよい」\n\nと申し上げます。\n\nこうして天照大御神と高木神は、邇邇芸命に葦原中国へ天降る役割を託しました。\n\n邇邇芸命には、天児屋命、布刀玉命、天宇受売命、伊斯許理度売命、玉祖命らが従います。\n\nさらに、\n\n八尺瓊勾玉、\n八咫鏡、\n草薙剣\n\nという神宝も授けられます。\n\nそして邇邇芸命は、高天原を離れ、筑紫の日向の高千穂の久士布流多気へ天降りました。",
      sceneExplanation: "邇邇芸命は、軽い頼み事をされたわけではありません。\n\nこれまで高天原の神々が長い時間をかけて進めてきた葦原中国の平定。\n\nその先を託されたのです。\n\nさらに神宝や多くの神々まで伴わせて送り出されたことからも、この天孫降臨が大きな役割を持つ出来事だったことが分かります。",
      connectionHeading: "なぜ「使命」と結びつくのか",
      connection: "使命とは、\n\n「自分がやりたいことだけ」\n\nとは少し違います。\n\nなぜか自分のところへ回ってきた役割。\n自分だからできること。\n誰かから受け取ったものを、次へつなぐ役割。\n\nそういうものがあります。\n\n邇邇芸命も、自分で高天原から出て行くことを思いついたのではありません。\n\n前の世代から託されたものを受け取り、地上へ向かいました。\n\nだから「國護り」ではこの天孫降臨を、\n\n受け取った役割を自分の人生として引き受ける「使命」\n\nとして描いています。",
      storyMessage: "使命は、最初から\n\n「これが私の使命です！」\n\nと分かるものばかりではありません。\n\n何度も同じことを頼まれる。\nなぜかその場所へ導かれる。\n自分の経験が誰かの役に立つ。\n\nあとから振り返った時、\n\n「ずっとここへ向かっていたのかもしれない」\n\nと気づくこともあります。",
      sacredSites: [{ mark: "★", name: "霧島神宮", location: "鹿児島県霧島市" }, { mark: "○", name: "高千穂神社", location: "宮崎県高千穂町" }], sacredSitesNote: "",
    },
    "47": {
      en: {
        title: "Fruition", episodeName: "Okuninushi no Okami & Omononushi no Okami",
        characters: [{ name: "Okuninushi no Okami" }, { name: "Omononushi no Okami" }], charactersNote: "", meaningTitle: "Fruition",
        meaning: "The point at which long effort, experience, cooperation, and change finally come together as a result.\n\nThis card represents completion, manifestation, and the moment when what has been built over time finally takes form.",
        myth: "Okuninushi no Kami had worked together with Sukunahikona no Kami to develop and establish the land.\n\nBut eventually, Sukunahikona departed for Tokoyo, the Eternal Land.\n\nLeft alone, Okuninushi wondered how he could complete the work of nation-building.\n\nAt that moment, a mysterious divine presence appeared from across the sea, shining brightly.\n\nThe deity told Okuninushi that if he wished to complete the land, he should enshrine this divine presence on a mountain in the eastern part of Yamato.\n\nThat mountain came to be associated with Mount Miwa.\n\nThe deity was Omononushi no Okami.\n\nAfter Omononushi was properly enshrined, the work of establishing the land was able to move toward completion.\n\nIn a version recorded in the Nihon Shoki, Omononushi is identified as the saki-mitama and kushi-mitama of Okuninushi—divine spiritual powers associated with blessing and wondrous accomplishment.",
        sceneExplanation: "A long process has nearly reached its end.\n\nA trusted companion has already departed.\n\nOkuninushi faces uncertainty alone.\n\nThen a new divine presence appears.\n\nA final condition is revealed.\n\nOmononushi is enshrined at Mount Miwa.\n\nThe work of building the land reaches completion.",
        connectionHeading: "Why This Story Represents “Fruition”",
        connection: "Fruition is rarely created by one final action alone.\n\nIt contains everything that came before it.\n\nThe effort.\nThe cooperation.\nThe uncertainty.\nThe losses.\nThe decisions.\nThe things learned along the way.\n\nIn this myth, Okuninushi has already traveled through many stages before the final piece appears.\n\nFor this reason, in Kunimamori, Okuninushi and Omononushi represent:\n\nthe moment when many earlier experiences finally come together and become a completed result.\n\nOne possible reading of the Nihon Shoki tradition is especially meaningful:\n\nthe final power needed to complete the work was described as a spiritual power connected with Okuninushi himself.\n\nSometimes what completes the journey is not something entirely new.\n\nIt is a part of yourself that you are finally ready to recognize and use.",
        storyMessage: "A result does not erase the long road that created it.\n\nWhat appears to be a single moment of success may actually contain years of effort, help, uncertainty, and change.\n\nWhen something finally bears fruit, remember everything that made that moment possible.",
        sacredSites: [{ mark: "★", name: "Omiwa Jinja", location: "Sakurai, Nara" }], sacredSitesNote: "",
      },
      id: "47", number: "47", special: true, title: "結実", episodeName: "大国主大神 × 大物主大神",
      characters: [{ name: "大国主大神", reading: "おおくにぬしのおおかみ" }, { name: "大物主大神", reading: "おおものぬしのおおかみ" }], charactersNote: "", meaningTitle: "結実",
      meaning: "長く続けてきたことが、ようやく一つの形として完成すること。\n\n努力、出会い、協力、迷いなど、途中にあったすべての経験が一つにつながり、成果となって現れることを表す。",
      myth: "大国主神は少彦名神とともに、葦原中国の国作りを進めていました。\n\nしかし、少彦名神は国作りの途中で常世国へ去ってしまいます。\n\n一人になった大国主神は、\n\n「この国を、これからどうやって完成させればよいのだろう」\n\nと思い悩みます。\n\nその時、海を照らしながら近づいてくる神が現れました。\n\nその神は、\n\n「自分を大和の青垣の東の山に祀るなら、国作りを成就させよう」\n\nという趣旨を告げます。\n\nその神こそ、大物主大神でした。\n\n大国主神はその言葉を受け、大物主大神を三輪山に祀ります。\n\nそして国作りは完成へ向かったと伝えられています。\n\n『日本書紀』ではさらに、大物主大神は大国主神に対して、\n\n「自分はあなたの幸魂・奇魂である」\n\nと名乗ったとされています。",
      sceneExplanation: "大国主神の国作りは、ずっと順調だったわけではありません。\n\n仲間だった少彦名神が去り、\n一人になり、\nどう進めればいいのか分からなくなります。\n\nそこへ大物主大神が現れました。\n\nそして大国主神は、その助けを受け入れます。\n\nこうして、長く続いてきた国作りが「成し遂げられる」段階へ入るのです。",
      connectionHeading: "なぜ「結実」と結びつくのか",
      connection: "「結実」とは、突然幸運が降ってきて完成することではありません。\n\nそれまでの過程があります。\n\n最初の一歩。\n誰かとの協力。\n途中の別れ。\n迷った時間。\n\nそれらが全部あった上で、\n\n「ようやく実になる。」\n\nしかも大物主大神が大国主神自身の幸魂・奇魂とされる伝承は、とても象徴的です。\n\n最後に必要だったものが、\n\n「まったく別のどこかから来たものではなく、自分自身の中にある御魂だった」\n\nとも読めます。\n\nだから「國護り」ではこの場面を、\n\n積み重ねてきたものが一つにつながり、形となる「結実」\n\nとして描いています。",
      storyMessage: "途中で、\n\n「もう無理かもしれない」\n\nと思ったことも、完成までの物語の一部かもしれません。\n\n実がなる瞬間だけが「成功」なのではありません。\n\nそこまで続いていたすべてが、実の中に入っています。",
      sacredSites: [{ mark: "★", name: "大神神社", location: "奈良県桜井市" }], sacredSitesNote: "",
    },
    "48": {
      en: {
        title: "Blessing", episodeName: "Oyamatsumi no Kami, Konohanasakuya-hime, Iwanagahime & Ninigi no Mikoto",
        characters: [{ name: "Oyamatsumi no Kami" }, { name: "Konohanasakuya-hime no Mikoto" }, { name: "Iwanagahime" }, { name: "Ninigi no Mikoto" }], charactersNote: "", meaningTitle: "Blessing",
        meaning: "Recognizing and receiving what has been offered to support your life.\n\nThis card represents gifts, protection, prosperity, and the wisdom to notice that a blessing may not always arrive in the form you expected.",
        myth: "After descending to the earthly realm, Ninigi no Mikoto met the beautiful Konohanasakuya-hime and wished to marry her.\n\nHe asked her father, Oyamatsumi no Kami, for permission.\n\nOyamatsumi was delighted.\n\nHe sent Konohanasakuya-hime to Ninigi together with her elder sister, Iwanagahime, and many gifts.\n\nBut Ninigi was frightened by Iwanagahime’s appearance and sent her back.\n\nHe accepted only Konohanasakuya-hime.\n\nOyamatsumi was deeply disappointed.\n\nHe then explained the meaning behind sending both daughters.\n\nHe had offered them with a sacred blessing.\n\nIf Ninigi accepted Iwanagahime, the lives of his descendants would remain firm and enduring like rock.\n\nIf he accepted Konohanasakuya-hime, his descendants would flourish beautifully like blossoms on a tree.\n\nThe two sisters represented two different blessings:\n\nenduring stability,\nand beautiful prosperity.\n\nBecause Iwanagahime was rejected, the Kojiki explains that the lives of Ninigi’s descendants became limited like flowers that bloom beautifully but eventually fall.",
        sceneExplanation: "A blessing is offered.\n\nBut it does not arrive in only one form.\n\nProsperity is offered.\n\nEnduring stability is also offered.\n\nNinigi accepts one.\n\nHe rejects the other.\n\nOnly afterward is the full meaning of the gift explained.",
        connectionHeading: "Why This Story Represents “Blessing”",
        connection: "This is not a story in which everything goes perfectly.\n\nThat is exactly what makes it meaningful as the final card.\n\nA blessing can be offered and still go unrecognized.\n\nSomething may look attractive and easy to accept.\n\nAnother gift may appear inconvenient, unfamiliar, or difficult to appreciate.\n\nBut both may carry value.\n\nFor this reason, in Kunimamori, this story represents:\n\nthe wisdom to recognize what life is offering before deciding too quickly that you do not need it.\n\nA blessing is not completed only because it is given.\n\nIt must also be recognized and received.",
        storyMessage: "Not every blessing looks like a reward.\n\nSome blessings arrive as responsibility.\nSome as protection.\nSome as limitation.\nSome as something you did not immediately want.\n\nBefore saying:\n\n“I do not need this,”\n\nit may be worth asking:\n\n“What gift might be hidden inside this?”\n\nThe final blessing of Kunimamori is not something placed outside you.\n\nIt is also the ability to recognize what has already been placed in your hands.",
        sacredSites: [{ mark: "★", name: "Oyamazumi Jinja", location: "Imabari, Ehime" }, { mark: "○", name: "Fujisan Hongu Sengen Taisha", location: "Fujinomiya, Shizuoka" }], sacredSitesNote: "",
      },
      id: "48", number: "48", special: true, title: "祝福", episodeName: "大山津見神 × 木花咲耶姫 × 石長比売 × 邇邇芸命",
      characters: [{ name: "大山津見神", reading: "おおやまつみのかみ" }, { name: "木花咲耶姫命", reading: "このはなさくやひめのみこと" }, { name: "石長比売", reading: "いわながひめ" }, { name: "邇邇芸命", reading: "ににぎのみこと" }], charactersNote: "", meaningTitle: "祝福",
      meaning: "与えられた恵みを受け取り、自分の人生へ迎え入れること。\n\n幸せとは一つの形だけではなく、繁栄、安定、縁、生命など、さまざまな恵みが差し出されていることに気づくことを表す。",
      myth: "天孫降臨の後、邇邇芸命は笠沙の岬で美しい木花之佐久夜毘売と出会います。\n\n彼女が大山津見神の娘であると知った邇邇芸命は、結婚を申し込みます。\n\n大山津見神はこの求婚を大いに喜びました。\n\nそして木花之佐久夜毘売だけではなく、姉である石長比売も一緒に、たくさんの贈り物を添えて邇邇芸命のもとへ送りました。\n\nところが邇邇芸命は、石長比売を送り返し、木花之佐久夜毘売だけを妻とします。\n\n大山津見神はそれを知り、二柱を一緒に送り出した理由を明かしました。\n\n石長比売には、\n\n「岩のように永く、揺るがない命」\n\nを。\n\n木花之佐久夜毘売には、\n\n「木の花が咲くような繁栄」\n\nを。\n\nその両方を邇邇芸命へ授けるため、二柱をともに送り出したというのです。\n\nしかし石長比売は受け入れられませんでした。\n\nそのため『古事記』は、天孫の命は岩のような永遠性を得られず、花のように限りあるものになったと説明します。",
      sceneExplanation: "ここは、\n\n「祝福なのに全部うまくいった話ではない」\n\nのがとても大切です。\n\n大山津見神が邇邇芸命へ差し出したのは、木花咲耶姫だけではありませんでした。\n\n繁栄と永続性。\n\n二つの祝福だったのです。\n\nでも邇邇芸命は、その片方だけを受け取ります。\n\nつまりこの神話は、\n\n「祝福は差し出されても、それをどう受け取るかは本人に委ねられている」\n\nという物語にも見えます。",
      connectionHeading: "なぜ「祝福」と結びつくのか",
      connection: "「祝福」というと、欲しかったものが手に入ることだと思いがちです。\n\nでも、本当に自分に与えられているものは、\n\n最初から自分が欲しいと思っていた形とは限りません。\n\n華やかなもの。\n地味に見えるもの。\nすぐ価値が分かるもの。\nあとになって大切さに気づくもの。\n\n大山津見神は、\n\n「花の繁栄と、岩の安定」\n\nという二種類の恵みを差し出しました。\n\nだから「國護り」の最後のカード「祝福」は、\n\n自分に与えられているものの価値に気づき、それを受け取ること\n\nを表します。\n\n祝福は、誰かから一方的に与えられて終わりではありません。\n\n受け取って初めて、自分の人生の一部になります。",
      storyMessage: "目の前にあるものを、\n\n「これはいらない」\n\nとすぐに判断していないでしょうか。\n\n今は魅力が分からないものの中に、長い人生を支える祝福が隠れていることがあります。\n\nそして、\n\n「すでに受け取っている祝福に気づくこと。」\n\nそれもまた、祝福を完成させる行為なのです。",
      sacredSites: [{ mark: "★", name: "大山祇神社", location: "愛媛県今治市大三島" }, { mark: "○", name: "富士山本宮浅間大社", location: "静岡県富士宮市" }], sacredSitesNote: "",
    },
  });
})(window.Kunimamori = window.Kunimamori || {});
